select * from jsonb_to_recordset('[{"content_type":"item","slug":"acessorios_capa_anti_optica","payload":{"id":"acessorios_capa_anti_optica","slug":"acessorios_capa_anti_optica","nome":"Capa Anti-Óptica","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"Impede identificação e acompanhamento automático por sistemas de leitura óptica.","descricao_longa":"*Raro*\n\nCapa produzida com tecido inteligente e uma malha de micro-runas que distorce o contorno do usuário e embaralha padrões utilizados por sistemas de reconhecimento visual.\n\nEnquanto estiver usando a capa, câmeras e outros sistemas que dependam de leitura óptica ainda podem perceber que existe alguém presente, mas não conseguem obter uma imagem ou padrão biométrico confiável do usuário.\n\nEsses sistemas também não conseguem identificá-lo automaticamente nem acompanhar sua identidade entre diferentes registros apenas por dados ópticos.\n\nA capa não afeta observação direta, contato físico, sensores térmicos, sensores de fluxo de mana, rastreadores, sinais transmitidos por equipamentos carregados pelo usuário ou qualquer outro método de detecção que não dependa de leitura óptica.\n\n**Espaços:** 2\n\n**Preço:** Ⱥ 1.500\n\nDados da lista de mercadorias:\n- Efeito: Impede identificação e acompanhamento automático por sistemas de leitura óptica.\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 1.500","tags":["loja"],"dados_notion":{"pagina":"ACESSÓRIOS","secao":[],"tipo_tabela":"Equipamento","campos":{"Equipamento":"Capa Anti-Óptica","Efeito":"Impede identificação e acompanhamento automático por sistemas de leitura óptica.","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"1.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f10a1363552818da767c209228ed796","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"5f5cd6e815934306a1405d2d0fd3170f","linhaBlocoId":"1d9d5ff28ec244f8b7b99fb3a1fbc904","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"acessorio","categoria_label":"Acessório","subtipo":null,"estatisticas":{"campos_tabela":{"Equipamento":"Capa Anti-Óptica","Efeito":"Impede identificação e acompanhamento automático por sistemas de leitura óptica.","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"1.500"},"espacos_texto":"2"}},"id":"item:acessorios_capa_anti_optica","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"35005715ed2366510444a77869322934f9e0cb206eb35c896117cb10f903878d"},{"content_type":"item","slug":"acessorios_fivela_de_retorno","payload":{"id":"acessorios_fivela_de_retorno","slug":"acessorios_fivela_de_retorno","nome":"Fivela de Retorno","raridade":"incomum","raridade_label":"Incomum","preco":500,"preco_texto":"500","preco_qualificador":null,"descricao_curta":"Recupera uma vez por cena um objeto que o usuário estava empunhando.","descricao_longa":"*Incomum*\n\nUma fivela atravessada por inscrições cinéticas que reconhecem os objetos mantidos junto ao corpo do usuário.\n\n**Uma vez por cena**, quando um objeto que você estava empunhando for derrubado, arrancado de suas mãos ou lançado para longe, você pode usar uma **Reação** para fazê-lo retornar imediatamente até você, desde que esteja a até 10 m e não exista uma barreira física impedindo o trajeto.\n\nO objeto retorna para uma mão livre. Caso não possua uma, ele cai aos seus pés.\n\nA fivela não pode retirar objetos que estejam sendo segurados por outra criatura ou presos a alguma estrutura.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 500\n\nDados da lista de mercadorias:\n- Efeito: Recupera uma vez por cena um objeto que o usuário estava empunhando.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 500","tags":["loja"],"dados_notion":{"pagina":"ACESSÓRIOS","secao":[],"tipo_tabela":"Equipamento","campos":{"Equipamento":"Fivela de Retorno","Efeito":"Recupera uma vez por cena um objeto que o usuário estava empunhando.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f10a1363552818da767c209228ed796","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"5f5cd6e815934306a1405d2d0fd3170f","linhaBlocoId":"dde46a4a09ae4662ad9b1721f1368a2f","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"acessorio","categoria_label":"Acessório","subtipo":null,"estatisticas":{"campos_tabela":{"Equipamento":"Fivela de Retorno","Efeito":"Recupera uma vez por cena um objeto que o usuário estava empunhando.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"500"},"espacos_texto":"1"}},"id":"item:acessorios_fivela_de_retorno","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"e5561960b69d573201ba013b3cd658f58a6dc531d4ac98fc7ce3ba1ee488e196"},{"content_type":"item","slug":"acessorios_foco_runico","payload":{"id":"acessorios_foco_runico","slug":"acessorios_foco_runico","nome":"Foco Rúnico","raridade":"raro","raridade_label":"Raro","preco":1200,"preco_texto":"1.200","preco_qualificador":null,"descricao_curta":"Reduz em um grau a Complexidade de uma Moldagem Preparada.","descricao_longa":"*Raro*\n\nObjeto pessoal gravado com uma matriz rúnica calibrada para estabilizar uma forma específica de conjuração. O foco não produz Mana nem conjura por conta própria; ele organiza o fluxo no instante em que a energia deixa o conduto, tornando uma manipulação previamente preparada mais fácil de reproduzir.\n\nCada Foco Rúnico possui uma **Moldagem Preparada**, vinculada a uma magia específica de uma Vertente. A Moldagem Preparada descreve uma alteração concreta que poderia ser realizada normalmente pelas regras de **Moldar Magia**, apresentadas em [17. MAGIA E VERTENTES](https://app.notion.com/p/bd50a1363552821ab3e581b50e481954).\n\nEnquanto estiver com o foco equipado, ao realizar exatamente essa Moldagem Preparada, determine normalmente a Complexidade da manipulação e então **reduza-a em um grau**, até o mínimo de **Trivial**. Manipulações de Complexidade **Insana** não têm sua Complexidade reduzida pelo foco.\n\nO foco não altera o custo base da magia nem permite realizar uma manipulação incompatível com a magia ou com sua Vertente.\n\nUm Foco Rúnico precisa ser calibrado para o fluxo de seu usuário. Sua matriz pode ser reconfigurada para outra Moldagem Preparada por um artesão rúnico capaz de realizar o procedimento.\n\n> **Exemplos de Moldagens Preparadas:**\n> - *Um Foco Rúnico vinculado a Rebote pode ser preparado para aumentar de 10 m para 15 m a distância máxima percorrida pelo alvo durante o retorno. Se o narrador considerar essa manipulação Fácil, o foco a reduz para Trivial.*\n> \n> - *Um foco vinculado a Fantasma Sensorial pode ser preparado para criar uma imagem de tamanho Médio, em vez de Pequeno. Se a manipulação for considerada Regular, o foco a reduz para Fácil.*\n> \n> - *Um foco vinculado a Modulação pode ser preparado para alterar simultaneamente a luz e o som de uma mesma fonte ou área. A mesma moldagem pode ser Regular em circunstâncias controladas e Difícil durante um combate ou sob interferência arcana. Com o foco, essas Complexidades seriam reduzidas para Fácil e Regular, respectivamente.*\n\nA Moldagem Preparada define **o que o foco foi construído para facilitar**, não sua Complexidade. A Complexidade continua sendo determinada no momento da conjuração, considerando a alteração realizada e as circunstâncias da cena.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 1.000\n\nDados da lista de mercadorias:\n- Efeito: Reduz em um grau a Complexidade de uma Moldagem Preparada.\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.200","tags":["loja"],"dados_notion":{"pagina":"ACESSÓRIOS","secao":[],"tipo_tabela":"Equipamento","campos":{"Equipamento":"Foco Rúnico","Efeito":"Reduz em um grau a Complexidade de uma Moldagem Preparada.","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f10a1363552818da767c209228ed796","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"5f5cd6e815934306a1405d2d0fd3170f","linhaBlocoId":"c17eeedafcef4f40be8300d53254fa58","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"acessorio","categoria_label":"Acessório","subtipo":null,"estatisticas":{"campos_tabela":{"Equipamento":"Foco Rúnico","Efeito":"Reduz em um grau a Complexidade de uma Moldagem Preparada.","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.200"},"espacos_texto":"1"}},"id":"item:acessorios_foco_runico","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"d15bd18d39148486657c2af35012274f4ab748153c20820e5b7c968bcbdb3be8"},{"content_type":"item","slug":"acessorios_mascara_filtrante","payload":{"id":"acessorios_mascara_filtrante","slug":"acessorios_mascara_filtrante","nome":"Máscara Filtrante","raridade":"comum","raridade_label":"Comum","preco":50,"preco_texto":"50","preco_qualificador":null,"descricao_curta":"Filtra contaminantes suspensos no ar e impede Saturado ambiental enquanto o filtro funcionar.","descricao_longa":"*Comum*\n\nMáscara leve equipada com filtros químicos e rúnicos substituíveis, utilizada em zonas industriais, áreas contaminadas e regiões sujeitas a tempestades arcanas.\n\nEnquanto estiver usando um filtro funcional, você pode respirar normalmente em meio a fumaça, poeira, gases tóxicos e outros contaminantes suspensos no ar. Além disso, não sofre a condição **`Saturado`** causada por efeitos ambientais.\n\nA máscara não protege contra substâncias transmitidas por contato, ingestão ou inoculação, nem fornece oxigênio em ambientes onde não exista ar respirável.\n\nA máscara vem com 3 filtros. Cada filtro permanece funcional por **1 cena de exposição** e precisa ser substituído depois disso.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 50\n\n**Filtro:** Ⱥ 10\n\nDados da lista de mercadorias:\n- Efeito: Filtra contaminantes suspensos no ar e impede Saturado ambiental enquanto o filtro funcionar.\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 50","tags":["loja"],"dados_notion":{"pagina":"ACESSÓRIOS","secao":[],"tipo_tabela":"Equipamento","campos":{"Equipamento":"Máscara Filtrante","Efeito":"Filtra contaminantes suspensos no ar e impede Saturado ambiental enquanto o filtro funcionar.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"50"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f10a1363552818da767c209228ed796","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"5f5cd6e815934306a1405d2d0fd3170f","linhaBlocoId":"d2b7c72bac6543f5b28d1a8e3d9c443e","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"acessorio","categoria_label":"Acessório","subtipo":null,"estatisticas":{"campos_tabela":{"Equipamento":"Máscara Filtrante","Efeito":"Filtra contaminantes suspensos no ar e impede Saturado ambiental enquanto o filtro funcionar.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"50"},"espacos_texto":"1"}},"id":"item:acessorios_mascara_filtrante","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"8ff3ec78e4ac9ddeb4bb4198bf8c9967bd0fe6b40f52818a88449f1ea20e8a86"},{"content_type":"item","slug":"acessorios_oculos_de_realidade_aumentada","payload":{"id":"acessorios_oculos_de_realidade_aumentada","slug":"acessorios_oculos_de_realidade_aumentada","nome":"Óculos de Realidade Aumentada","raridade":"incomum","raridade_label":"Incomum","preco":300,"preco_texto":"300","preco_qualificador":null,"descricao_curta":"Exibem a camada de realidade aumentada da Malha e informações de dispositivos conectados.","descricao_longa":"*Incomum*\n\nÓculos com lentes transparentes capazes de sobrepor interfaces digitais e rúnicas ao ambiente físico. Enquanto estiverem equipados, o usuário enxerga a camada de realidade aumentada da Malha, incluindo sinalizações, mapas, anúncios, interfaces públicas, portais e hubs digitais associados aos espaços ao seu redor.\n\nOs óculos também podem exibir mensagens, transmissões, imagens, marcações e outras informações recebidas de dispositivos conectados ao usuário, posicionando esses dados diretamente no campo de visão quando houver uma referência espacial correspondente.\n\nPermitem ainda visualizar **Tinta Rúnica Invisível** e outros sinais cuja descrição determine compatibilidade com realidade aumentada.\n\nOs óculos servem como interface para a Malha cotidiana, mas não substituem os equipamentos, acessos ou procedimentos exigidos para interagir com uma Trama ou invadir sistemas protegidos.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 300\n\nDados da lista de mercadorias:\n- Efeito: Exibem a camada de realidade aumentada da Malha e informações de dispositivos conectados.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 300","tags":["loja"],"dados_notion":{"pagina":"ACESSÓRIOS","secao":[],"tipo_tabela":"Equipamento","campos":{"Equipamento":"Óculos de Realidade Aumentada","Efeito":"Exibem a camada de realidade aumentada da Malha e informações de dispositivos conectados.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f10a1363552818da767c209228ed796","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"5f5cd6e815934306a1405d2d0fd3170f","linhaBlocoId":"22c4b44065cb4d98843fef09de486dfb","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"acessorio","categoria_label":"Acessório","subtipo":null,"estatisticas":{"campos_tabela":{"Equipamento":"Óculos de Realidade Aumentada","Efeito":"Exibem a camada de realidade aumentada da Malha e informações de dispositivos conectados.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300"},"espacos_texto":"1"}},"id":"item:acessorios_oculos_de_realidade_aumentada","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"7fdedc12d2e183b088108011d1ef0c467a3a247e338ef8920ff3b596aff71e2e"},{"content_type":"item","slug":"acessorios_pulseira_vital","payload":{"id":"acessorios_pulseira_vital","slug":"acessorios_pulseira_vital","nome":"Pulseira Vital","raridade":"incomum","raridade_label":"Incomum","preco":300,"preco_texto":"300","preco_qualificador":null,"descricao_curta":"Monitora e transmite sinais vitais para telemetria e diagnóstico remoto.","descricao_longa":"*Incomum*\n\nPulseira equipada com sensores biométricos e uma matriz rúnica de leitura fisiológica. Enquanto estiver equipada, monitora continuamente os sinais vitais do usuário e pode transmitir esses dados para dispositivos autorizados.\n\nO usuário e qualquer dispositivo pareado podem acompanhar seu estado fisiológico em tempo real. A pulseira sinaliza imediatamente quando ele fica com **metade ou menos dos PV máximos**, entra em **Colapso Físico** ou sofre uma alteração fisiológica relevante detectável pelos sensores.\n\nUma criatura com acesso à telemetria pode realizar testes de **`Medicina`** para avaliar ou diagnosticar o usuário sem examiná-lo diretamente, desde que a informação necessária possa ser obtida pelos sinais monitorados. Tratamentos, administração de medicamentos e outros procedimentos continuam exigindo acesso e recursos apropriados.\n\nQuando houver conexão disponível com a Malha, a pulseira também pode transmitir um alerta e a localização do usuário aos dispositivos autorizados.\n\nA pulseira não identifica automaticamente a causa de uma alteração, não detecta efeitos puramente mentais ou arcanos sem manifestação fisiológica e não cura nem estabiliza o usuário.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 300\n\nDados da lista de mercadorias:\n- Efeito: Monitora e transmite sinais vitais para telemetria e diagnóstico remoto.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 300","tags":["loja"],"dados_notion":{"pagina":"ACESSÓRIOS","secao":[],"tipo_tabela":"Equipamento","campos":{"Equipamento":"Pulseira Vital","Efeito":"Monitora e transmite sinais vitais para telemetria e diagnóstico remoto.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f10a1363552818da767c209228ed796","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"5f5cd6e815934306a1405d2d0fd3170f","linhaBlocoId":"69cd0368fbc44e53ad7866bcd3d4faf2","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"acessorio","categoria_label":"Acessório","subtipo":null,"estatisticas":{"campos_tabela":{"Equipamento":"Pulseira Vital","Efeito":"Monitora e transmite sinais vitais para telemetria e diagnóstico remoto.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300"},"espacos_texto":"1"}},"id":"item:acessorios_pulseira_vital","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"10ce5a97a823bb2d478faa80759fb259e54a2a68384956d081db38ea9dc363d8"},{"content_type":"item","slug":"armas_armas_corpo_a_corpo_faca","payload":{"id":"armas_armas_corpo_a_corpo_faca","slug":"armas_armas_corpo_a_corpo_faca","nome":"Faca","raridade":"muito_comum","raridade_label":"Muito Comum","preco":15,"preco_texto":"15","preco_qualificador":null,"descricao_curta":"Lâmina curta e versátil, usada em cozinha, caça ou combate. Em mãos habilidosas, serve tanto para confrontos corpo a corpo quanto para arremessos rápidos e discretos. É o instrumento de ataque mais difundido, presente em brigas de rua, assaltos ou na autodefesa improvisada.","descricao_longa":"*Muito comum*\n\nLâmina curta e versátil, usada em cozinha, caça ou combate. Em mãos habilidosas, serve tanto para confrontos corpo a corpo quanto para arremessos rápidos e discretos. É o instrumento de ataque mais difundido, presente em brigas de rua, assaltos ou na autodefesa improvisada.\n\n**Dano:** Corpo + 1d4 perfurante\n\n**Mãos:** 1\n\n**Propriedades:** Arremesso (10 m/20 m), Silencioso (à distância)\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 15 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d4 perfurante\n- Mãos: 1\n- Propriedades: Arremesso, Silencioso\n- Ocultável?: Sim\n- Raridade: Muito comum\n- Espaços: 1\n- Preço (Ⱥ): 15","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Faca","Dano":"Corpo + 1d4 perfurante","Mãos":"1","Propriedades":"Arremesso, Silencioso","Ocultável?":"Sim","Raridade":"Muito comum","Espaços":"1","Preço (Ⱥ)":"15"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"be4119bf66a744da85dfab3b2a8840b3","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"Faca","Dano":"Corpo + 1d4 perfurante","Mãos":"1","Propriedades":"Arremesso, Silencioso","Ocultável?":"Sim","Raridade":"Muito comum","Espaços":"1","Preço (Ⱥ)":"15"},"espacos_texto":"1","dado_dano":"1d4","soma_atributo":"corpo","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":1,"propriedades":["arremesso","silencioso"],"pericia_teste":"luta","slots_runa_max":1,"alcance":{"tipo":"adjacente","estendido_m":1}},"ocultavel":"sim"},"id":"item:armas_armas_corpo_a_corpo_faca","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"d569775b588eb967f4f92f30bc0225a1226f378ef2b21566701eea8349ec1e4c"},{"content_type":"item","slug":"armas_adaga","payload":{"id":"armas_adaga","slug":"armas_adaga","nome":"Adaga","raridade":"comum","raridade_label":"Comum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"Diferente da faca, a adaga é projetada para matar. Possui lâmina dupla e ponta reforçada, otimizando tanto cortes quanto estocadas rápidas. É uma das armas mais antigas e discretas do mundo, amplamente usada por militares, agentes e assassinos.","descricao_longa":"*Comum*\n\nDiferente da faca, a adaga é projetada para matar. Possui lâmina dupla e ponta reforçada, otimizando tanto cortes quanto estocadas rápidas. É uma das armas mais antigas e discretas do mundo, amplamente usada por militares, agentes e assassinos.\n\n**Dano:** 1d6 cortante ou perfurante\n\n**Mãos:** 1\n\n**Propriedades:** Sangramento\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 120 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d6 cortante/perfurante\n- Mãos: 1\n- Propriedades: Sangramento\n- Ocultável?: Sim\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Adaga","Dano":"Corpo + 1d6 cortante/perfurante","Mãos":"1","Propriedades":"Sangramento","Ocultável?":"Sim","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"c83308193fde4d32a19e9e8e14809d01","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"Adaga","Dano":"Corpo + 1d6 cortante/perfurante","Mãos":"1","Propriedades":"Sangramento","Ocultável?":"Sim","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1","dado_dano":"1d6","soma_atributo":"corpo","tipo_dano":"fisico","subtipos_dano_possiveis":["cortante","perfurante"],"maos":1,"propriedades":["sangramento"],"pericia_teste":"luta","slots_runa_max":1,"alcance":{"tipo":"adjacente","estendido_m":1}},"ocultavel":"sim"},"id":"item:armas_adaga","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b1a907dfa2ee23471150bf8a09e1fa100524884575edfec2a51755025fe7327c"},{"content_type":"item","slug":"armas_fl_1_razor_adaga","payload":{"id":"armas_fl_1_razor_adaga","slug":"armas_fl_1_razor_adaga","nome":"FL-1 Razor (Adaga)","raridade":"incomum","raridade_label":"Incomum","preco":800,"preco_texto":"800","preco_qualificador":null,"descricao_curta":"A **FL-1 Razor** é a lâmina compacta da família **Flatline**, equipada com sensores de impacto e microatuadores ao longo do fio. Ao encontrar resistência, seu núcleo vibratório registra a resposta do corpo atingido e ajusta a frequência da lâmina para os golpes seguintes.","descricao_longa":"*Incomum*\n\nA **FL-1 Razor** é a lâmina compacta da família **Flatline**, equipada com sensores de impacto e microatuadores ao longo do fio. Ao encontrar resistência, seu núcleo vibratório registra a resposta do corpo atingido e ajusta a frequência da lâmina para os golpes seguintes.\n\nPequena e discreta, a Razor é usada principalmente quando uma arma convencional não oferece poder de corte suficiente sem sacrificar facilidade de porte.\n\n**Ressonância fina:** ao acertar uma criatura, a Razor fica sintonizada com ela. Depois disso, uma vez por rodada, ao acertar novamente a criatura sintonizada, a Razor causa +1d4 de dano.\n\nA Razor perde a Sintonia ao acertar outra criatura ou se o portador passar até o fim de seu próximo turno sem atacar a criatura sintonizada. Trocar de portador não encerra a Sintonia.\n\n**Dano:** Corpo + 1d6 cortante ou perfurante\n\n**Mãos:** 1\n\n**Propriedades:** Sangramento\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 800 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d6 cortante ou perfurante\n- Mãos: 1\n- Propriedades: Sangramento\n- Ocultável?: Sim\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 800","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"FL-1 Razor (Adaga)","Dano":"Corpo + 1d6 cortante ou perfurante","Mãos":"1","Propriedades":"Sangramento","Ocultável?":"Sim","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"800"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"a188e7fa2619492e90fbeea5da21732f","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"FL-1 Razor (Adaga)","Dano":"Corpo + 1d6 cortante ou perfurante","Mãos":"1","Propriedades":"Sangramento","Ocultável?":"Sim","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"800"},"espacos_texto":"1","dado_dano":"1d6","soma_atributo":"corpo","tipo_dano":"fisico","subtipos_dano_possiveis":["cortante","perfurante"],"maos":1,"propriedades":["sangramento"],"pericia_teste":"luta","slots_runa_max":1,"alcance":{"tipo":"adjacente","estendido_m":1}},"ocultavel":"sim"},"id":"item:armas_fl_1_razor_adaga","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"25995ea6dc2b71701e9fd9252654089ed1d9d539fc12fc388b142d08ab8d3438"},{"content_type":"item","slug":"armas_soco_ingles","payload":{"id":"armas_soco_ingles","slug":"armas_soco_ingles","nome":"Soco-inglês","raridade":"muito_comum","raridade_label":"Muito Comum","preco":50,"preco_texto":"50","preco_qualificador":null,"descricao_curta":"Peça de metal projetada para encaixar nos dedos e potencializar socos. Simples, barata e eficiente em combates de curta distância. Muito usada por gangues urbanas por ser facilmente escondida.","descricao_longa":"*Muito comum*\n\nPeça de metal projetada para encaixar nos dedos e potencializar socos. Simples, barata e eficiente em combates de curta distância. Muito usada por gangues urbanas por ser facilmente escondida.\n\n**Dano:** 1d4 contundente\n\n**Mãos:** 1\n\n**Propriedades:** Contusão\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 50 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d4 contundente\n- Mãos: 1\n- Propriedades: Contusão\n- Ocultável?: Sim\n- Raridade: Muito Comum\n- Espaços: 1\n- Preço (Ⱥ): 50","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Soco-inglês","Dano":"Corpo + 1d4 contundente","Mãos":"1","Propriedades":"Contusão","Ocultável?":"Sim","Raridade":"Muito Comum","Espaços":"1","Preço (Ⱥ)":"50"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"3e5f47e7643f41b58aae16903c3d3aad","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"Soco-inglês","Dano":"Corpo + 1d4 contundente","Mãos":"1","Propriedades":"Contusão","Ocultável?":"Sim","Raridade":"Muito Comum","Espaços":"1","Preço (Ⱥ)":"50"},"espacos_texto":"1","dado_dano":"1d4","soma_atributo":"corpo","tipo_dano":"fisico","subtipo_dano":"contundente","maos":1,"propriedades":["contusao"],"pericia_teste":"luta","slots_runa_max":1,"alcance":{"tipo":"adjacente","estendido_m":1}},"ocultavel":"sim"},"id":"item:armas_soco_ingles","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"2b4ea995e53228307bbab7681c232f19e41895e2bc912e85d1fc8392ff794415"},{"content_type":"item","slug":"armas_tonfa","payload":{"id":"armas_tonfa","slug":"armas_tonfa","nome":"Tonfa","raridade":"comum","raridade_label":"Comum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"Arma tradicional adaptada para uso moderno, com empunhadura lateral que aumenta estabilidade e controle de golpes. Funciona bem tanto ofensivamente quanto defensivamente, sendo utilizada por forças de segurança em áreas urbanas e por lutadores treinados.","descricao_longa":"*Comum*\n\nArma tradicional adaptada para uso moderno, com empunhadura lateral que aumenta estabilidade e controle de golpes. Funciona bem tanto ofensivamente quanto defensivamente, sendo utilizada por forças de segurança em áreas urbanas e por lutadores treinados.\n\n**Dano:** 1d6 contundente\n\n**Mãos:** 1\n\n**Propriedades:** Contusão, Aparar\n\n**Ocultável:** parcial\n\n**Espaços:** 1\n\n**Preço:** 120 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d6 contundente\n- Mãos: 1\n- Propriedades: Contusão, Aparar\n- Ocultável?: Parcial\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Tonfa","Dano":"Corpo + 1d6 contundente","Mãos":"1","Propriedades":"Contusão, Aparar","Ocultável?":"Parcial","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"e1f913151d2349de8142b8655a3acf03","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"Tonfa","Dano":"Corpo + 1d6 contundente","Mãos":"1","Propriedades":"Contusão, Aparar","Ocultável?":"Parcial","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1","dado_dano":"1d6","soma_atributo":"corpo","tipo_dano":"fisico","subtipo_dano":"contundente","maos":1,"propriedades":["contusao","aparar"],"pericia_teste":"luta","slots_runa_max":1,"alcance":{"tipo":"adjacente","estendido_m":1}},"ocultavel":"parcial"},"id":"item:armas_tonfa","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"47d0dc03e660f7feefcdb51ed1a67faa989c6439c6975ebb92db0f4bd7302edf"},{"content_type":"item","slug":"armas_rv_4_shiv_faca","payload":{"id":"armas_rv_4_shiv_faca","slug":"armas_rv_4_shiv_faca","nome":"RV-4 Shiv (Faca)","raridade":"incomum","raridade_label":"Incomum","preco":300,"preco_texto":"300 por unidade","preco_qualificador":"por unidade","descricao_curta":"A **RV-4 Shiv** é a faca da família **Revenant**. Um sistema de vínculo acompanha sua posição depois do arremesso e permite que a lâmina refaça o caminho até o portador. Pequena e discreta, pode ser recuperada logo após o ataque ou deixada no ambiente para criar outro ângulo de retorno.","descricao_longa":"*Incomum*\n\nA **RV-4 Shiv** é a faca da família **Revenant**. Um sistema de vínculo acompanha sua posição depois do arremesso e permite que a lâmina refaça o caminho até o portador. Pequena e discreta, pode ser recuperada logo após o ataque ou deixada no ambiente para criar outro ângulo de retorno.\n\n**Retorno vetorial:** depois de resolver um ataque de arremesso com a Shiv, você pode fazê-la retornar imediatamente à mão, sem gastar PA ou **`Reação`**, ou deixá-la onde terminou sua trajetória. Enquanto estiver a até 30 m, ela permanece vinculada a você. Um portador pode manter até 3 armas Revenant vinculadas simultaneamente.\n\nAo utilizar **Rajada (2)**, duas Shivs são arremessadas no mesmo ataque e podem permanecer vinculadas simultaneamente, ocupando dois dos vínculos disponíveis.\n\nSe não recuperar a Shiv imediatamente, depois você pode usar uma **`Reação`** para chamar de volta todas as armas Revenant vinculadas. Todas retornam simultaneamente e resolvem suas trajetórias de retorno.\n\nCada Shiv retorna em linha reta de sua posição atual até você. Se uma ou mais trajetórias atravessarem uma criatura, resolva o retorno com um único teste de **`Precisão`** contra uma criatura atravessada, como em Rajada. Em acerto, cada Shiv cuja trajetória atravesse o alvo contribui com 1d6 de dano perfurante, somando **`Corpo`** apenas uma vez ao dano total. Todas as Shivs retornam à sua mão independentemente do resultado do ataque.\n\nA Shiv também pode ser arremessada deliberadamente contra um ponto ou superfície para preparar sua trajetória de retorno.\n\n**Dano:** Corpo + 1d6 perfurante\n\n**Mãos:** 1\n\n**Propriedades:** Arremesso, Silencioso, Rajada (2)\n\n**Alcance:** 15 m eficaz, até 30 m\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 300 Ⱥ por unidade\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d6 perfurante\n- Mãos: 1\n- Propriedades: Arremesso, Silencioso, Rajada (2)\n- Ocultável?: Sim\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 300 por unidade","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"RV-4 Shiv (Faca)","Dano":"Corpo + 1d6 perfurante","Mãos":"1","Propriedades":"Arremesso, Silencioso, Rajada (2)","Ocultável?":"Sim","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300 por unidade"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"ceecbdf17bbf421a8eadeee2e0ef490f","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"RV-4 Shiv (Faca)","Dano":"Corpo + 1d6 perfurante","Mãos":"1","Propriedades":"Arremesso, Silencioso, Rajada (2)","Ocultável?":"Sim","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300 por unidade"},"espacos_texto":"1","dado_dano":"1d6","soma_atributo":"corpo","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":1,"rajada_x":2,"propriedades":["arremesso","silencioso","rajada"],"pericia_teste":"luta","slots_runa_max":1},"ocultavel":"sim"},"id":"item:armas_rv_4_shiv_faca","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"744f2a90dc1cac1341b05cce75207f22e04c5a686f19d09b8a9d423288e770aa"},{"content_type":"item","slug":"armas_facas_de_arremesso","payload":{"id":"armas_facas_de_arremesso","slug":"armas_facas_de_arremesso","nome":"Facas de Arremesso","raridade":"comum","raridade_label":"Comum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"Kit composto por quatro facas projetadas para lançamento, com lâminas estreitas, construção reforçada e distribuição equilibrada de peso. Sua geometria favorece a estabilidade durante o arremesso, embora ofereça menor ergonomia para combate próximo.","descricao_longa":"*Comum*\n\nKit composto por quatro facas projetadas para lançamento, com lâminas estreitas, construção reforçada e distribuição equilibrada de peso. Sua geometria favorece a estabilidade durante o arremesso, embora