abela":"Arma","campos":{"Arma":"Shuriken","Dano":"Corpo + 1d4 cortante","Mãos":"1","Propriedades":"Arremesso, Sangramento, Silencioso, Rajada (3)","Ocultável?":"Sim","Raridade":"Incomum","Espaços":"1 (kit de 6)","Preço (Ⱥ)":"200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"f020e8bad8654100a38ecb5589a6cf71","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"Shuriken","Dano":"Corpo + 1d4 cortante","Mãos":"1","Propriedades":"Arremesso, Sangramento, Silencioso, Rajada (3)","Ocultável?":"Sim","Raridade":"Incomum","Espaços":"1 (kit de 6)","Preço (Ⱥ)":"200"},"espacos_texto":"1 (kit de 6)","dado_dano":"1d4","soma_atributo":"corpo","tipo_dano":"fisico","subtipo_dano":"cortante","maos":1,"rajada_x":3,"propriedades":["arremesso","sangramento","silencioso","rajada"],"kit":"6 shurikens","pericia_teste":"precisao","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":10,"max_m":20,"penalidade_alem_eficaz":-2}},"ocultavel":"sim"},"id":"item:armas_shuriken","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"95bcdeba91e749c6cca7c32c0cb7dd6d291577b06cab5f35c89e759109c84cfe"},{"content_type":"item","slug":"armas_rv_12_razorstar_shuriken","payload":{"id":"armas_rv_12_razorstar_shuriken","slug":"armas_rv_12_razorstar_shuriken","nome":"RV-12 Razorstar (Shuriken)","raridade":"raro","raridade_label":"Raro","preco":1000,"preco_texto":"1.000 por kit","preco_qualificador":"por kit","descricao_curta":"A **RV-12 Razorstar** é um kit de três lâminas de arremesso da família **Revenant**. As unidades compartilham o mesmo sistema de vínculo e podem permanecer espalhadas pelo campo depois de uma rajada, formando diferentes linhas de retorno até o portador.","descricao_longa":"*Raro*\n\nA **RV-12 Razorstar** é um kit de três lâminas de arremesso da família **Revenant**. As unidades compartilham o mesmo sistema de vínculo e podem permanecer espalhadas pelo campo depois de uma rajada, formando diferentes linhas de retorno até o portador.\n\n**Retorno vetorial:** depois de resolver um ataque de arremesso com uma Razorstar, você pode fazê-la retornar imediatamente à mão, sem gastar PA ou **`Reação`**, ou deixá-la onde terminou sua trajetória. Enquanto estiver a até 30 m, ela permanece vinculada a você. Um portador pode manter até 3 armas Revenant vinculadas simultaneamente.\n\nAo utilizar Rajada (3), as três Razorstars são arremessadas com o mesmo ataque e podem permanecer vinculadas ao mesmo tempo, ocupando os 3 vínculos disponíveis.\n\nSe não recuperar as Razorstars imediatamente, depois você pode usar uma **`Reação`** para chamar de volta todas as unidades vinculadas. Todas retornam simultaneamente.\n\nSempre que as Razorstars retornam, cada uma percorre uma linha reta de sua posição atual até você. Se pelo menos uma dessas trajetórias atravessar uma criatura, resolva o retorno com um único teste de **`Precisão`**, como em um uso de Rajada (3), contra uma criatura atravessada por pelo menos uma das trajetórias. Em acerto, cada Razorstar cuja trajetória atravesse o alvo contribui com 1d4 de dano cortante, somando **`Corpo`** apenas uma vez ao dano total. Todas as Razorstars retornam à sua mão independentemente do resultado.\n\nAs Razorstars também podem ser arremessadas deliberadamente contra pontos ou superfícies para preparar suas trajetórias de retorno.\n\n**Kit:** 3 Razorstars\n\n**Dano:** Corpo + 1d4 cortante\n\n**Mãos:** 1\n\n**Propriedades:** Arremesso, Silencioso, Sangramento, Rajada (3)\n\n**Alcance:** 10 m eficaz, até 20 m\n\n**Ocultável:** sim\n\n**Espaços:** 1 (kit)\n\n**Preço:** 1.000 Ⱥ por kit\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d4 cortante\n- Mãos: 1\n- Propriedades: Arremesso, Silencioso, Sangramento, Rajada (3)\n- Ocultável?: Sim\n- Raridade: Raro\n- Espaços: 1 (kit de 3)\n- Preço (Ⱥ): 1.000 por kit","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"RV-12 Razorstar (Shuriken)","Dano":"Corpo + 1d4 cortante","Mãos":"1","Propriedades":"Arremesso, Silencioso, Sangramento, Rajada (3)","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1 (kit de 3)","Preço (Ⱥ)":"1.000 por kit"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"75aba0aeaae842b9985c4de848f7ce81","linhaBlocoId":"d01963dc0d004c1f90b22e645b747f93","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"RV-12 Razorstar (Shuriken)","Dano":"Corpo + 1d4 cortante","Mãos":"1","Propriedades":"Arremesso, Silencioso, Sangramento, Rajada (3)","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1 (kit de 3)","Preço (Ⱥ)":"1.000 por kit"},"espacos_texto":"1 (kit de 3)","dado_dano":"1d4","soma_atributo":"corpo","tipo_dano":"fisico","subtipo_dano":"cortante","maos":1,"rajada_x":3,"propriedades":["arremesso","silencioso","sangramento","rajada"],"kit":"3 Razorstars","pericia_teste":"precisao","slots_runa_max":1},"ocultavel":"sim"},"id":"item:armas_rv_12_razorstar_shuriken","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"679badad0ac8fb708f8b8fe3cd9b5fe22f1e95e7dbe87ee2fbe414dd6e6eb71e"},{"content_type":"item","slug":"armas_rapieira","payload":{"id":"armas_rapieira","slug":"armas_rapieira","nome":"Rapieira","raridade":"i