ços: 1\n- Preço (Ⱥ): 200","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Espada curta","Dano":"Corpo + 1d8 cortante /perfurante","Mãos":"1","Propriedades":"Sangramento, Aparar","Ocultável?":"Não","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"1633dd88a58d4caba0f52ba7f1756079","linhaBlocoId":"6a6c454f819e45fead3e9ef5047c3ae1","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"Espada curta","Dano":"Corpo + 1d8 cortante /perfurante","Mãos":"1","Propriedades":"Sangramento, Aparar","Ocultável?":"Não","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"200"},"espacos_texto":"1","dado_dano":"1d8","soma_atributo":"corpo","tipo_dano":"fisico","subtipos_dano_possiveis":["cortante","perfurante"],"maos":1,"propriedades":["sangramento","aparar"],"pericia_teste":"luta","slots_runa_max":2,"alcance":{"tipo":"adjacente","estendido_m":1}},"ocultavel":"nao"},"id":"item:armas_espada_curta","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"83f58bf3ef688e78155947d80c51fb932efd7cd2f25a43fc4557e81de6a48877"},{"content_type":"item","slug":"armas_armas_corpo_a_corpo_machado_de_mao","payload":{"id":"armas_armas_corpo_a_corpo_machado_de_mao","slug":"armas_armas_corpo_a_corpo_machado_de_mao","nome":"Machado de mão","raridade":"comum","raridade_label":"Comum","preco":220,"preco_texto":"220","preco_qualificador":null,"descricao_curta":"Ferramenta robusta adaptada para confronto. Seus golpes pesados partem madeira, metal fino ou carne com a mesma facilidade, e seu equilíbrio permite que seja lançado em curta distância. Nas periferias e submundo, é tanto arma quanto utensílio cotidiano.","descricao_longa":"*Comum*\n\nFerramenta robusta adaptada para confronto. Seus golpes pesados partem madeira, metal fino ou carne com a mesma facilidade, e seu equilíbrio permite que seja lançado em curta distância. Nas periferias e submundo, é tanto arma quanto utensílio cotidiano.\n\n**Dano:** Corpo + 1d8 cortante\n\n**Mãos:** 1\n\n**Propriedades:** Sangramento, Arremesso (6 m/12 m)\n\n**Ocultável:** não\n\n**Espaços:** 1\n\n**Preço:** 220 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: Corpo + 1d8 cortante\n- Mãos: 1\n- Propriedades: Sangramento, Arremesso\n- Ocultável?: Não\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 220","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS BRANCAS","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Machado de mão","Dano":"Corpo + 1d8 cortante","Mãos":"1","Propriedades":"Sangramento, Arremesso","Ocultável?":"Não","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"220"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"1633dd88a58d4caba0f52ba7f1756079","linhaBlocoId":"fdcab03c26c440cc8e34a64c1d27e6a1","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS BRANCAS","estatisticas":{"campos_tabela":{"Arma":"Machado de mão","Dano":"Corpo + 1d8 cortante","Mãos":"1","Propriedades":"Sangramento, Arremesso","Ocultável?":"Não","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"220"},"espacos_texto":"1","dado_dano":"1d8","soma_atributo":"corpo","tipo_dano":"fisico","subtipo_dano":"cortante","maos":1,"propriedades":["sangramento","arremesso"],"pericia_teste":"luta","slots_runa_max":2,"alcance":{"tipo":"adjacente",