para emboscadas discretas em zonas rurais ou urbanas periféricas. Sua principal vantagem é a versatilidade, capaz de disparar desde flechas comuns até projéteis especiais, como explosivos ou tóxicos.\n\n**Munição:** 1 flecha\n\n**Dano:** 1d6 perfurante\n\n**Mãos:** 2\n\n**Alcance:** 30 m eficaz, até 60 m com –2 de desvantagem.\n\n**Propriedades:** Silencioso, Precisão\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 200 Ⱥ (12 flechas simples inclusas)\n\nDados da lista de mercadorias:\n- Munição: 1\n- Dano: 1d6\n- Mãos: 2\n- Tipo: Perfurante\n- Propriedades: Silencioso, Precisão\n- Ocultável?: Não\n- Raridade: Comum\n- Espaços: 2\n- Preço (Ⱥ): 200","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE DISPARO","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Arco curto","Munição":"1","Dano":"1d6","Mãos":"2","Tipo":"Perfurante","Propriedades":"Silencioso, Precisão","Ocultável?":"Não","Raridade":"Comum","Espaços":"2","Preço (Ⱥ)":"200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d20cd254170484bba66e47cfad8d4c3","linhaBlocoId":"ebc61c9de01c4b11ae54b97f33b57db4","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE DISPARO","estatisticas":{"campos_tabela":{"Arma":"Arco curto","Munição":"1","Dano":"1d6","Mãos":"2","Tipo":"Perfurante","Propriedades":"Silencioso, Precisão","Ocultável?":"Não","Raridade":"Comum","Espaços":"2","Preço (Ⱥ)":"200"},"espacos_texto":"2","dado_dano":"1d6","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":2,"propriedades":["silencioso","precisao"],"pericia_teste":"precisao","slots_runa_max":2,"alcance":{"tipo":"distancia","eficaz_m":30,"max_m":60,"penalidade_alem_eficaz":-2},"inclui_na_compra":"12 flechas sim