ano: 1d8\n- Mãos: 1\n- Propriedades: Sangramento, Perfuração\n- Ocultável?: Parcial\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 1.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Pistola pesada","Munição":"8","Dano":"1d8","Mãos":"1","Propriedades":"Sangramento, Perfuração","Ocultável?":"Parcial","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"1.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"955d0d03291245d19ef1354503ae529f","linhaBlocoId":"2561ceaf5fd1413c878fda4a02829921","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"Pistola pesada","Munição":"8","Dano":"1d8","Mãos":"1","Propriedades":"Sangramento, Perfuração","Ocultável?":"Parcial","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"1.000"},"espacos_texto":"1","dado_dano":"1d8","maos":1,"propriedades":["sangramento","perfuracao"],"pericia_teste":"balistica","slots_runa_max":1,"tipo_dano":"fisico","subtipo_dano":"perfurante","alcance":{"tipo":"distancia","eficaz_m":30,"max_m":60,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"mun_pistola"},"ocultavel":"parcial"},"id":"item:armas_pistola_pesada","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"fd67ea2cb34516002fe752a32b1b1ec49d9df30b6e205e29f94e139923a0e541"},{"content_type":"item","slug":"armas_sw_9_ghostline_pistola_pesada","payload":{"id":"armas_sw_9_ghostline_pistola_pesada","slug":"armas_sw_9_ghostline_pistola_pesada","nome":"SW-9 Ghostline (Pistola pesada)","raridade":"raro","raridade_label":"Raro","preco":1800,"preco_texto":"1.800","preco_qualificador":null,"descricao_curta":"A **SW-9 Ghostline** é a pistola pesada da família **Sidewinder**. Seu conjunto de mira acompanha o projétil depois do disparo e realiza pequenas correções durante o voo, permitindo que a bala contorne obstáculos e mude de direção depois do primeiro impacto.","descricao_longa":"*Raro*\n\nA **SW-9 Ghostline** é a pistola pesada da família **Sidewinder**. Seu conjunto de mira acompanha o projétil depois do disparo e realiza pequenas correções durante o voo, permitindo que a bala contorne obstáculos e mude de direção depois do primeiro impacto.\n\nCompacta para os padrões da linha, a Ghostline é procurada por quem precisa da tecnologia Sidewinder sem carregar uma arma longa.\n\n**Trajetória serpentina:** ataques com a Ghostline ignoram cobertura parcial. Depois de atingir uma criatura, o projétil pode continuar até outra criatura a até 2 m dela. Compare o mesmo resultado do teste de ataque com a Defesa do segundo alvo. Caso também o atinja, determine normalmente a região atingida pela nova margem e cause metade do dano.\n\nO segundo impacto não consome munição adicional, não pode gerar sucesso crítico e não ativa propriedades ou efeitos que dependam de um sucesso crítico. As demais propriedades da arma funcionam normalmente. O projétil não pode continuar para um terceiro alvo.\n\n**Munição:** 8\n\n**Dano:** 1d8 perfurante\n\n**Mãos:** 1\n\n**Propriedades:** Sangramento, Perfuração\n\n**Alcance:** 30 m eficaz, até 60 m com –2 de desvantagem\n\n**Ocultável:** parcial\n\n**Espaços:** 1\n\n**Preço:** 1.800 Ⱥ\n\nDados da lista de mercadorias:\n- Munição: 8\n- Dano: 1d8 perfurante\n- Mãos: 1\n- Propriedades: Sangramento, Perfuração\n- Ocultável?: Parcial\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.800","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"SW-9 Ghostline (Pistola pesada)","Munição":"8","Dano":"1d8 perfurante","Mãos":"1","Propriedades":"Sangramento, Perfuração","Ocultável?":"Parcial","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.800"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"955d0d03291245d19ef1354503ae529f","linhaBlocoId":"1112291b4d904a0f91ef3f8caacffcf6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"SW-9 Ghostline (Pistola pesada)","Munição":"8","Dano":"1d8 perfurante","Mãos":"1","Propriedades":"Sangramento, Perfuração","Ocultável?":"Parcial","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.800"},"espacos_texto":"1","dado_dano":"1d8","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":1,"propriedades":["sangramento","perfuracao"],"pericia_teste":"balistica","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":30,"max_m":60,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"mun_pistola"},"ocultavel":"parcial"},"id":"item:armas_sw_9_ghostline_pistola_pesada","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9aae2b87e3c889d30f09488e79d70ce4c94bf483db50809feb88b43bbfc878bb"},{"content_type":"item","slug":"armas_as_10_overdrive_pistola_pesada","payload":{"id":"armas_as_10_overdrive_pistola_pesada","slug":"armas_as_10_overdrive_pistola_pesada","nome":"AS-10 Overdrive (Pistola pesada)","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"A **AS-10 Overdrive** é a pistola pesada da família **Aftershock**. Seus projéteis possuem um sistema de propulsão secundária que entra em funcionamento depois do disparo, aumentando sua velocidade enquanto percorrem o espaço até o alvo.","descricao_longa":"*Raro*\n\nA **AS-10 Overdrive** é a pistola pesada da família **Aftershock**. Seus projéteis possuem um sistema de propulsão secundária que entra em funcionamento depois do disparo, aumentando sua velocidade enquanto percorrem o espaço até o alvo.\n\nA Overdrive preserva o porte de uma pistola pesada, mas recompensa disparos feitos com alguma distância entre o atirador e o alvo.\n\n**Aceleração terminal:** quando a Overdrive atinge um alvo a 15 m ou mais, seu dano passa de 1d8 para 1d10 nesse ataque.\n\n**Munição:** 8\n\n**Dano:** 1d8 perfurante\n\n**Mãos:** 1\n\n**Propriedades:** Sangramento, Perfuração\n\n**Alcance:** 30 m eficaz, até 60 m com –2 de desvantagem\n\n**Espaços:** 1\n\n**Preço:** 1.500 Ⱥ\n\nDados da lista de mercadorias:\n- Munição: 8\n- Dano: 1d8 perfurante\n- Mãos: 1\n- Propriedades: Sangramento, Perfuração\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"AS-10 Overdrive (Pistola pesada)","Munição":"8","Dano":"1d8 perfurante","Mãos":"1","Propriedades":"Sangramento, Perfuração","Ocultável?":"","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"955d0d03291245d19ef1354503ae529f","linhaBlocoId":"0fd0c66c7acc428ebf86950e997c2340","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"AS-10 Overdrive (Pistola pesada)","Munição":"8","Dano":"1d8 perfurante","Mãos":"1","Propriedades":"Sangramento, Perfuração","Ocultável?":"","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.500"},"espacos_texto":"1","dado_dano":"1d8","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":1,"propriedades":["sangramento","perfuracao"],"pericia_teste":"balistica","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":30,"max_m":60,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"mun_pistola"}},"id":"item:armas_as_10_overdrive_pistola_pesada","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"2b1f9fd639a895e55142b71cb8bade050fe7f5df52294eef5cea6d622301f79f"},{"content_type":"item","slug":"armas_dl_8_cry_havoc_pistola_automatica","payload":{"id":"armas_dl_8_cry_havoc_pistola_automatica","slug":"armas_dl_8_cry_havoc_pistola_automatica","nome":"DL-8 Cry Havoc (Pistola automática)","raridade":"incomum","raridade_label":"Incomum","preco":1200,"preco_texto":"1.200","preco_qualificador":null,"descricao_curta":"A **DL-8 Cry Havoc** é a pistola automática da família **Deadlock**. Um conjunto de compensadores internos corrige o recuo entre disparos sucessivos, mantendo a arma alinhada mesmo durante sequências rápidas a curta distância.","descricao_longa":"*Incomum*\n\nA **DL-8 Cry Havoc** é a pistola automática da família **Deadlock**. Um conjunto de compensadores internos corrige o recuo entre disparos sucessivos, mantendo a arma alinhada mesmo durante sequências rápidas a curta distância.\n\nA Cry Havoc foi construída para concentrar vários impactos antes que o recuo consiga afastar a mira do alvo.\n\n**Controle Deadlock:** ao utilizar Rajada (2) contra uma criatura a até 10 m, a Cry Havoc não sofre a desvantagem imposta por Rajada. Outras fontes de desvantagem continuam funcionando normalmente. Se o ataque acertar, cada disparo causa +1 de dano, totalizando +2 de dano na Rajada.\n\n**Munição:** 18\n\n**Dano:** 1d6 perfurante\n\n**Mãos:** 1\n\n**Propriedades:** Sangramento, Rajada (2)\n\n**Alcance:** 20 m eficaz, até 40 m com –2 de desvantagem\n\n**Espaços:** 1\n\n**Preço:** 1.200 Ⱥ\n\nDados da lista de mercadorias:\n- Munição: 18\n- Dano: 1d6 perfurante\n- 