ão":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"65c3a0154432412b8c3378708fda7bd6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"Rifle de assalto","Dano":"2d6","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"2.500"},"espacos_texto":"3","dado_dano":"2d6","maos":2,"propriedades":["sangramento","perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"tipo_dano":"fisico","subtipo_dano":"perfurante","alcance":{"tipo":"distancia","eficaz_m":100,"max_m":200,"penalidade_alem_eficaz":-2},"municao_max":30,"municao_compativel":"mun_fuzil"},"ocultavel":"nao"},"id":"item:armas_rifle_de_assalto","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"f80c44ad748e0f662e0ed56c649fa65b169809723002b593b541de60fb85d90f"},{"content_type":"item","slug":"armas_sw_51_deviant_rifle_de_assalto","payload":{"id":"armas_sw_51_deviant_rifle_de_assalto","slug":"armas_sw_51_deviant_rifle_de_assalto","nome":"SW-51 Deviant (Rifle de assalto)","raridade":"raro","raridade_label":"Raro","preco":4000,"preco_texto":"4.000","preco_qualificador":null,"descricao_curta":"A **SW-51 Deviant** é o rifle de assalto da família **Sidewinder**. Seu sistema de orientação foi construído para manter controle sobre projéteis mais rápidos e pesados, corrigindo a trajetória mesmo depois de atravessar o primeiro alvo.","descricao_longa":"*Raro*\n\nA **SW-51 Deviant** é o rifle de assalto da família **Sidewinder**. Seu sistema de orientação foi construído para manter controle sobre projéteis mais rápidos e pesados, corrigindo a trajetória mesmo depois de atravessar o primeiro alvo.\n\nA Deviant é utilizada quando alcance e poder de fogo importam tanto quanto a capacidade de atingir adversários agrupados ou protegidos por obstáculos.\n\n**Trajetória serpentina:** ataques com a Deviant ignoram cobertura parcial. Depois de atingir uma criatura, o projétil pode continuar até outra criatura a até 2 m dela. Compare o mesmo resultado do teste de ataque com a Defesa do segundo alvo. Caso também o atinja, determine normalmente a região atingida pela nova margem e cause metade do dano.\n\nO segundo impacto não consome munição adicional, não pode gerar sucesso crítico e não ativa propriedades ou efeitos que dependam de um sucesso crítico. As demais propriedades da arma funcionam normalmente. O projétil não pode continuar para um terceiro alvo.\n\n**Munição:** 30\n\n**Dano:** 2d6 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Perfuração, Precisão\n\n**Alcance:** 100 m eficaz, até 200 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 4.000 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 2d6 perfurante\n- Mãos: 2\n- Propriedades: Sangramento, Perfuração, Precisão\n- Munição: 30\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 4.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"SW-51 Deviant (Rifle de assalto)","Dano":"2d6 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"4.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"6572e97c710e489cbe8a5d4ae778a392","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"SW-51 Deviant (Rifle de assalto)","Dano":"2d6 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"4.000"},"espacos_texto":"3","dado_dano":"2d6","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":2,"propriedades":["sangramento","perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":100,"max_m":200,"penalidade_alem_eficaz":-2},"municao_max":30,"municao_compativel":"mun_fuzil"},"ocultavel":"nao"},"id":"item:armas_sw_51_deviant_rifle_de_assalto","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"86d6d387de3b75054b4a9f468ea3b99289b38a3ed5df0172bc05dd6dd5869f8e"},{"content_type":"item","slug":"armas_dl_47_butcher_rifle_de_assalto","payload":{"id":"armas_dl_47_butcher_rifle_de_assalto","slug":"armas_dl_47_butcher_rifle_de_assalto","nome":"DL-47 Butcher (Rifle de assalto)","raridade":"raro","raridade_label":"Raro","preco":3800,"preco_texto":"3.800","preco_qualificador":null,"descricao_curta":"A **DL-47 Butcher** é o rifle de assalto da família **Deadlock**. Seu conjunto de compensação percorre praticamente toda a arma, distribuindo a força produzida pelos disparos entre coronha, receptor e cano.","descricao_longa":"*Raro*\n\nA **DL-47 Butcher** é o rifle de assalto da família **Deadlock**. Seu conjunto de compensação percorre praticamente toda a arma, distribuindo a força produzida pelos disparos entre coronha, receptor e cano.\n\nMesmo utilizando munição de maior potência, a Butcher consegue manter dois disparos consecutivos concentrados sobre o mesmo alvo quando usada a curta distância.\n\n**Controle Deadlock:** ao utilizar Rajada (2) contra uma criatura a até 10 m, a Butcher não sofre a desvantagem imposta por Rajada. Outras fontes de desvantagem continuam funcionando normalmente. Se o ataque acertar, cada disparo causa +1 de dano, totalizando +2 de dano na Rajada.\n\n**Munição:** 30\n\n**Dano:** 2d6 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Perfuração, Precisão, Rajada (2)\n\n**Alcance:** 100 m eficaz, até 200 m com –2 de desvantagem\n\n**Espaços:** 3\n\n**Preço:** 3.800 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 2d6 perfurante\n- Mãos: 2\n- Propriedades: Sangramento, Perfuração, Precisão, Rajada (2)\n- Munição: 30\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 3.800","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"DL-47 Butcher (Rifle de assalto)","Dano":"2d6 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão, Rajada (2)","Munição":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"3.800"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"2a9166f309b84711b995b4086caeb60d","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"DL-47 Butcher (Rifle de assalto)","Dano":"2d6 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão, Rajada (2)","Munição":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"3.800"},"espacos_texto":"3","dado_dano":"2d6","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":2,"rajada_x":2,"propriedades":["sangramento","perfuracao","precisao","rajada"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":100,"max_m":200,"penalidade_alem_eficaz":-2},"municao_max":30,"municao_compativel":"mun_fuzil"},"ocultavel":"nao"},"id":"item:armas_dl_47_butcher_rifle_de_assalto","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"6fc35a8910725b9c29e29b0b4766a6ffb313ab855f6489041a03a3d114e49ed1"},{"content_type":"item","slug":"armas_as_762_redshift_rifle_de_assalto","payload":{"id":"armas_as_762_redshift_rifle_de_assalto","slug":"armas_as_762_redshift_rifle_de_assalto","nome":"AS-762 Redshift (Rifle de assalto)","raridade":"raro","raridade_label":"Raro","preco":3500,"preco_texto":"3.500","preco_qualificador":null,"descricao_curta":"A **AS-762 Redshift** é o rifle de assalto da família **Aftershock**. Cada disparo recebe uma segunda etapa de propulsão durante o percurso, fazendo com que o projétil continue acelerando depois de sair do cano.","descricao_longa":"*Raro*\n\nA **AS-762 Redshift** é o rifle de assalto da família **Aftershock**. Cada disparo recebe uma segunda etapa de propulsão durante o percurso, fazendo com que o projétil continue acelerando depois de sair do cano.\n\nA curta distância, a Redshift se comporta como um rifle de assalto convencional. Em linhas de tiro mais longas, o mesmo projétil chega ao alvo com impacto consideravelmente maior.\n\n**Aceleração terminal:** quando a Redshift atinge um alvo a 50 m ou mais, seu dano passa de 2d6 para 2d8 nesse ataque.\n\n**Munição:** 30\n\n**Dano:** 2d6 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Perfuração, Precisão\n\n**Alcance:** 100 m eficaz, até 200 m com –2 de desvantagem\n\n**Espaços:** 3\n\n**Preço:** 3.500 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 2d6 perfurante\n- Mãos: 2\n- Propriedades: Sangramento, Perfuração, Precisão\n- Munição: 30\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 3.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"AS-762 Redshift (Rifle de assalto)","Dano":"2d6 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"3.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"8beb95a122c74e709ec24e1dc28408b6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"AS-762 Redshift (Rifle de assalto)","Dano":"2d6 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"30","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"3.500"},"espacos_texto":"3","dado_dano":"2d6","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":2,"propriedades":["sangramento","perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":100,"max_m":200,"penalidade_alem_eficaz":-2},"municao_max":30,"municao_compativel":"mun_fuzil"},"ocultavel":"nao"},"id":"item:armas_as_762_redshift_rifle_de_assalto","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"fbdfdfbed240bb61820e7a8630641def1cc3d2b8356f9a20a16b4b2b83896165"},{"content_type":"item","slug":"armas_rifle_de_precisao","payload":{"id":"armas_rifle_de_precisao","slug":"armas_rifle_de_precisao","nome":"Rifle de precisão","raridade":"raro","raridade_label":"Raro","preco":4000,"preco_texto":"4.000","preco_qualificador":null,"descricao_curta":"Usado em emboscadas ou execuções planejadas, é capaz de atingir alvos a grandes distâncias com letalidade extrema.","descricao_longa":"*Raro*\n\nUsado em emboscadas ou execuções planejadas, é capaz de atingir alvos a grandes distâncias com letalidade extrema.\n\n**Munição:** 2\n\n**Dano:** 2d10 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Perfuração, Precisão\n\n**Alcance:** 400 m eficaz, até 800 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 4.000 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 2d10\n- Mãos: 2\n- Propriedades: Sangramento, Perfuração, Precisão\n- Munição: 2\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 4.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Rifle de precisão","Dano":"2d10","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"2","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"4.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"6ec756a4ce874ad9bbbd461e88493906","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"Rifle de precisão","Dano":"2d10","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"2","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"4.000"},"espacos_texto":"3","dado_dano":"2d10","maos":2,"propriedades":["sangramento","perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"tipo_dano":"fisico","subtipo_dano":"perfurante","alcance":{"tipo":"distancia","eficaz_m":400,"max_m":800,"penalidade_alem_eficaz":-2},"municao_max":2,"municao_compativel":"mun_precisao"},"ocultavel":"nao"},"id":"item:armas_rifle_de_precisao","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"057dfbba01b60650d99c404229b027c5a775f53049d45fcd333a295f97f3cc42"},{"content_type":"item","slug":"armas_sw_80_parallax_rifle_de_precisao","payload":{"id":"armas_sw_80_parallax_rifle_de_precisao","slug":"armas_sw_80_parallax_rifle_de_precisao","nome":"SW-80 Widowmaker (Rifle de precisão)","raridade":"muito_raro","raridade_label":"Muito Raro","preco":5500,"preco_texto":"5.500","preco_qualificador":null,"descricao_curta":"A **SW-80 Widowmaker** é o rifle de precisão da família **Sidewinder**. Sensores de longo alcance acompanham o projétil durante praticamente todo o percurso, transmitindo correções sucessivas para que ele altere o curso mesmo a centenas de metros do atirador.","descricao_longa":"*Muito raro*\n\nA **SW-80 Widowmaker** é o rifle de precisão da família **Sidewinder**. Sensores de longo alcance acompanham o projétil durante praticamente todo o percurso, transmitindo correções sucessivas para que ele altere o curso mesmo a centenas de metros do atirador.\n\nA Widowmaker transforma posições que normalmente ofereceriam proteção em soluções temporárias. Um disparo pode contornar uma cobertura e ainda conservar trajetória suficiente para atingir outra criatura próxima ao primeiro alvo.\n\n**Trajetória serpentina:** ataques com a Widowmaker ignoram cobertura parcial. Depois de atingir uma criatura, o projétil pode continuar até outra criatura a até 2 m dela. Compare o mesmo resultado do teste de ataque com a Defesa do segundo alvo. Caso também o atinja, determine normalmente a região atingida pela nova margem e cause metade do dano.\n\nO segundo impacto não consome munição adicional, não pode gerar sucesso crítico e não ativa propriedades ou efeitos que dependam de um sucesso crítico. As demais propriedades da arma funcionam normalmente. O projétil não pode continuar para um terceiro alvo.\n\n**Munição:** 2\n\n**Dano:** 2d10 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Perfuração, Precisão\n\n**Alcance:** 400 m eficaz, até 800 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 5.500 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 2d10 perfurante\n- Mãos: 2\n- Propriedades: Sangramento, Perfuração, Precisão\n- Munição: 2\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 5.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"SW-80 Widowmaker (Rifle de precisão)","Dano":"2d10 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"2","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"5fef05aa6e944c36a96b205af47339c5","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"SW-80 Widowmaker (Rifle de precisão)","Dano":"2d10 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"2","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.500"},"espacos_texto":"3","dado_dano":"2d10","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":2,"propriedades":["sangramento","perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":400,"max_m":800,"penalidade_alem_eficaz":-2},"municao_max":2,"municao_compativel":"mun_precisao"},"ocultavel":"nao"},"id":"item:armas_sw_80_parallax_rifle_de_precisao","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"a4c31413a537a7ab3623a411e43bb6ef66c9d029e7b9fb1c92d5b32b1ea20dba"},{"content_type":"item","slug":"armas_as_86_terminal_rifle_de_precisao","payload":{"id":"armas_as_86_terminal_rifle_de_precisao","slug":"armas_as_86_terminal_rifle_de_precisao","nome":"AS-86 Terminal (Rifle de precisão)","raridade":"muito_raro","raridade_label":"Muito Raro","preco":5000,"preco_texto":"5.000","preco_qualificador":null,"descricao_curta":"A **AS-86 Terminal** é o rifle de precisão da família **Aftershock**. Seu sistema de propulsão foi desenvolvido para manter o projétil acelerando por uma parcela significativa do percurso, transformando distância em força de impacto.","descricao_longa":"*Muito raro*\n\nA **AS-86 Terminal** é o rifle de precisão da família **Aftershock**. Seu sistema de propulsão foi desenvolvido para manter o projétil acelerando por uma parcela significativa do percurso, transformando distância em força de impacto.\n\nA Terminal é particularmente perigosa em campos abertos e linhas de tiro extensas, onde o projétil alcança sua velocidade máxima muito antes de encontrar o alvo.\n\n**Aceleração terminal:** quando a Terminal atinge um alvo a 50 m ou mais, seu dano passa de 2d10 para 2d12 nesse ataque.\n\n**Munição:** 2\n\n**Dano:** 2d10 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Perfuração, Precisão\n\n**Alcance:** 400 m eficaz, até 800 m com –2 de desvantagem\n\n**Espaços:** 3\n\n**Preço:** 5.000 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 2d10 perfurante\n- Mãos: 2\n- Propriedades: Sangramento, Perfuração, Precisão\n- Munição: 2\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 5.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"AS-86 Terminal (Rifle de precisão)","Dano":"2d10 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"2","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"c3aae6ec0afc4a11b5941e2f5fd79808","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"AS-86 Terminal (Rifle de precisão)","Dano":"2d10 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"2","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.000"},"espacos_texto":"3","dado_dano":"2d10","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":2,"propriedades":["sangramento","perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":400,"max_m":800,"penalidade_alem_eficaz":-2},"municao_max":2,"municao_compativel":"mun_precisao"},"ocultavel":"nao"},"id":"item:armas_as_86_terminal_rifle_de_precisao","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"cae54f6a7ede02513406e11cb6d032e133d4a97b504fd25d4c22150be0f530cc"},{"content_type":"item","slug":"armas_as_127_wrecker_rifle_antimaterial","payload":{"id":"armas_as_127_wrecker_rifle_antimaterial","slug":"armas_as_127_wrecker_rifle_antimaterial","nome":"AS-127 Wrecker (Rifle antimaterial)","raridade":"muito_raro","raridade_label":"Muito Raro","preco":7000,"preco_texto":"7.000","preco_qualificador":null,"descricao_curta":"A **AS-127 Wrecker** é o rifle antimaterial da família **Aftershock**. Sua estrutura reforçada suporta projéteis pesados equipados com propulsão secundária, feitos para continuar acelerando muito depois de deixar o cano.","descricao_longa":"*Muito raro*\n\nA **AS-127 Wrecker** é o rifle antimaterial da família **Aftershock**. Sua estrutura reforçada suporta projéteis pesados equipados com propulsão secundária, feitos para continuar acelerando muito depois de deixar o cano.\n\nQuando recebe distância suficiente, a Wrecker atinge força capaz de atravessar proteção pessoal e comprometer barricadas, escudos e componentes estruturais.\n\n**Aceleração terminal:** quando a Wrecker atinge um alvo a 50 m ou mais, seu dano passa de 3d8 para 3d10 nesse ataque.\n\nEnquanto Aceleração terminal estiver ativa, o dano causado pela Wrecker aos PD de objetos, escudos, coberturas, estruturas, drones e robôs é dobrado.\n\n**Munição:** 1\n\n**Dano:** 3d8 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Perfuração, Precisão\n\n**Alcance:** 400 m eficaz, até 800 m com –2 de desvantagem\n\n**Espaços:** 3\n\n**Preço:** 7.000 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 3d8 perfurante\n- Mãos: 2\n- Propriedades: Sangramento, Perfuração, Precisão\n- Munição: 1\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 7.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"AS-127 Wrecker (Rifle antimaterial)","Dano":"3d8 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"1","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"7.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"5e4b607df1084244b2003f3e7364ba2a","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"AS-127 Wrecker (Rifle antimaterial)","Dano":"3d8 perfurante","Mãos":"2","Propriedades":"Sangramento, Perfuração, Precisão","Munição":"1","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"7.000"},"espacos_texto":"3","dado_dano":"3d8","tipo_dano":"fisico","subtipo_dano":"perfurante","maos":2,"propriedades":["sangramento","perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":400,"max_m":800,"penalidade_alem_eficaz":-2},"municao_max":1},"ocultavel":"nao"},"id":"item:armas_as_127_wrecker_rifle_antimaterial","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"0ebf20f3faed36ebf8a909339d9e4093bdc829d69e4fa1927117070772c0d830"},{"content_type":"item","slug":"armas_metralhadora","payload":{"id":"armas_metralhadora","slug":"armas_metralhadora","nome":"Metralhadora","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"2.500","preco_qualificador":null,"descricao_curta":"*Muito rara*","descricao_longa":"*Muito rara*\n\nProjetada para supressão, dispara rajadas contínuas capazes de varrer áreas inteiras. Seu peso elevado e consumo rápido de munição tornam-na pouco prática fora de combates planejados, mas absolutamente devastadora quando em posição.\n\n**Munição:** 80 (10 balas por disparo)\n\n**Dano:** 1d8 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Rajada (4)\n\n**Alcance:** 100 m eficaz, até 250 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 2.500 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 1d8\n- Mãos: 2\n- Propriedades: Sangramento, Rajada (4)\n- Munição: 80\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 2.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Metralhadora","Dano":"1d8","Mãos":"2","Propriedades":"Sangramento, Rajada (4)","Munição":"80","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"70cf58dd49584c31b10f020c4f38d34c","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"Metralhadora","Dano":"1d8","Mãos":"2","Propriedades":"Sangramento, Rajada (4)","Munição":"80","Ocultável?":"Não","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"2.500"},"espacos_texto":"3","dado_dano":"1d8","maos":2,"rajada_x":4,"propriedades":["sangramento","rajada"],"pericia_teste":"balistica","slots_runa_max":3,"tipo_dano":"fisico","subtipo_dano":"perfurante","alcance":{"tipo":"distancia","eficaz_m":100,"max_m":250,"penalidade_alem_eficaz":-2},"municao_max":80,"municao_compativel":"mun_fuzil"},"ocultavel":"nao"},"id":"item:armas_metralhadora","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"375489f9fcad4d15c9d0cddbbe48a1fc3103ac8e0a9c4811904c75fc81041184"},{"content_type":"item","slug":"armas_dl_66_widowmaker_metralhadora","payload":{"id":"armas_dl_66_widowmaker_metralhadora","slug":"armas_dl_66_widowmaker_metralhadora","nome":"DL-66 Maelstrom (Metralhadora)","raridade":"muito_raro","raridade_label":"Muito Raro","preco":4000,"preco_texto":"4.000","preco_qualificador":null,"descricao_curta":"A **DL-66 Maelstrom** é a metralhadora da família **Deadlock**. O peso da estrutura é aproveitado por um sistema de compensação que redistribui o recuo durante o disparo, mantendo o cano sobre o alvo enquanto dezenas de balas atravessam o mecanismo.","descricao_longa":"*Muito raro*\n\nA **DL-66 Maelstrom** é a metralhadora da família **Deadlock**. O peso da estrutura é aproveitado por um sistema de compensação que redistribui o recuo durante o disparo, mantendo o cano sobre o alvo enquanto dezenas de balas atravessam o mecanismo.\n\nColocada em posição e usada a curta distância, a Maelstrom concentra um volume de fogo difícil de reproduzir com armas automáticas convencionais.\n\n**Controle Deadlock:** ao utilizar Rajada (4) contra uma criatura a até 10 m, a Maelstrom não sofre a desvantagem imposta por Rajada. Outras fontes de desvantagem continuam funcionando normalmente. Se o ataque acertar, cada disparo causa +1 de dano, totalizando +4 de dano na Rajada.\n\n**Munição:** 80. Cada disparo consome 10 balas. Rajada (4) consome 40 balas.\n\n**Dano:** 1d8 perfurante\n\n**Mãos:** 2\n\n**Propriedades:** Sangramento, Rajada (4)\n\n**Alcance:** 100 m eficaz, até 250 m com –2 de desvantagem\n\n**Espaços:** 3\n\n**Preço:** 4.000 Ⱥ\n\nDados da lista de mercadorias:\n- Dano: 1d8 perfurante\n- Mãos: 2\n- Propriedades: Sangramento, Rajada (4)\n- Munição: 80\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 4.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE FOGO","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"DL-66 Maelstrom (Metralhadora)","Dano":"1d8 perfurante","Mãos":"2","Propriedades":"Sangramento, Rajada (4)","Munição":"80","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"4.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"6d0b29743de84945882e67c5cf296e4e","linhaBlocoId":"d4132da802224d6f9467b5bcf11fbb39","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE FOGO","estatisticas":{"campos_tabela":{"Arma":"DL-66 Maelstrom (Metralhadora)","Dano":"1d8 perfurante","Mãos":"2",