f9148439f465b2cff0cc6d8","linhaBlocoId":"b8604e99329b43219de0346a09ccaf69","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"municao","categoria_label":"Munição","subtipo":"Munição","estatisticas":{"campos_tabela":{"Munição":"Precisão","Compatibilidade":"Rifle de precisão","Kit":"5 projéteis","Raridade":"Raro","Espaços":"1 (kit)","Preço (Ⱥ)":"150"},"espacos_texto":"1 (kit)","kit":"5 projéteis","compatibilidade":{"familia":"mun_precisao","itens":["armas_rifle_de_precisao","armas_sw_80_parallax_rifle_de_precisao","armas_as_86_terminal_rifle_de_precisao"]}}},"id":"item:armas_precisao","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"5c61dbc5c70f9f9c6d48d40b2e99a29a06ab3efa66dfa1d29fc0160ec920ecc1"},{"content_type":"item","slug":"armas_pistola_de_feixe","payload":{"id":"armas_pistola_de_feixe","slug":"armas_pistola_de_feixe","nome":"Pistola de feixe","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"Um emissor compacto que concentra energia térmica em uma linha estreita. O disparo atravessa o ar como um traço branco ou avermelhado, queimando o ponto atingido e deixando ferimentos cauterizados.","descricao_longa":"*Raro*\n\nUm emissor compacto que concentra energia térmica em uma linha estreita. O disparo atravessa o ar como um traço branco ou avermelhado, queimando o ponto atingido e deixando ferimentos cauterizados.\n\nPossui pouco recuo e excelente estabilidade, sendo comum entre agentes que valorizam precisão e facilidade de porte.\n\n**Corte térmico:** ataques contra objetos, coberturas e estruturas causam **+1d6 de dano** e ignoram **2 PD**. Com tempo suficiente, o feixe pode cortar fechaduras, grades, chapas finas e componentes expostos.\n\n**Cargas:** 8\n\n**Dano:** 1d6 ígneo\n\n**Mãos:** 1\n\n**Propriedades:** Precisão\n\n**Alcance:** 30 m eficaz, até 60 m com –2 de desvantagem\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 1.500 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 8\n- Dano: 1d6 ígneo\n- Mãos: 1\n- Propriedades: Precisão\n- Ocultável?: Sim\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Pistola de feixe","Cargas":"8","Dano":"1d6 ígneo","Mãos":"1","Propriedades":"Precisão","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"db818d43ae5045e48b492fc214a83542","linhaBlocoId":"800fafa4efd24056b1783266bc1065c9","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Pistola de feixe","Cargas":"8","Dano":"1d6 ígneo","Mãos":"1","Propriedades":"Precisão","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.500"},"espacos_texto":"1","dado_dano":"1d6","tipo_dano":"energetico","subtipo_dano":"igneo","maos":1,"propriedades":["precisao"],"pericia_teste":"balistica","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":30,"max_m":60,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"celula_energia_8"},"ocultavel":"sim"},"id":"item:armas_pistola_de_feixe","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"656f905f712797805c16fb209ef6526874b967293e3a37c8cc4791e5587f35a6"},{"content_type":"item","slug":"armas_fundidora","payload":{"id":"armas_fundidora","slug":"armas_fundidora","nome":"Fundidora","raridade":"raro","raridade_label":"Raro","preco":1600,"preco_texto":"1.600","preco_qualificador":null,"descricao_curta":"A fundidora comprime calor dentro de uma câmara curta e o libera como um pulso térmico espesso. O disparo perde coesão rapidamente, mas dentro do alcance ideal é capaz de carbonizar tecidos, derreter plástico e inflamar materiais expostos.","descricao_longa":"*Raro*\n\nA fundidora comprime calor dentro de uma câmara curta e o libera como um pulso térmico espesso. O disparo perde coesão rapidamente, mas dentro do alcance ideal é capaz de carbonizar tecidos, derreter plástico e inflamar materiais expostos.\n\nÉ popular em invasões, confrontos dentro de veículos e operações conduzidas em corredores estreitos.\n\n**Carga residual:** depois de acertar uma criatura, você pode consumir 1 carga adicional para manter parte do calor acumulado no corpo dela. Caso o alvo gaste seu 3º PA antes do início do seu próximo turno, sofre **1d4 de dano ígneo**.\n\n**Cargas:** 8\n\n**Dano:** 1d8 ígneo\n\n**Mãos:** 1\n\n**Propriedades:** Queimadura\n\n**Alcance:** 8 m eficaz, até 16 m com –2 de desvantagem\n\n**Ocultável:** parcial\n\n**Espaços:** 1\n\n**Preço:** 1.600 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 8\n- Dano: 1d8 ígneo\n- Mãos: 1\n- Propriedades: Queimadura\n- Ocultável?: Parcial\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.600","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Fundidora","Cargas":"8","Dano":"1d8 ígneo","Mãos":"1","Propriedades":"Queimadura","Ocultável?":"Parcial","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.600"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"db818d43ae5045e48b492fc214a83542","linhaBlocoId":"343c57744ec14b0f821543897821214f","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Fundidora","Cargas":"8","Dano":"1d8 ígneo","Mãos":"1","Propriedades":"Queimadura","Ocultável?":"Parcial","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.600"},"espacos_texto":"1","dado_dano":"1d8","tipo_dano":"energetico","subtipo_dano":"igneo","maos":1,"propriedades":["queimadura"],"pericia_teste":"balistica","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":8,"max_m":16,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"celula_energia_8"},"ocultavel":"parcial"},"id":"item:armas_fundidora","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"3e21cddee4e26df87ce7188474fff744248ea3b0c354ea18ef239452805a7e71"},{"content_type":"item","slug":"armas_pistola_voltaica","payload":{"id":"armas_pistola_voltaica","slug":"armas_pistola_voltaica","nome":"Pistola voltaica","raridade":"raro","raridade_label":"Raro","preco":1700,"preco_texto":"1.700","preco_qualificador":null,"descricao_curta":"Conhecida nas ruas como *arqueador*, utiliza dois condutores frontais para lançar uma descarga elétrica concentrada. O arco percorre o corpo atingido, provocando espasmos musculares e interferências breves em escalpos conectados ao sistema nervoso.","descricao_longa":"*Raro*\n\nConhecida nas ruas como *arqueador*, utiliza dois condutores frontais para lançar uma descarga elétrica concentrada. O arco percorre o corpo atingido, provocando espasmos musculares e interferências breves em escalpos conectados ao sistema nervoso.\n\nÉ utilizada por equipes de captura, seguranças privados e grupos que precisam incapacitar alvos sem depender apenas de dano bruto.\n\n**Neurochoque:** antes de atacar, você pode consumir 1 carga adicional e reduzir o dano do disparo para **1d4 elétrico**. Caso acerte, o alvo não pode realizar Reações até o início do próximo turno dele. Criaturas sem sistema nervoso são imunes a esse efeito.\n\n**Cargas:** 8\n\n**Dano:** 1d6 elétrico\n\n**Mãos:** 1\n\n**Propriedades:** Atordoamento\n\n**Alcance:** 15 m eficaz, até 30 m com –2 de desvantagem\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 1.700 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 8\n- Dano: 1d6 elétrico\n- Mãos: 1\n- Propriedades: Atordoamento\n- Ocultável?: Sim\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.700","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Pistola voltaica","Cargas":"8","Dano":"1d6 elétrico","Mãos":"1","Propriedades":"Atordoamento","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.700"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"db818d43ae5045e48b492fc214a83542","linhaBlocoId":"45cdd46dcb76498392903792be8e2644","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Pistola voltaica","Cargas":"8","Dano":"1d6 elétrico","Mãos":"1","Propriedades":"Atordoamento","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.700"},"espacos_texto":"1","dado_dano":"1d6","tipo_dano":"energetico","subtipo_dano":"eletrico","maos":1,"propriedades":["atordoamento"],"pericia_teste":"balistica","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":15,"max_m":30,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"celula_energia_8"},"ocultavel":"sim"},"id":"item:armas_pistola_voltaica","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"94083673b70989b39341fbd8997007b5f71141f5c765a4d38531f1456c49ae29"},{"content_type":"item","slug":"armas_crioagulha","payload":{"id":"armas_crioagulha","slug":"armas_crioagulha","nome":"Crioagulha","raridade":"raro","raridade_label":"Raro","preco":1700,"preco_texto":"1.700","preco_qualificador":null,"descricao_curta":"A crioagulha projeta um feixe quase invisível que remove calor de uma área muito pequena. Em vez de congelar o alvo por inteiro, concentra o efeito sobre músculos, juntas, cabos, dobradiças ou componentes expostos.","descricao_longa":"*Raro*\n\nA crioagulha projeta um feixe quase invisível que remove calor de uma área muito pequena. Em vez de congelar o alvo por inteiro, concentra o efeito sobre músculos, juntas, cabos, dobradiças ou componentes expostos.\n\nSeu dano direto é limitado, mas o congelamento localizado prejudica movimentos e torna materiais quebradiços.\n\n**Fratura térmica:** depois de acertar, escolha o alvo ou um objeto que ele esteja carregando. O próximo ataque físico que atingir o elemento escolhido antes do fim do próximo turno ignora **1 MIT ou 2 PD**. O efeito termina depois de beneficiar um ataque.\n\n**Cargas:** 8\n\n**Dano:** 1d4 gélido\n\n**Mãos:** 1\n\n**Propriedades:** Congelamento, Precisão\n\n**Alcance:** 20 m eficaz, até 40 m com –2 de desvantagem\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 1.700 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 8\n- Dano: 1d4 gélido\n- Mãos: 1\n- Propriedades: Congelamento, Precisão\n- Ocultável?: Sim\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.700","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Crioagulha","Cargas":"8","Dano":"1d4 gélido","Mãos":"1","Propriedades":"Congelamento, Precisão","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.700"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"db818d43ae5045e48b492fc214a83542","linhaBlocoId":"82fa8ab459b145e9adddb6cba152c3d8","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Crioagulha","Cargas":"8","Dano":"1d4 gélido","Mãos":"1","Propriedades":"Congelamento, Precisão","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.700"},"espacos_texto":"1","dado_dano":"1d4","tipo_dano":"energetico","subtipo_dano":"gelido","maos":1,"propriedades":["congelamento","precisao"],"pericia_teste":"balistica","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":20,"max_m":40,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"celula_energia_8"},"ocultavel":"sim"},"id":"item:armas_crioagulha","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9655cbb79c799e77356f72cc82c84f44ca77c879abb641cbbc5f5c806b775bd8"},{"content_type":"item","slug":"armas_ofuscador","payload":{"id":"armas_ofuscador","slug":"armas_ofuscador","nome":"Ofuscador","raridade":"raro","raridade_label":"Raro","preco":1400,"preco_texto":"1.400","preco_qualificador":null,"descricao_curta":"Originalmente desenvolvido para contenção civil, o ofuscador projeta um pulso de luz coerente diretamente contra o campo visual do alvo. O clarão aquece a superfície atingida, mas sua principal função é saturar olhos e sensores ópticos.","descricao_longa":"*Raro*\n\nOriginalmente desenvolvido para contenção civil, o ofuscador projeta um pulso de luz coerente diretamente contra o campo visual do alvo. O clarão aquece a superfície atingida, mas sua principal função é saturar olhos e sensores ópticos.\n\nO disparo não produz explosão ou estampido, embora o clarão ainda possa denunciar a trajetória da arma.\n\n**Cargas:** 8\n\n**Dano:** 1d4 ígneo\n\n**Mãos:** 1\n\n**Propriedades:** Ofuscamento, Silencioso\n\n**Alcance:** 12 m eficaz, até 24 m com –2 de desvantagem\n\n**Clarão difuso:** em vez de realizar um ataque comum, consuma 2 cargas para projetar um cone de 4 metros. Faça um único teste de **`Balística`** e compare o resultado com a ação defensiva de cada criatura na área. Criaturas atingidas ficam **`Ofuscadas`** até o fim do próximo turno delas. Essa descarga não causa dano.\n\n**Ocultável:** sim\n\n**Espaços:** 1\n\n**Preço:** 1.400 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 8\n- Dano: 1d4 ígneo\n- Mãos: 1\n- Propriedades: Ofuscamento, Silencioso\n- Ocultável?: Sim\n- Raridade: Raro\n- Espaços: 1\n- Preço (Ⱥ): 1.400","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS LEVES"],"tipo_tabela":"Arma","campos":{"Arma":"Ofuscador","Cargas":"8","Dano":"1d4 ígneo","Mãos":"1","Propriedades":"Ofuscamento, Silencioso","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.400"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"db818d43ae5045e48b492fc214a83542","linhaBlocoId":"ce3639ed58f748c2ba41510a84b9d0ab","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Ofuscador","Cargas":"8","Dano":"1d4 ígneo","Mãos":"1","Propriedades":"Ofuscamento, Silencioso","Ocultável?":"Sim","Raridade":"Raro","Espaços":"1","Preço (Ⱥ)":"1.400"},"espacos_texto":"1","dado_dano":"1d4","tipo_dano":"energetico","subtipo_dano":"igneo","maos":1,"propriedades":["ofuscamento","silencioso"],"pericia_teste":"balistica","slots_runa_max":1,"alcance":{"tipo":"distancia","eficaz_m":12,"max_m":24,"penalidade_alem_eficaz":-2},"municao_max":8,"municao_compativel":"celula_energia_8"},"ocultavel":"sim"},"id":"item:armas_ofuscador","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"521facbced866d30a76a962a5ea19e90997a690d7978602de53579b6b0e1e931"},{"content_type":"item","slug":"armas_carabina_de_feixe","payload":{"id":"armas_carabina_de_feixe","slug":"armas_carabina_de_feixe","nome":"Carabina de feixe","raridade":"raro","raridade_label":"Raro","preco":3000,"preco_texto":"3.000","preco_qualificador":null,"descricao_curta":"Versão ampliada da pistola de feixe, equipada com lentes de cristalídeo capazes de manter a descarga coesa por distâncias maiores. O feixe atravessa proteções leves e atinge o alvo antes que a linha luminosa desapareça.","descricao_longa":"*Raro*\n\nVersão ampliada da pistola de feixe, equipada com lentes de cristalídeo capazes de manter a descarga coesa por distâncias maiores. O feixe atravessa proteções leves e atinge o alvo antes que a linha luminosa desapareça.\n\nÉ uma das armas mais comuns entre unidades imperiais treinadas para enfrentar magistas e criaturas vestigiais.\n\n**Atravessamento:** depois de acertar uma criatura, você pode consumir 1 carga adicional para prolongar o feixe. Escolha outro alvo diretamente atrás do primeiro e a até 3 metros dele. Compare o resultado original do ataque com a ação defensiva do segundo alvo. Caso também o atinja, ele sofre metade do dano, arredondado para baixo.\n\n**Cargas:** 12\n\n**Dano:** 1d8 ígneo\n\n**Mãos:** 2\n\n**Propriedades:** Perfuração, Precisão\n\n**Alcance:** 80 m eficaz, até 160 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 3.000 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 12\n- Dano: 1d8 ígneo\n- Mãos: 2\n- Propriedades: Perfuração, Precisão\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 3.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Carabina de feixe","Cargas":"12","Dano":"1d8 ígneo","Mãos":"2","Propriedades":"Perfuração, Precisão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"3154938c28b54d48ab6349854e3de65e","linhaBlocoId":"f812c97d86184fdfb988ce8dab18ce91","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Carabina de feixe","Cargas":"12","Dano":"1d8 ígneo","Mãos":"2","Propriedades":"Perfuração, Precisão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.000"},"espacos_texto":"2","dado_dano":"1d8","tipo_dano":"energetico","subtipo_dano":"igneo","maos":2,"propriedades":["perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":2,"alcance":{"tipo":"distancia","eficaz_m":80,"max_m":160,"penalidade_alem_eficaz":-2},"municao_max":12,"municao_compativel":"celula_energia_12"},"ocultavel":"nao"},"id":"item:armas_carabina_de_feixe","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"dd78518efec6fce79f1234fd785a007f0d8d672160d4d90467fad55817aa6af2"},{"content_type":"item","slug":"armas_repetidora_termica","payload":{"id":"armas_repetidora_termica","slug":"armas_repetidora_termica","nome":"Repetidora térmica","raridade":"raro","raridade_label":"Raro","preco":2800,"preco_texto":"2.800","preco_qualificador":null,"descricao_curta":"Utiliza uma sequência de câmaras menores para disparar pulsos térmicos em rápida sucessão. Cada descarga isolada é menos intensa que a de uma carabina, mas a cadência permite cobrir corredores, pressionar múltiplos alvos ou concentrar fogo sobre uma única posição.","descricao_longa":"*Raro*\n\nUtiliza uma sequência de câmaras menores para disparar pulsos térmicos em rápida sucessão. Cada descarga isolada é menos intensa que a de uma carabina, mas a cadência permite cobrir corredores, pressionar múltiplos alvos ou concentrar fogo sobre uma única posição.\n\nO cano permanece incandescente após uma rajada prolongada, tornando seu usuário facilmente identificável.\n\n**Supressão incandescente:** ao utilizar *Rajada (3)*, os disparos podem ser distribuídos entre criaturas diferentes que estejam a até 3 metros umas das outras. Depois da rajada, escolha uma área de 2 × 2 metros atravessada pelos disparos. Até o início do seu próximo turno, a primeira criatura que entrar ou terminar seu turno nessa área sofre **1d4 de dano ígneo**.\n\n**Cargas:** 24\n\n**Dano:** 1d6 ígneo\n\n**Mãos:** 2\n\n**Propriedades:** Rajada (3)\n\n**Alcance:** 30 m eficaz, até 60 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 2.800 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 24\n- Dano: 1d6 ígneo\n- Mãos: 2\n- Propriedades: Rajada (3)\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 2.800","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Repetidora térmica","Cargas":"24","Dano":"1d6 ígneo","Mãos":"2","Propriedades":"Rajada (3)","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"2.800"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"3154938c28b54d48ab6349854e3de65e","linhaBlocoId":"80956e6bb4c94a4ca1a15aa6b89ec80d","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Repetidora térmica","Cargas":"24","Dano":"1d6 ígneo","Mãos":"2","Propriedades":"Rajada (3)","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"2.800"},"espacos_texto":"2","dado_dano":"1d6","tipo_dano":"energetico","subtipo_dano":"igneo","maos":2,"rajada_x":3,"propriedades":["rajada"],"pericia_teste":"balistica","slots_runa_max":2,"alcance":{"tipo":"distancia","eficaz_m":30,"max_m":60,"penalidade_alem_eficaz":-2},"municao_max":24,"municao_compativel":"celula_energia_24"},"ocultavel":"nao"},"id":"item:armas_repetidora_termica","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"de25e73bc87b896d0de7362e162b1a864ed9624cc0aa845d804e0740fbbe5cb7"},{"content_type":"item","slug":"armas_fuzil_voltaico","payload":{"id":"armas_fuzil_voltaico","slug":"armas_fuzil_voltaico","nome":"Fuzil voltaico","raridade":"raro","raridade_label":"Raro","preco":3200,"preco_texto":"3.200","preco_qualificador":null,"descricao_curta":"O fuzil voltaico projeta descargas elétricas estabilizadas por um campo condutor temporário. O arco percorre o alvo e se dissipa pelo ambiente, afetando músculos, nervos e componentes conectados ao corpo.","descricao_longa":"*Raro*\n\nO fuzil voltaico projeta descargas elétricas estabilizadas por um campo condutor temporário. O arco percorre o alvo e se dissipa pelo ambiente, afetando músculos, nervos e componentes conectados ao corpo.\n\nÉ especialmente valorizado em operações de captura de magistas, nas quais impedir reações costuma ser mais importante que provocar morte imediata.\n\n**Arco derivado:** depois de causar dano, você pode consumir 1 carga adicional e escolher outra criatura a até 3 metros do alvo original. Ela sofre **1d4 de dano elétrico**. O arco não atravessa barreiras sólidas.\n\n**Cargas:** 12\n\n**Dano:** 1d8 elétrico\n\n**Mãos:** 2\n\n**Propriedades:** Atordoamento\n\n**Alcance:** 50 m eficaz, até 100 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 3.200 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 12\n- Dano: 1d8 elétrico\n- Mãos: 2\n- Propriedades: Atordoamento\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 3.200","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Fuzil voltaico","Cargas":"12","Dano":"1d8 elétrico","Mãos":"2","Propriedades":"Atordoamento","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"3154938c28b54d48ab6349854e3de65e","linhaBlocoId":"ebb43024128e450296f6fbf9f2e7aa31","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Fuzil voltaico","Cargas":"12","Dano":"1d8 elétrico","Mãos":"2","Propriedades":"Atordoamento","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.200"},"espacos_texto":"2","dado_dano":"1d8","tipo_dano":"energetico","subtipo_dano":"eletrico","maos":2,"propriedades":["atordoamento"],"pericia_teste":"balistica","slots_runa_max":2,"alcance":{"tipo":"distancia","eficaz_m":50,"max_m":100,"penalidade_alem_eficaz":-2},"municao_max":12,"municao_compativel":"celula_energia_12"},"ocultavel":"nao"},"id":"item:armas_fuzil_voltaico","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"86d655eec2945695f30b2ea65ebf8850bfeaa8aea4dac7c44902ca3cb4162c24"},{"content_type":"item","slug":"armas_disruptor","payload":{"id":"armas_disruptor","slug":"armas_disruptor","nome":"Disruptor","raridade":"raro","raridade_label":"Raro","preco":3500,"preco_texto":"3.500","preco_qualificador":null,"descricao_curta":"O disruptor não produz uma descarga elétrica convencional. Seu emissor projeta um pulso eletromagnético estreito, calibrado para atravessar blindagens externas e interferir em circuitos, runas, sensores e conexões tecnomágicas.","descricao_longa":"*Raro*\n\nO disruptor não produz uma descarga elétrica convencional. Seu emissor projeta um pulso eletromagnético estreito, calibrado para atravessar blindagens externas e interferir em circuitos, runas, sensores e conexões tecnomágicas.\n\nContra um corpo sem componentes tecnológicos, o efeito é comparável ao de uma arma elétrica leve. Contra escalpos, drones, robôs e equipamentos de energia, pode interromper funções críticas por tempo suficiente para decidir um confronto.\n\n**Cargas:** 12\n\n**Dano:** 1d6 elétrico\n\n**Mãos:** 2\n\n**Propriedades:** Disrupção, Precisão\n\n**Alcance:** 40 m eficaz, até 80 m com –2 de desvantagem\n\n**Pane forçada:** antes de atacar, você pode consumir 2 cargas adicionais e declarar uma Pane forçada. O ataque não causa dano. Caso acerte, escolha um escalpo, arma de energia, runa ativa ou equipamento tecnológico conhecido no alvo. O componente fica inativo até o fim do próximo turno do alvo.\n\nDrones, robôs e veículos podem reagir com **Resistir** contra o resultado do ataque para evitar a pane.\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 3.500 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 12\n- Dano: 1d6 elétrico\n- Mãos: 2\n- Propriedades: Disrupção, Precisão\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 3.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Disruptor","Cargas":"12","Dano":"1d6 elétrico","Mãos":"2","Propriedades":"Disrupção, Precisão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"3154938c28b54d48ab6349854e3de65e","linhaBlocoId":"0aabf7f27b524b72ae172fbaa01bb8b2","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Disruptor","Cargas":"12","Dano":"1d6 elétrico","Mãos":"2","Propriedades":"Disrupção, Precisão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.500"},"espacos_texto":"2","dado_dano":"1d6","tipo_dano":"energetico","subtipo_dano":"eletrico","maos":2,"propriedades":["disrupcao","precisao"],"pericia_teste":"balistica","slots_runa_max":2,"alcance":{"tipo":"distancia","eficaz_m":40,"max_m":80,"penalidade_alem_eficaz":-2},"municao_max":12,"municao_compativel":"celula_energia_12"},"ocultavel":"nao"},"id":"item:armas_disruptor","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"ceb6f40eb5115b6bdc3b0cee75a3ac606b16cac54081e921a618c654794784b9"},{"content_type":"item","slug":"armas_criojetor","payload":{"id":"armas_criojetor","slug":"armas_criojetor","nome":"Criojetor","raridade":"raro","raridade_label":"Raro","preco":3000,"preco_texto":"3.000","preco_qualificador":null,"descricao_curta":"Arma de cano largo que libera uma nuvem de partículas resfriadas. O disparo cobre uma região curta à frente do usuário, congelando superfícies, endurecendo tecidos e criando placas de gelo sobre tudo o que alcançar.","descricao_longa":"*Raro*\n\nArma de cano largo que libera uma nuvem de partículas resfriadas. O disparo cobre uma região curta à frente do usuário, congelando superfícies, endurecendo tecidos e criando placas de gelo sobre tudo o que alcançar.\n\nA nuvem se espalha ao redor de pequenas coberturas, mas perde densidade rapidamente fora do alcance ideal.\n\n**Campo congelado:** depois de disparar, o terreno em um cone de 4 metros permanece congelado até o início do seu próximo turno. A área é considerada terreno difícil. Na primeira vez que uma criatura se deslocar pelo menos 2 metros dentro dela durante uma rodada, deve testar **`Reflexos`**, CD 7. Em falha, termina **`Caída`**.\n\n**Cargas:** 12\n\n**Dano:** 1d10 gélido\n\n**Mãos:** 2\n\n**Propriedades:** Congelamento, Dispersão\n\n**Alcance:** 8 m eficaz, até 16 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 3.000 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 12\n- Dano: 1d10 gélido\n- Mãos: 2\n- Propriedades: Congelamento, Dispersão\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 3.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Criojetor","Cargas":"12","Dano":"1d10 gélido","Mãos":"2","Propriedades":"Congelamento, Dispersão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"3154938c28b54d48ab6349854e3de65e","linhaBlocoId":"cd633586a22e491e97ec00a4caba6204","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Criojetor","Cargas":"12","Dano":"1d10 gélido","Mãos":"2","Propriedades":"Congelamento, Dispersão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.000"},"espacos_texto":"2","dado_dano":"1d10","tipo_dano":"energetico","subtipo_dano":"gelido","maos":2,"propriedades":["congelamento","dispersao"],"pericia_teste":"balistica","slots_runa_max":2,"alcance":{"tipo":"distancia","eficaz_m":8,"max_m":16,"penalidade_alem_eficaz":-2},"municao_max":12,"municao_compativel":"celula_energia_12"},"ocultavel":"nao"},"id":"item:armas_criojetor","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"f5e088480f899b8a482bda7f1a3e9ded3adeea41351cb62ccb17b6b7ebed6bad"},{"content_type":"item","slug":"armas_ressonador","payload":{"id":"armas_ressonador","slug":"armas_ressonador","nome":"Ressonador","raridade":"raro","raridade_label":"Raro","preco":3200,"preco_texto":"3.200","preco_qualificador":null,"descricao_curta":"O ressonador converte a carga da célula em uma onda de pressão sonora. O disparo não queima ou eletrocuta: comprime o ar e atinge o alvo como um impacto invisível, capaz de romper tímpanos, desequilibrar corpos e deslocar objetos.","descricao_longa":"*Raro*\n\nO ressonador converte a carga da célula em uma onda de pressão sonora. O disparo não queima ou eletrocuta: comprime o ar e atinge o alvo como um impacto invisível, capaz de romper tímpanos, desequilibrar corpos e deslocar objetos.\n\nComo causa dano físico contundente, seu ataque pode ser reduzido por armaduras físicas.\n\n**Onda ampla:** em vez de realizar um ataque comum, consuma 2 cargas para atingir todas as criaturas em um cone de 4 metros. Faça um único teste de **`Balística`** e compare-o com cada ação defensiva. O dano da descarga é reduzido para **1d6 contundente**, e cada criatura atingida é empurrada 1 metro.\n\n**Cargas:** 12\n\n**Dano:** 1d10 contundente\n\n**Mãos:** 2\n\n**Propriedades:** Contusão, Empurrão\n\n**Alcance:** 15 m eficaz, até 30 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 3.200 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 12\n- Dano: 1d10 contundente\n- Mãos: 2\n- Propriedades: Contusão, Empurrão\n- Ocultável?: Não\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 3.200","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS MÉDIAS"],"tipo_tabela":"Arma","campos":{"Arma":"Ressonador","Cargas":"12","Dano":"1d10 contundente","Mãos":"2","Propriedades":"Contusão, Empurrão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"3154938c28b54d48ab6349854e3de65e","linhaBlocoId":"114e3d738cbf44de8597bc52f32be98a","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Ressonador","Cargas":"12","Dano":"1d10 contundente","Mãos":"2","Propriedades":"Contusão, Empurrão","Ocultável?":"Não","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"3.200"},"espacos_texto":"2","dado_dano":"1d10","tipo_dano":"fisico","subtipo_dano":"contundente","maos":2,"propriedades":["contusao","empurrao"],"pericia_teste":"balistica","slots_runa_max":2,"alcance":{"tipo":"distancia","eficaz_m":15,"max_m":30,"penalidade_alem_eficaz":-2},"municao_max":12,"municao_compativel":"celula_energia_12"},"ocultavel":"nao"},"id":"item:armas_ressonador","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"89dec68f04374b5f60cfb2bc988009826a0642f96330bc5ed00bc8f1e5e52dae"},{"content_type":"item","slug":"armas_incinerador","payload":{"id":"armas_incinerador","slug":"armas_incinerador","nome":"Incinerador","raridade":"muito_raro","raridade_label":"Muito Raro","preco":5000,"preco_texto":"5.000","preco_qualificador":null,"descricao_curta":"Projetor térmico desenvolvido para limpar barricadas, instalações infestadas e posições defensivas. Em vez de lançar combustível, transforma cada carga em uma massa de energia ígnea que se expande assim que deixa o emissor.","descricao_longa":"*Muito raro*\n\nProjetor térmico desenvolvido para limpar barricadas, instalações infestadas e posições defensivas. Em vez de lançar combustível, transforma cada carga em uma massa de energia ígnea que se expande assim que deixa o emissor.\n\nO disparo ocupa o espaço como uma onda de fogo branco e laranja. Tecidos são carbonizados, materiais inflamáveis entram em combustão e o ar permanece quente após a descarga.\n\n**Mar de fogo:** depois do ataque, escolha uma área de 3 × 3 metros atingida pela dispersão. A área permanece incendiada até o início do seu próximo turno. Uma criatura sofre **1d6 de dano ígneo** ao entrar ou terminar seu turno nela. Cada criatura sofre esse dano no máximo uma vez por rodada.\n\n**Cargas:** 6\n\n**Dano:** 2d6 ígneo\n\n**Mãos:** 2\n\n**Propriedades:** Dispersão, Queimadura\n\n**Alcance:** 15 m eficaz, até 30 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 5.000 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 6\n- Dano: 2d6 ígneo\n- Mãos: 2\n- Propriedades: Dispersão, Queimadura\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 5.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Incinerador","Cargas":"6","Dano":"2d6 ígneo","Mãos":"2","Propriedades":"Dispersão, Queimadura","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"ab7fd8fdb83e45f6ac8e986629086211","linhaBlocoId":"a5966fa4a03442ee8cc1044d13456553","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Incinerador","Cargas":"6","Dano":"2d6 ígneo","Mãos":"2","Propriedades":"Dispersão, Queimadura","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.000"},"espacos_texto":"3","dado_dano":"2d6","tipo_dano":"energetico","subtipo_dano":"igneo","maos":2,"propriedades":["dispersao","queimadura"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":15,"max_m":30,"penalidade_alem_eficaz":-2},"municao_max":6,"municao_compativel":"celula_energia_6"},"ocultavel":"nao"},"id":"item:armas_incinerador","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"c39bc40b0de16c83f84082a9812f7d75e5fc8dd334b220ebfc5be3fba2320ba7"},{"content_type":"item","slug":"armas_rifle_de_feixe_concentrado","payload":{"id":"armas_rifle_de_feixe_concentrado","slug":"armas_rifle_de_feixe_concentrado","nome":"Rifle de feixe concentrado","raridade":"muito_raro","raridade_label":"Muito Raro","preco":6500,"preco_texto":"6.500","preco_qualificador":null,"descricao_curta":"Uma arma longa equipada com múltiplas lentes rúnicas que comprimem a descarga em uma linha extremamente estreita. O feixe atravessa o campo de batalha em uma fração de segundo, deixando um rastro luminoso e uma perfuração cauterizada.","descricao_longa":"*Muito raro*\n\nUma arma longa equipada com múltiplas lentes rúnicas que comprimem a descarga em uma linha extremamente estreita. O feixe atravessa o campo de batalha em uma fração de segundo, deixando um rastro luminoso e uma perfuração cauterizada.\n\nÉ utilizado contra alvos prioritários, operadores protegidos por armaduras e componentes expostos de veículos.\n\n**Tiro estabilizado:** gaste **`1 PA`** e consuma 2 cargas adicionais antes de atacar. O próximo disparo realizado no mesmo turno:\n\n- Causa **+1d8 de dano ígneo.**\n\n- Ignora **2 MIT** ou **4 PD.**\n\n- Não pode ser realizado caso você tenha se deslocado durante o mesmo turno.\n\n**Cargas:** 6\n\n**Dano:** 2d8 ígneo\n\n**Mãos:** 2\n\n**Propriedades:** Perfuração, Precisão\n\n**Alcance:** 300 m eficaz, até 600 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 6.500 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 6\n- Dano: 2d8 ígneo\n- Mãos: 2\n- Propriedades: Perfuração, Precisão\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 6.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Rifle de feixe concentrado","Cargas":"6","Dano":"2d8 ígneo","Mãos":"2","Propriedades":"Perfuração, Precisão","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"6.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"ab7fd8fdb83e45f6ac8e986629086211","linhaBlocoId":"9b62f6b53b3640269fd68e97ea7bf3ab","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Rifle de feixe concentrado","Cargas":"6","Dano":"2d8 ígneo","Mãos":"2","Propriedades":"Perfuração, Precisão","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"6.500"},"espacos_texto":"3","dado_dano":"2d8","tipo_dano":"energetico","subtipo_dano":"igneo","maos":2,"propriedades":["perfuracao","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":300,"max_m":600,"penalidade_alem_eficaz":-2},"municao_max":6,"municao_compativel":"celula_energia_6"},"ocultavel":"nao"},"id":"item:armas_rifle_de_feixe_concentrado","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9ff76f4918a8782cd660d4426974378cb23a8ca120def472dcea50a0c2e0afd9"},{"content_type":"item","slug":"armas_canhao_de_plasma","payload":{"id":"armas_canhao_de_plasma","slug":"armas_canhao_de_plasma","nome":"Canhão de plasma","raridade":"muito_raro","raridade_label":"Muito Raro","preco":6000,"preco_texto":"6.000","preco_qualificador":null,"descricao_curta":"O canhão de plasma confina matéria superaquecida dentro de um campo temporário e a projeta como uma massa luminosa. Ao atingir uma superfície, o campo se rompe e libera calor, expansão e pressão de uma só vez.","descricao_longa":"*Muito raro*\n\nO canhão de plasma confina matéria superaquecida dentro de um campo temporário e a projeta como uma massa luminosa. Ao atingir uma superfície, o campo se rompe e libera calor, expansão e pressão de uma só vez.\n\nDiferente do rifle de feixe, não depende de precisão cirúrgica. É uma arma de impacto bruto, utilizada contra barricadas, criaturas grandes e grupos concentrados.\n\n**Ruptura do campo:** quando o disparo atingir uma criatura, objeto ou superfície, todas as outras criaturas e objetos a até 2 metros do ponto de impacto sofrem **1d6 de dano ígneo**. Criaturas podem reagir com **Desviar** contra o resultado do ataque original para evitar esse dano secundário. O alvo principal não sofre o dano secundário novamente.\n\n**Cargas:** 6\n\n**Dano:** 2d8 ígneo\n\n**Mãos:** 2\n\n**Propriedades:** Empurrão, Queimadura\n\n**Alcance:** 60 m eficaz, até 120 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 6.000 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 6\n- Dano: 2d8 ígneo\n- Mãos: 2\n- Propriedades: Empurrão, Queimadura\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 6.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Canhão de plasma","Cargas":"6","Dano":"2d8 ígneo","Mãos":"2","Propriedades":"Empurrão, Queimadura","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"6.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"ab7fd8fdb83e45f6ac8e986629086211","linhaBlocoId":"5a815dd51caf407ca0e94f2dd2185bdb","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Canhão de plasma","Cargas":"6","Dano":"2d8 ígneo","Mãos":"2","Propriedades":"Empurrão, Queimadura","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"6.000"},"espacos_texto":"3","dado_dano":"2d8","tipo_dano":"energetico","subtipo_dano":"igneo","maos":2,"propriedades":["empurrao","queimadura"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":60,"max_m":120,"penalidade_alem_eficaz":-2},"municao_max":6,"municao_compativel":"celula_energia_6"},"ocultavel":"nao"},"id":"item:armas_canhao_de_plasma","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"58b49dec5d80a0bb3d5fdf9039b3b8f532acd4e326bba9693353571963516390"},{"content_type":"item","slug":"armas_metralhadora_de_arco","payload":{"id":"armas_metralhadora_de_arco","slug":"armas_metralhadora_de_arco","nome":"Metralhadora de arco","raridade":"muito_raro","raridade_label":"Muito Raro","preco":5500,"preco_texto":"5.500","preco_qualificador":null,"descricao_curta":"Uma sequência de condutores rotatórios dispara descargas elétricas em cadência contínua. Cada arco é relativamente pequeno, mas a sucessão transforma o espaço à frente da arma em uma rede de eletricidade instável.","descricao_longa":"*Muito raro*\n\nUma sequência de condutores rotatórios dispara descargas elétricas em cadência contínua. Cada arco é relativamente pequeno, mas a sucessão transforma o espaço à frente da arma em uma rede de eletricidade instável.\n\nÉ utilizada para supressão de corredores, contenção de multidões hostis e combate contra enxames de drones ou criaturas.\n\n**Rede voltaica:** ao utilizar *Rajada (4)*, os disparos podem ser distribuídos entre alvos diferentes. Cada novo alvo deve estar a até 4 metros de uma criatura atingida anteriormente pela mesma rajada. Uma criatura não pode ser escolhida novamente depois de ser atingida durante essa rajada.\n\n**Cargas:** 24\n\n**Dano:** 1d8 elétrico\n\n**Mãos:** 2\n\n**Propriedades:** Rajada (4)\n\n**Alcance:** 80 m eficaz, até 160 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 5.500 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 24\n- Dano: 1d8 elétrico\n- Mãos: 2\n- Propriedades: Rajada (4)\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 5.500","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Metralhadora de arco","Cargas":"24","Dano":"1d8 elétrico","Mãos":"2","Propriedades":"Rajada (4)","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"ab7fd8fdb83e45f6ac8e986629086211","linhaBlocoId":"d723167095564855bbcb56f18ba8ff27","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Metralhadora de arco","Cargas":"24","Dano":"1d8 elétrico","Mãos":"2","Propriedades":"Rajada (4)","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"5.500"},"espacos_texto":"3","dado_dano":"1d8","tipo_dano":"energetico","subtipo_dano":"eletrico","maos":2,"rajada_x":4,"propriedades":["rajada"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":80,"max_m":160,"penalidade_alem_eficaz":-2},"municao_max":24,"municao_compativel":"celula_energia_24"},"ocultavel":"nao"},"id":"item:armas_metralhadora_de_arco","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"23993e8a2daa5ea54dc3dfaa688e2106343841722399cff039880a7cd7518211"},{"content_type":"item","slug":"armas_lanca_crio","payload":{"id":"armas_lanca_crio","slug":"armas_lanca_crio","nome":"Lança-crio","raridade":"muito_raro","raridade_label":"Muito Raro","preco":6000,"preco_texto":"6.000","preco_qualificador":null,"descricao_curta":"O lança-crio projeta um feixe de extração térmica capaz de congelar grandes volumes em poucos segundos. O ponto atingido se cobre de cristais, estruturas metálicas contraem e movimentos corporais tornam-se rígidos.","descricao_longa":"*Muito raro*\n\nO lança-crio projeta um feixe de extração térmica capaz de congelar grandes volumes em poucos segundos. O ponto atingido se cobre de cristais, estruturas metálicas contraem e movimentos corporais tornam-se rígidos.\n\nUnidades imperiais utilizam a arma para conter criaturas grandes, impedir fugas e fragilizar estruturas antes de uma invasão.\n\n**Encapsulamento:** depois de acertar uma criatura, você pode consumir 2 cargas adicionais. O alvo deve reagir com **Resistir**, CD 8. Em falha, fica **`Agarrado`** por uma massa de gelo com **10 PD**.\n\n**Cargas:** 6\n\n**Dano:** 2d6 gélido\n\n**Mãos:** 2\n\n**Propriedades:** Congelamento, Precisão\n\n**Alcance:** 100 m eficaz, até 200 m com –2 de desvantagem\n\nO alvo ou outra criatura pode atacar o gelo normalmente. A massa derrete depois de 3 rodadas ou imediatamente ao sofrer dano ígneo.\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 6.000 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 6\n- Dano: 2d6 gélido\n- Mãos: 2\n- Propriedades: Congelamento, Precisão\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 6.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Lança-crio","Cargas":"6","Dano":"2d6 gélido","Mãos":"2","Propriedades":"Congelamento, Precisão","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"6.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"ab7fd8fdb83e45f6ac8e986629086211","linhaBlocoId":"fd546a7d20854312b45bbedaa1deee09","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Lança-crio","Cargas":"6","Dano":"2d6 gélido","Mãos":"2","Propriedades":"Congelamento, Precisão","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"6.000"},"espacos_texto":"3","dado_dano":"2d6","tipo_dano":"energetico","subtipo_dano":"gelido","maos":2,"propriedades":["congelamento","precisao"],"pericia_teste":"balistica","slots_runa_max":3,"alcance":{"tipo":"distancia","eficaz_m":100,"max_m":200,"penalidade_alem_eficaz":-2},"municao_max":6,"municao_compativel":"celula_energia_6"},"ocultavel":"nao"},"id":"item:armas_lanca_crio","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"f9730679a99eda7a994f6913a6268d52388dd6baad1dbb7dd4ced44f1f00dc07"},{"content_type":"item","slug":"armas_ressonador_de_cerco","payload":{"id":"armas_ressonador_de_cerco","slug":"armas_ressonador_de_cerco","nome":"Ressonador de cerco","raridade":"muito_raro","raridade_label":"Muito Raro","preco":6000,"preco_texto":"6.000","preco_qualificador":null,"descricao_curta":"Versão militar do ressonador, construída ao redor de uma câmara de pressão reforçada. O disparo libera uma onda sonora tão intensa que o impacto pode derrubar pessoas, romper paredes finas, deslocar portas e desestabilizar veículos leves.","descricao_longa":"*Muito raro*\n\nVersão militar do ressonador, construída ao redor de uma câmara de pressão reforçada. O disparo libera uma onda sonora tão intensa que o impacto pode derrubar pessoas, romper paredes finas, deslocar portas e desestabilizar veículos leves.\n\nO ataque causa dano físico contundente e é reduzido normalmente por armaduras físicas.\n\n**Demolição harmônica:** ataques contra objetos, coberturas, veículos e estruturas causam dano dobrado. Quando o ataque destruir uma cobertura, todas as criaturas diretamente atrás dela devem testar **`Reflexos`**, CD 8. Em falha, sofrem **1d8 de dano contundente** pelos destroços e terminam **`Caídas`**.\n\n**Cargas:** 6\n\n**Dano:** 2d8 contundente\n\n**Mãos:** 2\n\n**Propriedades:** Contusão, Empurrão\n\n**Alcance:** 30 m eficaz, até 60 m com –2 de desvantagem\n\n**Ocultável:** não\n\n**Espaços:** 3\n\n**Preço:** 6.000 Ⱥ\n\nDados da lista de mercadorias:\n- Cargas: 6\n- Dano: 2d8 contundente\n- Mãos: 2\n- Propriedades: Contusão, Empurrão\n- Ocultável?: Não\n- Raridade: Muito raro\n- Espaços: 3\n- Preço (Ⱥ): 6.000","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["ARMAS DE ENERGIA","ARMAS PESADAS"],"tipo_tabela":"Arma","campos":{"Arma":"Ressonador de cerco","Cargas":"6","Dano":"2d8 contundente","Mãos":"2","Propriedades":"Contusão, Empurrão","Ocultável?":"Não","Raridade":"Muito raro","Espaços":"3","Preço (Ⱥ)":"6.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"ab7fd8fdb83e45f6ac8e986629086211","linhaBlocoId":"2734a862e1674676987a4ee7202b42f3","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"arma","categoria_label":"Arma","subtipo":"ARMAS DE ENERGIA","estatisticas":{"campos_tabela":{"Arma":"Ressonador de cerco","Cargas":"6","Dano":"2d8 contundente","Mãos":"2","Propriedade