bida em bares, becos e festas, protegendo o tronco de cortes e golpes leves sem chamar atenção.\n\n**Região:** tronco\n\n**Mitigação (MIT):** 3\n\n**Resistência:** físico\n\n**Ocultável:** não\n\n**Espaços:** 2\n\n**Preço:** 100 Ⱥ\n\nDados da lista de mercadorias:\n- Região: Tronco\n- MIT: 3\n- Resistência: Físico\n- Ocultável?: Não\n- Raridade: Muito comum\n- Espaços: 2\n- Preço (Ⱥ): 100","tags":["loja"],"dados_notion":{"pagina":"ARMADURAS E ESCUDOS","secao":["ARMADURAS","ARMADURAS LEVES"],"tipo_tabela":"Armadura","campos":{"Armadura":"Jaqueta de couro reforçada","Região":"Tronco","MIT":"3","Resistência":"Físico","Ocultável?":"Não","Raridade":"Muito comum","Espaços":"2","Preço (Ⱥ)":"100"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355280de9992cec6eca3f6b6","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"d2a5ecc4d6c24abb8d65a14987063b7e","linhaBlocoId":"18c3a4f6f2524656b116eed9078f43af","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"armadura","categoria_label":"Armadura","subtipo":"ARMADURAS LEVES","estatisticas":{"campos_tabela":{"Armadura":"Jaqueta de couro reforçada","Região":"Tronco","MIT":"3","Resistência":"Físico","Ocultável?":"Não","Raridade":"Muito comum","Espaços":"2","Preço (Ⱥ)":"100"},"espacos_texto":"2","regioes":["tronco"],"mit_base":3,"classe_armadura":"leve","tipo_protecao":"fisica"},"ocultavel":"nao"},"id":"item:armaduras_e_escudos_jaqueta_de_couro_reforcada","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"fe35ba68f010c24c158a14aeb0133b83eb580d4e819c6411effd5d862a21302c"},{"content_type":"item","slug":"armaduras_e_escudos_jaqueta_isolante","payload":{"id":"armaduras_e_escudos_jaqueta_isolante","slug":"armaduras_e_escudos_jaqueta_isolante","nome":"Jaqueta isolante","raridade":"incomum","raridade_label":"