ntent_type":"item","slug":"armaduras_e_escudos_capacete_balistico","payload":{"id":"armaduras_e_escudos_capacete_balistico","slug":"armaduras_e_escudos_capacete_balistico","nome":"Capacete balístico","raridade":"comum","raridade_label":"Comum","preco":300,"preco_texto":"300","preco_qualificador":null,"descricao_curta":"Feito de ligas leves reforçadas com fibras de kravita, cobre toda a calota craniana e parte da face. Oferece boa proteção contra impactos diretos e projéteis, mas é impossível de ocultar em contextos urbanos. Seu uso é um sinal explícito de preparação para combate.","descricao_longa":"*Comum*\n\nFeito de ligas leves reforçadas com fibras de kravita, cobre toda a calota craniana e parte da face. Oferece boa proteção contra impactos diretos e projéteis, mas é impossível de ocultar em contextos urbanos. Seu uso é um sinal explícito de preparação para combate.\n\n**Região:** Cabeça\n\n**MIT:** 3\n\n**Resistência:** Físico\n\n**Ocultável:** não\n\n**Espaços:** 1\n\n**Preço:** 300 Ⱥ\n\nDados da lista de mercadorias:\n- Região: Cabeça\n- MIT: 3\n- Resistência: Físico\n- Ocultável?: Não\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 300","tags":["loja"],"dados_notion":{"pagina":"ARMADURAS E ESCUDOS","secao":["ARMADURAS","ARMADURAS MÉDIAS"],"tipo_tabela":"Armadura","campos":{"Armadura":"Capacete balístico","Região":"Cabeça","MIT":"3","Resistência":"Físico","Ocultável?":"Não","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"300"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355280de9992cec6eca3f6b6","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"839f7481d4df4630ae1354d653fe2277","linhaBlocoId":"f64a76cde54a485f9a74a0cb30816d49","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"armadura","categoria_label":"Armadura","subtipo":"ARMADURAS MÉDIAS","estatisticas":{"campos_tabela