os\n- MIT: 3\n- Resistência: Físico\n- Ocultável?: Não\n- Raridade: Incomum\n- Espaços: 2\n- Preço (Ⱥ): 350","tags":["loja"],"dados_notion":{"pagina":"ARMADURAS E ESCUDOS","secao":["ARMADURAS","ARMADURAS MÉDIAS"],"tipo_tabela":"Armadura","campos":{"Armadura":"Ombreiras compostas","Região":"Braços","MIT":"3","Resistência":"Físico","Ocultável?":"Não","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"350"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355280de9992cec6eca3f6b6","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"839f7481d4df4630ae1354d653fe2277","linhaBlocoId":"ca40dfba34de4b4bbc325335286544a2","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"armadura","categoria_label":"Armadura","subtipo":"ARMADURAS MÉDIAS","estatisticas":{"campos_tabela":{"Armadura":"Ombreiras compostas","Região":"Braços","MIT":"3","Resistência":"Físico","Ocultável?":"Não","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"350"},"espacos_texto":"2","regioes":["bracos"],"mit_base":3,"classe_armadura":"media","tipo_protecao":"fisica"},"ocultavel":"nao"},"id":"item:armaduras_e_escudos_ombreiras_compostas","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"45e0c24675fd83cd931c6f3c06ffd52746c24dcac18f5d463e1d5ca02f1fae62"},{"content_type":"item","slug":"armaduras_e_escudos_perneiras_reforcadas","payload":{"id":"armaduras_e_escudos_perneiras_reforcadas","slug":"armaduras_e_escudos_perneiras_reforcadas","nome":"Perneiras reforçadas","raridade":"incomum","raridade_label":"Incomum","preco":400,"preco_texto":"400","preco_qualificador":null,"descricao_curta":"Proteções robustas para coxas e canelas, muito usadas por quem atua em zonas de confronto urbano. Podem ser escondidas sob calças largas, mas deformam a silhueta e produzem ruído ao andar.","descricao_longa":