":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"a7f800f1bb9649ad805408b47cccb04b","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Kit de rastreamento","Efeito":"Detecta resíduos e pistas em superfícies. 5 cargas.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1"}},"id":"item:ferramentas_e_utilidades_kit_de_rastreamento","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"c9edd5866fb1fbbe98d71b2ca125edae627a8322ce86663348541eb790bc51d9"},{"content_type":"item","slug":"ferramentas_e_utilidades_detergente_enzimatico","payload":{"id":"ferramentas_e_utilidades_detergente_enzimatico","slug":"ferramentas_e_utilidades_detergente_enzimatico","nome":"Detergente enzimático","raridade":"incomum","raridade_label":"Incomum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"Dissolve resíduos biológicos. Remove rastros orgânicos. 5 cargas.","descricao_longa":"Incomum\n\nSolução química capaz de dissolver resíduos biológicos (sangue, fluidos, cabelos) sem deixar vestígios detectáveis. Muito usado por criminosos, refratários e equipes de contenção para eliminar provas e rastros genéticos.\n\n- **Efeito:** remove completamente marcas e resíduos orgânicos de superfícies, ferramentas ou roupas. Possui 5 cargas.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 120\n\nDados da lista de mercadorias:\n- Efeito: Dissolve resíduos biológicos. Remove rastros orgânicos. 5 cargas.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Detergente enzimático","Efeito":"Dissolve resíduos biológicos. Remove rastros orgânicos. 5 cargas.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"731c40b2f6a24d61b2d73e7f65c462a3","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Detergente enzimático","Efeito":"Dissolve resíduos biológicos. Remove rastros orgânicos. 5 cargas.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1"}},"id":"item:ferramentas_e_utilidades_detergente_enzimatico","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"924ae41023efe281d4dac5beb1fec3c09668fd4f8fcf4e093b4147647d33f43c"},{"content_type":"item","slug":"ferramentas_e_utilidades_tinta_runica_invisivel","payload":{"id":"ferramentas_e_utilidades_tinta_runica_invisivel","slug":"ferramentas_e_utilidades_tinta_runica_invisivel","nome":"Tinta rúnica invisível","raridade":"incomum","raridade_label":"Incomum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"Só visível com óculos RA/óptica rúnica. Marcações secretas. 5 cargas.","descricao_longa":"*Incomum*\n\nPigmento tecnomágico que só pode ser visualizado por meio de óculos de realidade aumentada ou ópticas rúnicas configuradas para o sinal da tinta. Usada em marcações secretas, sinalização de rotas ou comunicação codificada.\n\n- **Efeito:** inscrições, símbolos ou rastros só podem ser lidos por quem tem equipamento sintonizado. Possui 5 cargas.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 120\n\nDados da lista de mercadorias:\n- Efeito: Só visível com óculos RA/óptica rúnica. Marcações secretas. 5 cargas.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Tinta rúnica invisível","Efeito":"Só visível com óculos RA/óptica rúnica. Marcações secretas. 5 cargas.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"ebaac47706c74cfabf7c34958d128de9","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Tinta rúnica invisível","Efeito":"Só visível com óculos RA/óptica rúnica. Marcações secretas. 5 cargas.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1"}},"id":"item:ferramentas_e_utilidades_tinta_runica_invisivel","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"775c92907e4329fea236405b12f573de5855909968a73a8ca2b21706404c017a"},{"content_type":"item","slug":"ferramentas_e_utilidades_corda_runica","payload":{"id":"ferramentas_e_utilidades_corda_runica","slug":"ferramentas_e_utilidades_corda_runica","nome":"Corda rúnica","raridade":"incomum","raridade_label":"Incomum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"Fibra rúnica, estende até 20 m, fixa e suporta até 500 kg. 1 hora de duração ativa.","descricao_longa":"*Incomum*\n\nFibra de alta resistência com runas de aderência programáveis, ajustando-se ao terreno e ao usuário.\n\n- **Efeito:** estende até 20 m, suporta até 500 kg e se fixa automaticamente em superfícies sólidas. Possui 1 hora de duração ativa. Pode ser recarregada por uma bateria rúnica.\n\n- **PA para uso:** 1\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 120\n\nDados da lista de mercadorias:\n- Efeito: Fibra rúnica, estende até 20 m, fixa e suporta até 500 kg. 1 hora de duração ativa.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Corda rúnica","Efeito":"Fibra rúnica, estende até 20 m, fixa e suporta até 500 kg. 1 hora de duração ativa.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"375569c2145043caa1ff92fd5c98ec15","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Corda rúnica","Efeito":"Fibra rúnica, estende até 20 m, fixa e suporta até 500 kg. 1 hora de duração ativa.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1"}},"id":"item:ferramentas_e_utilidades_corda_runica","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"00d8e11624019bcbdd5e484f12a23fc12280e3e2302ff5ad37bbea05808927b8"},{"content_type":"item","slug":"ferramentas_e_utilidades_kit_de_tirolesa","payload":{"id":"ferramentas_e_utilidades_kit_de_tirolesa","slug":"ferramentas_e_utilidades_kit_de_tirolesa","nome":"Kit de Tirolesa","raridade":"comum","raridade_label":"Comum","preco":200,"preco_texto":"200","preco_qualificador":null,"descricao_curta":"Instala uma tirolesa de até 30 m entre dois pontos de fixação, permitindo atravessar vãos e desníveis.","descricao_longa":"*Comum*\n\nO Kit de Tirolesa reúne 30 m de cabo leve de alta resistência, pontos de fixação, um sistema de tensionamento e uma roldana de travessia com linha de retorno. Quando instalado entre duas estruturas, cria uma rota temporária para atravessar vãos e desníveis.\n\n**Instalar:** fixar uma extremidade do cabo em um ponto firme exige **Interagir** **`1 PA`**. Depois que as duas extremidades estiverem presas, o cabo é tensionado e fica pronto para uso. A trajetória entre os pontos precisa estar livre, e o destino deve estar abaixo da origem.\n\n**Deslizar:** ao usar **Deslocar-se** preso à tirolesa, você percorre o cabo até a outra extremidade, em uma distância máxima de 30 m.\n\nDepois da travessia, a roldana pode ser puxada de volta até a origem pela linha de retorno, permitindo que outras criaturas utilizem a mesma rota.\n\nO Kit de Tirolesa não permite ganhar altitude e depende de dois pontos de fixação adequados.\n\n**Espaços:** 2\n\n**Preço:** 200 Ⱥ\n\nDados da lista de mercadorias:\n- Efeito: Instala uma tirolesa de até 30 m entre dois pontos de fixação, permitindo atravessar vãos e desníveis.\n- Raridade: Comum\n- Espaços: 2\n- Preço (Ⱥ): 200","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Kit de Tirolesa","Efeito":"Instala uma tirolesa de até 30 m entre dois pontos de fixação, permitindo atravessar vãos e desníveis.","Raridade":"Comum","Espaços":"2","Preço (Ⱥ)":"200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"403abea710574282953f9ef7e962c408","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Kit de Tirolesa","Efeito":"Instala uma tirolesa de até 30 m entre dois pontos de fixação, permitindo atravessar vãos e desníveis.","Raridade":"Comum","Espaços":"2","Preço (Ⱥ)":"200"},"espacos_texto":"2"}},"id":"item:ferramentas_e_utilidades_kit_de_tirolesa","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"484587a67c479aae167b3bb608b1457bbd8ae8b8f9266b681ea7c95550502539"},{"content_type":"item","slug":"ferramentas_e_utilidades_ascensor_motorizado","payload":{"id":"ferramentas_e_utilidades_ascensor_motorizado","slug":"ferramentas_e_utilidades_ascensor_motorizado","nome":"Ascensor Motorizado","raridade":"comum","raridade_label":"Comum","preco":250,"preco_texto":"250","preco_qualificador":null,"descricao_curta":"Permite subir ou descer até 12 m por ação de Deslocar-se ao longo de uma corda ou cabo ancorado.","descricao_longa":"*Comum*\n\nO Ascensor Motorizado é um dispositivo preso ao cinto ou a um arnês, equipado com roldanas motorizadas que se fecham ao redor de uma corda ou cabo. Depois de acoplado, o sistema traciona o usuário para cima ou controla sua descida, deixando as mãos livres durante o percurso.\n\n**Deslocamento por cabo:** enquanto estiver conectado a uma corda ou cabo firmemente ancorado, ao usar **Deslocar-se ****`1 PA`**, você pode subir ou descer até 12 m ao longo dele.\n\nAcoplar ou desacoplar o Ascensor Motorizado pode ser feito como parte desse deslocamento, sem custo adicional.\n\nO Ascensor Motorizado não instala nem ancora a corda ou o cabo utilizado. Se a linha deixar de estar presa, romper ou não alcançar o destino, o equipamento não impede a queda.\n\n**Espaços:** 1\n\n**Preço:** 250 Ⱥ\n\nDados da lista de mercadorias:\n- Efeito: Permite subir ou descer até 12 m por ação de Deslocar-se ao longo de uma corda ou cabo ancorado.\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 250","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Ascensor Motorizado","Efeito":"Permite subir ou descer até 12 m por ação de Deslocar-se ao longo de uma corda ou cabo ancorado.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"250"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"d500cf3de9294bf090293d2c99134f7f","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Ascensor Motorizado","Efeito":"Permite subir ou descer até 12 m por ação de Deslocar-se ao longo de uma corda ou cabo ancorado.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"250"},"espacos_texto":"1"}},"id":"item:ferramentas_e_utilidades_ascensor_motorizado","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"05d6b0c947d8fad31380c630da0c88bbad67c416a59f2d149198b355ad55fa53"},{"content_type":"item","slug":"ferramentas_e_utilidades_solas_antiderrapantes","payload":{"id":"ferramentas_e_utilidades_solas_antiderrapantes","slug":"ferramentas_e_utilidades_solas_antiderrapantes","nome":"Solas Antiderrapantes","raridade":"comum","raridade_label":"Comum","preco":150,"preco_texto":"150","preco_qualificador":null,"descricao_curta":"Ignora o custo adicional de deslocamento por superfícies escorregadias e concede +1 de vantagem em testes de Mobilidade para não escorregar.","descricao_longa":"*Comum*\n\nAs Solas Antiderrapantes são encaixes reforçados para calçados, cobertos por microcravos e superfícies aderentes que se ajustam ao terreno durante a passada. São usadas em áreas industriais, terrenos instáveis e ambientes onde perder o apoio pode ser mais perigoso do que avançar devagar.\n\n**Aderência:** terreno difícil causado exclusivamente por superfícies escorregadias ou com pouca aderência não aumenta a distância gasta pelo seu deslocamento.\n\nIsso inclui superfícies como gelo, piso molhado, óleo, lama superficial ou cascalho solto. O efeito não se aplica a obstáculos, escombros, vegetação densa ou outras condições em que a dificuldade não seja causada pela falta de aderência.\n\nQuando um teste de **`Mobilidade`** for exigido especificamente para manter o equilíbrio ou evitar escorregar por causa da superfície, você recebe **+1 de vantagem**.\n\n**Espaços:** 1\n\n**Preço:** 150 Ⱥ\n\nDados da lista de mercadorias:\n- Efeito: Ignora o custo adicional de deslocamento por superfícies escorregadias e concede +1 de vantagem em testes de Mobilidade para não escorregar.\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 150","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Solas Antiderrapantes","Efeito":"Ignora o custo adicional de deslocamento por superfícies escorregadias e concede +1 de vantagem em testes de Mobilidade para não escorregar.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"150"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"9089d8148824412f861d3140f13c4b64","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Solas Antiderrapantes","Efeito":"Ignora o custo adicional de deslocamento por superfícies escorregadias e concede +1 de vantagem em testes de Mobilidade para não escorregar.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"150"},"espacos_texto":"1"}},"id":"item:ferramentas_e_utilidades_solas_antiderrapantes","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"bd5ce62f0f4332d54b32dfc231e1dc31ac905563cc4f160ae73b21561d3be38b"},{"content_type":"item","slug":"aljava","payload":{"id":"aljava","slug":"aljava","nome":"Aljava","raridade":"comum","raridade_label":"Comum","preco":70,"preco_texto":"70","preco_qualificador":null,"descricao_curta":"Armazena até 20 flechas ou 10 virotes, permitindo combinar os dois tipos.","descricao_longa":"*Comum*\n\nSuporte de cintura ou costas com divisórias ajustáveis, projetado para transportar diferentes tipos de flechas e virotes.\n\n**Capacidade:** comporta até 20 flechas ou 10 virotes, podendo misturar os dois tipos. Cada virote equivale a 2 flechas para determinar a capacidade.\n\n**Suporte de Munição:** enquanto equipada, ocupa a posição de Suporte de Munição, sem utilizar Acesso Rápido. Suas munições não ocupam posições adicionais nem espaços da Mochila.\n\n**Seleção de munição:** permite escolher qualquer flecha ou virote armazenado ao realizar **Recarregar** **`1 PA`**.\n\n**Espaços:** 1 (vazia). Quando guardada na Mochila, suas munições também ocupam os espaços normais de armazenamento.\n\n**Preço:** 70 Ⱥ\n\nDados da lista de mercadorias:\n- Efeito: Armazena até 20 flechas ou 10 virotes, permitindo combinar os dois tipos.\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 70","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Aljava","Efeito":"Armazena até 20 flechas ou 10 virotes, permitindo combinar os dois tipos.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"70"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"e98754979f7b4d988e770ffd353397ea","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-11","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Aljava","Efeito":"Armazena até 20 flechas ou 10 virotes, permitindo combinar os dois tipos.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"70"},"espacos_texto":"1","suporte_municao":{"tipo":"aljava","capacidade":20,"autoalimentadora":false}}},"id":"item:aljava","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"ad930a95709a2b99ef3d61b7d013f676a85ee3382d2e7ada169d4e4a6eb4f622"},{"content_type":"item","slug":"ferramentas_aljava_autoalimentadora","payload":{"id":"ferramentas_aljava_autoalimentadora","slug":"ferramentas_aljava_autoalimentadora","nome":"Aljava Autoalimentadora","raridade":"incomum","raridade_label":"Incomum","preco":400,"preco_texto":"400","preco_qualificador":null,"descricao_curta":"Armazena até 20 flechas e permite recarregar um arco como parte da ação Atacar.","descricao_longa":"*Incomum*\n\nAljava rígida equipada com um mecanismo de alimentação por molas e trilhos internos. Conforme uma flecha é retirada, a próxima avança automaticamente até a abertura, permanecendo posicionada para um saque imediato. O sistema reduz os movimentos necessários para preparar cada disparo e permite alternar entre diferentes tipos de flechas.\n\n**Capacidade:** comporta até 20 flechas de qualquer tipo. Não comporta virotes.\n\n**Suporte de Munição:** enquanto equipada, ocupa a posição de Suporte de Munição, sem utilizar Acesso Rápido. Suas flechas não ocupam posições adicionais nem espaços da Mochila.\n\n**Alimentação automática:** ao realizar **Atacar** com um arco, você pode recarregá-lo como parte da mesma ação, sem gastar PA adicionais. Você pode escolher qualquer flecha disponível na aljava para o disparo.\n\nO mecanismo não reduz o custo de Atacar nem os custos adicionais de habilidades especiais.\n\n**Espaços:** 1 (vazia). Quando guardada na Mochila, suas flechas também ocupam os espaços normais de armazenamento.\n\n**Preço:** 400 Ⱥ\n\nDados da lista de mercadorias:\n- Efeito: Armazena até 20 flechas e permite recarregar um arco como parte da ação Atacar.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 400","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Aljava Autoalimentadora","Efeito":"Armazena até 20 flechas e permite recarregar um arco como parte da ação Atacar.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"400"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"38f4452084e94d658827f3da2b0ff665","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-11","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Aljava Autoalimentadora","Efeito":"Armazena até 20 flechas e permite recarregar um arco como parte da ação Atacar.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"400"},"espacos_texto":"1","suporte_municao":{"tipo":"aljava","capacidade":20,"autoalimentadora":true}}},"id":"item:ferramentas_aljava_autoalimentadora","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9ed0962700793ab3d838930e043a0cd3cd8c655409e4d0a0a400472918923a3e"},{"content_type":"item","slug":"ferramentas_cartucheira","payload":{"id":"ferramentas_cartucheira","slug":"ferramentas_cartucheira","nome":"Cartucheira","raridade":"comum","raridade_label":"Comum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"Armazena até 40 unidades de capacidade em munições de diferentes calibres.","descricao_longa":"*Comum*\n\nSuporte modular de cintura ou torso com compartimentos ajustáveis para armazenar munições de diferentes calibres. Permite selecionar os cartuchos necessários durante um confronto.\n\n**Capacidade:** até 40 unidades de capacidade, distribuídas entre diferentes tipos de munição. Cada projétil de pistola ou fuzil consome 1 unidade de capacidade; cada projétil de escopeta ou precisão consome 2 unidades. Os tipos podem ser misturados livremente, respeitando o limite total.\n\n**Suporte de Munição:** enquanto equipada, ocupa a posição de Suporte de Munição, sem utilizar Acesso Rápido. A munição armazenada não ocupa posições adicionais nem espaços da Mochila.\n\n**Seleção de munição:** permite utilizar qualquer munição compatível armazenada ao realizar **Recarregar** **`1 PA`**.\n\n**Espaços:** 1 (vazia). Quando guardada na Mochila, suas munições também ocupam os espaços normais de armazenamento.\n\n**Preço:** 120 Ⱥ\n\nDados da lista de mercadorias:\n- Efeito: Armazena até 40 unidades de capacidade em munições de diferentes calibres.\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"FERRAMENTAS","secao":[],"tipo_tabela":"Item","campos":{"Item":"Cartucheira","Efeito":"Armazena até 40 unidades de capacidade em munições de diferentes calibres.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"4210a13635528285a61281d46315a915","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"61d5a3c4b51b45f697f24ae90fb32558","linhaBlocoId":"ca89a6116ef24e828478b5d0f0637d3a","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-11","updated_at":"2026-10-11","categoria":"ferramenta","categoria_label":"Ferramenta","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Cartucheira","Efeito":"Armazena até 40 unidades de capacidade em munições de diferentes calibres.","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1","suporte_municao":{"tipo":"cartucheira","capacidade":40,"autoalimentadora":false}}},"id":"item:ferramentas_cartucheira","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9f7b71016c00d9a5ee5ad0a6b5344693d43df4e4048390f07a21fde4c5eaf6b1"},{"content_type":"item","slug":"mobilidade_aerovoile","payload":{"id":"mobilidade_aerovoile","slug":"mobilidade_aerovoile","nome":"Aérovoile","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"*Estrutura dorsal · Incomum*","descricao_longa":"*Estrutura dorsal · Incomum*\n\nO Aérovoile é um planador retrátil montado sobre uma estrutura dorsal. Duas superfícies aerodinâmicas articuladas se abrem para os lados do usuário e tensionam uma membrana leve, aproveitando o fluxo de ar para converter perda de altitude em deslocamento horizontal.\n\nQuando recolhido, o conjunto permanece dobrado junto às costas. O Aérovoile não possui propulsão própria: precisa de altura para funcionar e não é capaz de ganhar altitude ou manter o usuário suspenso.\n\n**Planar:** enquanto estiver no ar com o Aerovoile aberto, ao usar **Deslocar-se** **`1 PA`**, você pode planar. Mova-se até 18 m pelo ar. Para cada 3 m percorridos, você perde 1 m de altitude.\n\nVocê não pode ganhar altitude enquanto plana. Se alcançar uma superfície capaz de sustentá-lo durante o deslocamento, pode aterrissar nela.\n\nAo usar Planar com o equipamento recolhido, você pode abrir o Aerovoile como parte da mesma ação. Recolhê-lo exige **Interagir** **`1 PA`** durante cenas organizadas em rodadas.\n\nSe terminar seu turno no ar após planar, permanece em voo. Caso termine um turno no ar sem planar, começa a cair.\n\nQuando a trajetória exigir atravessar espaços apertados, desviar de obstáculos, realizar mudanças bruscas de direção ou pousar sobre uma superfície pequena ou difícil, use as regras de **Manobrar**, mantendo o deslocamento do Aerovoile.\n\n**Abrir Aérovoile** **`Reação`**: quando começar a cair, se houver pelo menos 3 m livres antes da superfície abaixo de você e espaço suficiente para abrir o equipamento, você pode abrir o Aérovoile e começar a planar. A queda é interrompida.\n\n**Espaços:** 2\n\n**Preço:** 1.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Estrutura dorsal\n- Raridade: Incomum\n- Espaços: 2\n- Preço (Ⱥ): 1.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Aérovoile","Tipo":"Estrutura dorsal","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"1.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"461ff5336e4e48c8a4cff1722b2b61f1","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Aérovoile","Tipo":"Estrutura dorsal","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"1.000"},"espacos_texto":"2"}},"id":"item:mobilidade_aerovoile","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"58539b473a952e471423ca07a50ce76fbd447680774aba09e3c95f1af148a5c2"},{"content_type":"item","slug":"mobilidade_bicicleta","payload":{"id":"mobilidade_bicicleta","slug":"mobilidade_bicicleta","nome":"Bicicleta","raridade":"comum","raridade_label":"Comum","preco":300,"preco_texto":"300","preco_qualificador":null,"descricao_curta":"*Locomoção · Comum*","descricao_longa":"*Locomoção · Comum*\n\nA bicicleta é um equipamento leve de duas rodas, comum em bairros residenciais, zonas comerciais e trajetos cotidianos. É eficiente, silenciosa e barata de manter, mas depende de espaço para circular e perde eficiência fora de vias adequadas.\n\n**Pedalar:** enquanto estiver sobre a bicicleta em uma superfície firme e contínua, ao usar **Deslocar-se** **`1 PA`**, você pode percorrer até 25 m. Você pode subir ou descer da bicicleta como parte desse deslocamento, sem custo adicional.\n\n**Acelerar:** enquanto estiver sobre a bicicleta em uma superfície firme e contínua, ao usar **Deslocar-se** **`1 PA`**, você pode pedalar intensamente para percorrer até 50 m. O narrador pode exigir um teste de **`Mobilidade`** nas mesmas condições de **Correr**. Em caso de falha, você percorre no máximo 20 m, e o narrador pode aplicar outra consequência apropriada, como ficar **`Caído`**.\n\nA bicicleta não funciona adequadamente em escadas, terreno acidentado, corredores muito estreitos, entulho denso ou superfícies onde não haja espaço para manter o equilíbrio. Quando a trajetória exigir curvas fechadas, desvio de obstáculos ou controle preciso, use as regras de **Manobrar**, mantendo o deslocamento da bicicleta.\n\n**Perda de equilíbrio:** se você ficar **`Caído`** enquanto utiliza a bicicleta, você cai e deixa de utilizá-la. A bicicleta para no espaço onde isso ocorreu ou no espaço válido mais próximo.\n\nA bicicleta não cabe em uma mochila comum. Para transportá-la sem utilizá-la, você pode empurrá-la, prendê-la a outro veículo ou acomodá-la em uma área de carga apropriada.\n\n**Espaços:** Carga\n\n**Preço:** 300 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Locomoção\n- Raridade: Comum\n- Espaços: Carga\n- Preço (Ⱥ): 300","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Bicicleta","Tipo":"Locomoção","Raridade":"Comum","Espaços":"Carga","Preço (Ⱥ)":"300"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"c8dfb32484d74a0eb326eff5531f2c36","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Bicicleta","Tipo":"Locomoção","Raridade":"Comum","Espaços":"Carga","Preço (Ⱥ)":"300"},"espacos_texto":"Carga"}},"id":"item:mobilidade_bicicleta","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"a8881285f5260ae3ef573f6069216ba3c4e744800e93fb7ac17590d367e879a5"},{"content_type":"item","slug":"mobilidade_cabestan_i","payload":{"id":"mobilidade_cabestan_i","slug":"mobilidade_cabestan_i","nome":"Cabestan I","raridade":"incomum","raridade_label":"Incomum","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"*Estrutura dorsal · Incomum*","descricao_longa":"*Estrutura dorsal · Incomum*\n\nO Cabestan I é o modelo básico da linha Cabestan, formado por uma estrutura dorsal rígida presa ao tronco e à cintura, um lançador de âncora e um guincho retrátil. Quando a âncora se fixa a um ponto de ancoragem firme, o guincho recolhe o cabo e projeta o corpo em direção a ele.\n\nCom um único cabo ativo, o modelo realiza trajetórias diretas e não consegue redirecioná-las depois que a Tração começa.\n\n**Tração:** ao realizar **Deslocar-se** **`1 PA`**, escolha um ponto de ancoragem firme e visível dentro de uma distância igual ao seu deslocamento de Andar + 2 m. Dispare uma âncora contra ela e desloque-se em sua direção.\n\nDurante a Tração:\n\n- Você não precisa de uma superfície sob os pés.\n\n- Pode subir, descer e atravessar vãos.\n\n- Cada trecho do deslocamento deve aproximá-lo do ponto de ancoragem utilizado naquele momento.\n\n- Você pode dividir o deslocamento entre outras ações normalmente.\n\n- O trajeto precisa permanecer desimpedido para seu corpo e para o cabo.\n\n- A distância total percorrida não pode ultrapassar o alcance de Tração do equipamento.\n\n- Você deve terminar o deslocamento sobre uma superfície estável. Caso contrário, começa a cair.\n\nDisparar ou recolher a âncora utilizada durante a Tração não exige uma ação adicional. O Cabestan I utiliza apenas uma âncora por Tração e não pode redirecioná-la depois que o deslocamento é iniciado.\n\n**Espaços:** 2\n\n**Preço:** 1.500 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Estrutura dorsal\n- Raridade: Incomum\n- Espaços: 2\n- Preço (Ⱥ): 1.500","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Cabestan I","Tipo":"Estrutura dorsal","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"1.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"8d0c06c2c1064dccb73d05fe89ce837d","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Cabestan I","Tipo":"Estrutura dorsal","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"1.500"},"espacos_texto":"2"}},"id":"item:mobilidade_cabestan_i","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"e868fab7ee5752820ef7b4123a544a73c2f2a1d707ce5095a349ce005249f688"},{"content_type":"item","slug":"mobilidade_cabestan_ii","payload":{"id":"mobilidade_cabestan_ii","slug":"mobilidade_cabestan_ii","nome":"Cabestan II","raridade":"raro","raridade_label":"Raro","preco":3000,"preco_texto":"3.000","preco_qualificador":null,"descricao_curta":"*Estrutura dorsal · Raro*","descricao_longa":"*Estrutura dorsal · Raro*\n\nO Cabestan II é o modelo duplo da linha Cabestan. Um segundo lançador ocupa o lado oposto da estrutura dorsal, enquanto os guinchos são distribuídos entre a cintura e as costas para dividir a tensão entre os dois cabos.\n\nEnquanto uma âncora permanece sob carga, o segundo lançador pode fixar um novo ponto e transferir a tração para ele, permitindo uma mudança de direção durante o deslocamento.\n\n**Tração:** ao realizar **Deslocar-se** **`1 PA`**, escolha um ponto de ancoragem firme e visível dentro de uma distância igual ao seu deslocamento de Andar + 4 m. Dispare uma âncora contra ela e desloque-se em sua direção.\n\nDurante a Tração:\n\n- Você não precisa de uma superfície sob os pés.\n\n- Pode subir, descer e atravessar vãos.\n\n- Cada trecho do deslocamento deve aproximá-lo do ponto de ancoragem utilizado naquele momento.\n\n- Você pode dividir o deslocamento entre outras ações normalmente.\n\n- O trajeto precisa permanecer desimpedido para seu corpo e para o cabo.\n\n- A distância total percorrida não pode ultrapassar o alcance de Tração do equipamento.\n\n- Você deve terminar o deslocamento sobre uma superfície estável. Caso contrário, começa a cair.\n\nDisparar ou recolher as âncoras utilizadas durante a Tração não exige uma ação adicional.\n\n**Redirecionamento:** uma vez durante cada Tração, você pode disparar uma nova âncora e passar a se deslocar em direção a ela. O Cabestan II utiliza até duas âncoras por Tração, e a distância percorrida antes e depois do redirecionamento faz parte do mesmo limite de Tração.\n\n**Espaços:** 3\n\n**Preço:** 3.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Estrutura dorsal\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 3.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Cabestan II","Tipo":"Estrutura dorsal","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"3.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"7025802c5e764b99b84b0d1db8952f55","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Cabestan II","Tipo":"Estrutura dorsal","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"3.000"},"espacos_texto":"3"}},"id":"item:mobilidade_cabestan_ii","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"63547288e3232c9ead13ee604b9b13807634dc8b734df9c1f4febc5c74b13dac"},{"content_type":"item","slug":"mobilidade_hoverboard","payload":{"id":"mobilidade_hoverboard","slug":"mobilidade_hoverboard","nome":"Hoverboard","raridade":"incomum","raridade_label":"Incomum","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"*Locomoção · Incomum*","descricao_longa":"*Locomoção · Incomum*\n\nO Hoverboard é uma prancha individual equipada com repulsores na base. Quando ativados, eles mantêm a prancha cerca de 20 cm acima da superfície e fornecem a propulsão necessária para movê-la, enquanto estabilizadores internos compensam irregularidades e mudanças de inclinação.\n\nO campo de repulsão funciona sobre superfícies sólidas ou líquidas, desde que haja uma superfície contínua abaixo da prancha.\n\n**Deslizar:** enquanto estiver sobre o Hoverboard, ao usar **Deslocar-se** **`1 PA`**, você pode deslizar até 20 m. Você pode subir ou descer da prancha como parte desse deslocamento, sem custo adicional.\n\n**Acelerar:** enquanto estiver sobre o Hoverboard em uma superfície sólida, contínua e relativamente regular, ao usar **Deslocar-se** **`1 PA`**, você pode aumentar a propulsão para percorrer até 30 m. Ao Acelerar, você não pode ignorar terreno difícil nem atravessar superfícies líquidas. O narrador pode exigir um teste de **`Mobilidade`** nas mesmas condições de **Correr**. Em caso de falha, você percorre no máximo 20 m, e o narrador pode aplicar outra consequência apropriada, como ficar **`Caído`**.\n\nAo deslizar, você ignora terreno difícil causado exclusivamente pelas condições da superfície, como entulho, lama, areia, neve ou irregularidades do solo. A prancha também pode atravessar superfícies líquidas, como rios, canais, lagos, esgoto ou reservatórios. Isso não oferece proteção contra outros riscos ambientais presentes no local, como calor, gases ou vapores.\n\nO Hoverboard precisa permanecer próximo de uma superfície contínua capaz de manter seu campo de repulsão. Ele não permite ganhar altitude, percorrer paredes, planar ou atravessar vãos sem uma superfície abaixo.\n\nQuando a trajetória exigir curvas bruscas, passagens estreitas, desvio de obstáculos ou outras manobras complexas, use as regras de **Manobrar**, mantendo o deslocamento do Hoverboard.\n\n**Perda de equilíbrio:** se você ficar **`Caído`** enquanto estiver utilizando o Hoverboard, você cai e deixa de utilizá-lo. O Hoverboard para no espaço onde isso ocorreu ou, caso esse espaço não possa sustentá-lo, no espaço válido mais próximo.\n\n**Energia:** o Hoverboard possui 3 cargas. Ao ativá-lo, 1 carga é consumida e mantém o equipamento funcionando por 1 hora. Enquanto você continuar utilizando o Hoverboard, uma nova carga é consumida automaticamente sempre que a duração da carga anterior terminar. Você pode desligá-lo a qualquer momento.\n\n**Recarga:** durante um Descanso Longo, o Hoverboard recupera todas as suas cargas. Ele também é compatível com Baterias Rúnicas; cada carga gasta de uma Bateria Rúnica restaura 1 carga do Hoverboard.\n\n**Espaços:** 3\n\n**Preço:** 1.500 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Locomoção\n- Raridade: Incomum\n- Espaços: 3\n- Preço (Ⱥ): 1.500","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Hoverboard","Tipo":"Locomoção","Raridade":"Incomum","Espaços":"3","Preço (Ⱥ)":"1.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"dd9ab57bc5a44bec9444cb4d3a8b053a","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Hoverboard","Tipo":"Locomoção","Raridade":"Incomum","Espaços":"3","Preço (Ⱥ)":"1.500"},"espacos_texto":"3"}},"id":"item:mobilidade_hoverboard","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"32a0a4b484ee2b8129d76a75e6fb260ed9afc8f293c6bc70231f666b27636d1d"},{"content_type":"item","slug":"mobilidade_icarus_i","payload":{"id":"mobilidade_icarus_i","slug":"mobilidade_icarus_i","nome":"Icarus I","raridade":"raro","raridade_label":"Raro","preco":2000,"preco_texto":"2.000","preco_qualificador":null,"descricao_curta":"*Estrutura dorsal · Raro*","descricao_longa":"*Estrutura dorsal · Raro*\n\nO Icarus I é um conjunto de asas propulsoras montado sobre uma estrutura dorsal rígida. Duas estruturas articuladas se abrem para os lados do usuário e distribuem pequenos propulsores ao longo de sua extensão, enquanto estabilizadores próximos ao torso corrigem inclinação e direção durante o voo.\n\nO sistema produz sustentação suficiente para retirar uma pessoa do chão, movimentá-la livremente pelo ar e mantê-la suspensa por curtos períodos.\n\n**Propulsão aérea:** o Icarus I possui 3 cargas. Ao usar **Deslocar-se** **`1 PA`** com o equipamento desligado, você pode ativá-lo como parte da mesma ação, consumindo 1 carga. Enquanto a propulsão estiver ativa, você possui 15 m de deslocamento de voo e pode permanecer suspenso no ar.\n\nCada carga mantém a propulsão ativa por 1 rodada. Enquanto você continuar utilizando o Icarus I, uma nova carga é consumida automaticamente sempre que a duração da carga anterior terminar. Você pode desligar a propulsão a qualquer momento sem gastar uma ação.\n\nSe a duração de uma carga terminar e não houver outra disponível, a propulsão se encerra e você começa a cair.\n\n**Recarga:** durante um Descanso Longo, o Icarus I recupera todas as suas cargas. Ele também é compatível com Baterias Rúnicas; cada carga gasta de uma Bateria Rúnica restaura 1 carga do Icarus I. Por ser compatível, também pode ter suas cargas restauradas pela magia Carga.\n\n**Espaços:** 3\n\n**Preço:** 2.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Estrutura dorsal\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 2.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Icarus I","Tipo":"Estrutura dorsal","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"2.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"80cdf32fe55446b2bd0ec372485c10e3","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Icarus I","Tipo":"Estrutura dorsal","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"2.000"},"espacos_texto":"3"}},"id":"item:mobilidade_icarus_i","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"dafd05fe1802c723692f72d7f9a1ab48db01d1d9bfdbf173fad8cbc0ccc4eac0"},{"content_type":"item","slug":"mobilidade_icarus_ii","payload":{"id":"mobilidade_icarus_ii","slug":"mobilidade_icarus_ii","nome":"Icarus II","raridade":"raro","raridade_label":"Raro","preco":4000,"preco_texto":"4.000","preco_qualificador":null,"descricao_curta":"*Estrutura dorsal · Raro*","descricao_longa":"*Estrutura dorsal · Raro*\n\nO Icarus II é um conjunto de asas propulsoras construído sobre uma estrutura dorsal reforçada, com superfícies articuladas largas e propulsores distribuídos entre as articulações e extremidades. Um sistema interno de estabilização redistribui continuamente o empuxo entre os dois lados do conjunto, permitindo sustentar peso adicional sem perder o controle de direção.\n\nA estrutura possui pontos de apoio e travas próprias para prender uma segunda pessoa ao usuário durante o voo, embora a carga adicional reduza a velocidade do conjunto.\n\n**Propulsão aérea:** o Icarus II possui 3 cargas. Ao usar **Deslocar-se** **`1 PA`** com o equipamento desligado, você pode ativá-lo como parte da mesma ação, consumindo 1 carga. Enquanto a propulsão estiver ativa, você possui 20 m de deslocamento de voo e pode permanecer suspenso no ar.\n\nCada carga mantém a propulsão ativa por 1 minuto. Enquanto você continuar utilizando o Icarus II, uma nova carga é consumida automaticamente sempre que a duração da carga anterior terminar. Você pode desligar a propulsão a qualquer momento sem gastar uma ação.\n\nVocê pode transportar uma criatura de porte igual ou menor que o seu. Enquanto fizer isso, seu deslocamento de voo é reduzido à metade.\n\nSe a duração de uma carga terminar e não houver outra disponível, a propulsão se encerra e você começa a cair.\n\n**Recarga:** durante um Descanso Longo, o Icarus II recupera todas as suas cargas. Ele também é compatível com Baterias Rúnicas; cada carga gasta de uma Bateria Rúnica restaura 1 carga do Icarus II. Por ser compatível, também pode ter suas cargas restauradas pela magia Carga.\n\n**Espaços:** 3\n\n**Preço:** 4.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Estrutura dorsal\n- Raridade: Raro\n- Espaços: 3\n- Preço (Ⱥ): 4.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Icarus II","Tipo":"Estrutura dorsal","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"4.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"267822f7974e4fa192bf7c46ede140ce","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Icarus II","Tipo":"Estrutura dorsal","Raridade":"Raro","Espaços":"3","Preço (Ⱥ)":"4.000"},"espacos_texto":"3"}},"id":"item:mobilidade_icarus_ii","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b76e572eedb41fd8444ece933e63b69313e58b1fb3251ed6c0d1f9414cb8882d"},{"content_type":"item","slug":"mobilidade_icarus_iii","payload":{"id":"mobilidade_icarus_iii","slug":"mobilidade_icarus_iii","nome":"Icarus III","raridade":"muito_raro","raridade_label":"Muito Raro","preco":8000,"preco_texto":"8.000","preco_qualificador":null,"descricao_curta":"*Estrutura dorsal · Muito Raro*","descricao_longa":"*Estrutura dorsal · Muito Raro*\n\nO Icarus III é um conjunto de asas propulsoras de alta capacidade formado por uma estrutura dorsal reforçada, superfícies articuladas extensas e múltiplos propulsores independentes distribuídos por toda a estrutura. Módulos de estabilização e sustentação ajustam continuamente o empuxo para compensar mudanças de direção e de peso durante o voo.\n\nO sistema é capaz de permanecer ativo por longos períodos e possui estrutura suficiente para sustentar uma segunda pessoa sem comprometer a velocidade ou a estabilidade do conjunto.\n\n**Propulsão aérea:** o Icarus III possui 3 cargas. Ao usar **Deslocar-se** **`1 PA`** com o equipamento desligado, você pode ativá-lo como parte da mesma ação, consumindo 1 carga. Enquanto a propulsão estiver ativa, você possui 25 m de deslocamento de voo e pode permanecer suspenso no ar.\n\nCada carga mantém a propulsão ativa por 1 hora. Enquanto você continuar utilizando o Icarus III, uma nova carga é consumida automaticamente sempre que a duração da carga anterior terminar. Você pode desligar a propulsão a qualquer momento sem gastar uma ação.\n\nVocê pode transportar uma criatura de porte igual ou menor que o seu sem reduzir seu deslocamento de voo.\n\nSe a duração de uma carga terminar e não houver outra disponível, a propulsão se encerra e você começa a cair.\n\n**Recarga:** durante um Descanso Longo, o Icarus III recupera todas as suas cargas. Ele também é compatível com Baterias Rúnicas; cada carga gasta de uma Bateria Rúnica restaura 1 carga do Icarus III. Por ser compatível, também pode ter suas cargas restauradas pela magia Carga.\n\n**Espaços:** 3\n\n**Preço:** 8.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Estrutura dorsal\n- Raridade: Muito Raro\n- Espaços: 3\n- Preço (Ⱥ): 8.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Icarus III","Tipo":"Estrutura dorsal","Raridade":"Muito Raro","Espaços":"3","Preço (Ⱥ)":"8.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"669aec2956b64e8285dedf71289229b1","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Icarus III","Tipo":"Estrutura dorsal","Raridade":"Muito Raro","Espaços":"3","Preço (Ⱥ)":"8.000"},"espacos_texto":"3"}},"id":"item:mobilidade_icarus_iii","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b43c126ced1e9c35f4ab0706b122bf84e144247c9c904bf1c006112f100ea614"},{"content_type":"item","slug":"mobilidade_luvas_de_escalada","payload":{"id":"mobilidade_luvas_de_escalada","slug":"mobilidade_luvas_de_escalada","nome":"Luvas de Escalada","raridade":"comum","raridade_label":"Comum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"*Luvas · Comum*","descricao_longa":"*Luvas · Comum*\n\nAs Luvas de Escalada possuem palmas aderentes, reforços nos dedos e pequenas garras retráteis para encontrar apoio em concreto, pedra, estruturas metálicas e outras superfícies irregulares. São usadas em manutenção vertical, resgate e acesso a estruturas onde uma rota convencional não está disponível.\n\n**Escalada:** você recebe **+1 de vantagem** em testes de **`Mobilidade`** realizados para escalar.\n\nEnquanto escala uma superfície que ofereça apoios suficientes, você pode usar **Manobrar** normalmente para se deslocar por ela.\n\nAs luvas não permitem escalar superfícies completamente lisas ou sem pontos de apoio adequados. Durante a escalada, suas mãos ficam ocupadas.\n\n**Espaços:** 1\n\n**Preço:** 120 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Luvas\n- Raridade: Comum\n- Espaços: 1\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Luvas de Escalada","Tipo":"Luvas","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"6c34493fb73642dfb1eb50eb8c5628f4","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Luvas de Escalada","Tipo":"Luvas","Raridade":"Comum","Espaços":"1","Preço (Ⱥ)":"120"},"espacos_texto":"1"}},"id":"item:mobilidade_luvas_de_escalada","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"8b46242053646e20be524544b60eed5f4eb304b11da0b8de0c9b7a39f6d1923c"},{"content_type":"item","slug":"mobilidade_magboots","payload":{"id":"mobilidade_magboots","slug":"mobilidade_magboots","nome":"Magboots","raridade":"raro","raridade_label":"Raro","preco":1200,"preco_texto":"1.200","preco_qualificador":null,"descricao_curta":"*Locomoção · Raro*","descricao_longa":"*Locomoção · Raro*\n\nAs Magboots possuem matrizes de aderência instaladas nas solas, capazes de ajustar continuamente a força do campo magnético durante cada passada. O sistema permite caminhar por superfícies metálicas verticais ou invertidas sem comprometer a mobilidade do usuário.\n\n**Aderência magnética:** enquanto estiver em contato com uma superfície metálica firme, você pode tratá-la como uma superfície transitável independentemente de sua orientação.\n\nVocê pode Andar, Correr e Manobrar normalmente por paredes, tetos, cascos de veículos e outras estruturas metálicas contínuas. A orientação da superfície não altera seu deslocamento.\n\nAs Magboots precisam permanecer em contato com uma superfície metálica ao longo do trajeto. Elas não permitem atravessar vãos, saltar entre superfícies distantes ou permanecer suspenso sem apoio.\n\n**Fixação magnética:** ao terminar um deslocamento sobre uma superfície metálica, você pode travar as Magboots nela. Enquanto estiver fixado, recebe **+1 de vantagem** em testes para **Resistir** a efeitos que tentem deslocá-lo involuntariamente para longe da superfície.\n\nEnquanto estiver fixado, você não pode se deslocar voluntariamente. Ao usar **Deslocar-se**, você pode liberar a fixação como parte da mesma ação, sem custo adicional.\n\n**Espaços:** 2\n\n**Preço:** 1.200 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Locomoção\n- Raridade: Raro\n- Espaços: 2\n- Preço (Ⱥ): 1.200","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Magboots","Tipo":"Locomoção","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"1.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"4c54162752ae4e0381cb926695202072","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Magboots","Tipo":"Locomoção","Raridade":"Raro","Espaços":"2","Preço (Ⱥ)":"1.200"},"espacos_texto":"2"}},"id":"item:mobilidade_magboots","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"ae3114798a006a99bbc8f4f5a59d361139b07275f0b6e3201cfe4ea24813893f"},{"content_type":"item","slug":"mobilidade_patinete_eletrico","payload":{"id":"mobilidade_patinete_eletrico","slug":"mobilidade_patinete_eletrico","nome":"Patinete Elétrico","raridade":"comum","raridade_label":"Comum","preco":700,"preco_texto":"700","preco_qualificador":null,"descricao_curta":"*Locomoção · Comum*","descricao_longa":"*Locomoção · Comum*\n\nO patinete elétrico possui uma plataforma estreita, duas rodas, guidão e um pequeno motor de propulsão. Leve e dobrável, é comum em trajetos urbanos curtos, onde permite circular sem esforço constante do usuário, embora dependa de piso adequado e ofereça estabilidade limitada.\n\n**Conduzir:** enquanto estiver sobre o patinete em uma superfície firme e contínua, ao usar **Deslocar-se** **`1 PA`**, você pode percorrer até 30 m. Você pode subir ou descer do patinete como parte desse deslocamento, sem custo adicional.\n\n**Acelerar:** enquanto estiver sobre o patinete em uma superfície firme e contínua, ao usar **Deslocar-se** **`1 PA`**, você pode aumentar a potência do motor para percorrer até 60 m. O narrador pode exigir um teste de **`Mobilidade`** nas mesmas condições de **Correr**. Em caso de falha, você percorre no máximo 25 m, e o narrador pode aplicar outra consequência apropriada, como ficar **`Caído`**.\n\nO patinete não funciona adequadamente em escadas, terreno acidentado, lama, areia, entulho denso ou superfícies muito irregulares. Quando a trajetória exigir curvas apertadas, desvio de obstáculos ou passagens estreitas, use as regras de **Manobrar**, mantendo o deslocamento do patinete.\n\n**Perda de equilíbrio:** se você ficar **`Caído`** enquanto utiliza o patinete, você cai e deixa de utilizá-lo. O patinete para no espaço onde isso ocorreu ou no espaço válido mais próximo.\n\n**Energia:** o patinete possui 3 cargas. Ao ativá-lo, 1 carga é consumida e mantém o equipamento funcionando por 1 hora. Enquanto você continuar utilizando o patinete, uma nova carga é consumida automaticamente sempre que a duração da carga anterior terminar. Você pode desligá-lo a qualquer momento.\n\n**Recarga:** durante um Descanso Longo, o patinete recupera todas as suas cargas. Ele também é compatível com Baterias Rúnicas; cada carga gasta de uma Bateria Rúnica restaura 1 carga do patinete.\n\nQuando dobrado, o patinete pode ser carregado, mas continua volumoso demais para uma mochila comum.\n\n**Espaços:** Carga\n\n**Preço:** 700 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Locomoção\n- Raridade: Comum\n- Espaços: Carga\n- Preço (Ⱥ): 700","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Patinete Elétrico","Tipo":"Locomoção","Raridade":"Comum","Espaços":"Carga","Preço (Ⱥ)":"700"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"257fd95a5b8c4fc5b5a05ae4c11aa439","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Patinete Elétrico","Tipo":"Locomoção","Raridade":"Comum","Espaços":"Carga","Preço (Ⱥ)":"700"},"espacos_texto":"Carga"}},"id":"item:mobilidade_patinete_eletrico","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9086d1443ec2884a9ccc678ad466dc123e112112c15ed7ff1b59391a87683397"},{"content_type":"item","slug":"mobilidade_rollsyns","payload":{"id":"mobilidade_rollsyns","slug":"mobilidade_rollsyns","nome":"Rollsyns","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"*Locomoção · Incomum*","descricao_longa":"*Locomoção · Incomum*\n\nOs Rollsyns são um par de patins motorizados com rodas retráteis, pequenos propulsores e estabilizadores que acompanham o movimento das pernas. O sistema amplifica o impulso produzido pelo usuário, permitindo atingir velocidades maiores sem substituir o esforço e a coordenação necessários para se locomover.\n\nSeu desempenho depende de superfícies firmes e relativamente regulares, onde é possível acumular velocidade e manter o movimento sem interrupções.\n\n**Patinar:** enquanto estiver usando os Rollsyns sobre uma superfície firme e relativamente regular, ao usar **Deslocar-se** **`1 PA`**, você pode percorrer até 2× seu Andar.\n\nSe percorrer pelo menos 6 m e terminar o deslocamento sem atravessar terreno difícil, você recebe **Embalo**.\n\nEnquanto tiver **Embalo**, seu próximo uso de Patinar permite percorrer até 3× seu Andar. Você mantém **Embalo** se percorrer pelo menos 6 m e terminar esse deslocamento sem atravessar terreno difícil.\n\nVocê perde **Embalo** se terminar seu turno sem Patinar, atravessar terreno difícil, ficar **`Caído`**, for impedido de continuar seu movimento ou realizar uma manobra que exija uma parada completa.\n\nQuando a trajetória exigir curvas bruscas, passagens estreitas, desvio de obstáculos ou outras manobras complexas, use as regras de **Manobrar**, mantendo o deslocamento dos Rollsyns. Em caso de falha, você também perde **Embalo**.\n\n**Energia:** os Rollsyns possuem 3 cargas. Ao começar a utilizá-los, 1 carga é consumida e mantém o equipamento funcionando por 1 hora. Enquanto você continuar utilizando os Rollsyns, uma nova carga é consumida automaticamente sempre que a duração da carga anterior terminar. Você pode desligá-los a qualquer momento.\n\n**Recarga:** durante um Descanso Longo, os Rollsyns recuperam todas as suas cargas. Eles também são compatíveis com Baterias Rúnicas; cada carga gasta de uma Bateria Rúnica restaura 1 carga dos Rollsyns.\n\n**Espaços:** 2\n\n**Preço:** 1.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Locomoção\n- Raridade: Incomum\n- Espaços: 2\n- Preço (Ⱥ): 1.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Rollsyns","Tipo":"Locomoção","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"1.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"f1eb0b9da61d4778a4b80b95e37a5e17","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Rollsyns","Tipo":"Locomoção","Raridade":"Incomum","Espaços":"2","Preço (Ⱥ)":"1.000"},"espacos_texto":"2"}},"id":"item:mobilidade_rollsyns","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"c41da298762eb69ffa4a244fa1d3f219a53ce521509715aee62cb366687a0449"},{"content_type":"item","slug":"mobilidade_skate","payload":{"id":"mobilidade_skate","slug":"mobilidade_skate","nome":"Skate","raridade":"comum","raridade_label":"Comum","preco":120,"preco_texto":"120","preco_qualificador":null,"descricao_curta":"*Locomoção · Comum*","descricao_longa":"*Locomoção · Comum*\n\nO skate é uma prancha de quatro rodas utilizada para percorrer distâncias curtas sobre superfícies firmes e relativamente lisas. É barato, portátil e fácil de carregar debaixo do braço, mas depende da qualidade do piso e exige equilíbrio constante.\n\n**Deslizar:** enquanto estiver sobre o skate em uma superfície firme, lisa e contínua, ao usar **Deslocar-se** **`1 PA`**, você pode percorrer até 20 m. Você pode subir ou descer do skate como parte desse deslocamento, sem custo adicional.\n\n**Acelerar:** enquanto estiver sobre o skate em uma superfície firme, lisa e contínua, ao usar **Deslocar-se** **`1 PA`**, você pode impulsioná-lo para percorrer até 40 m. O narrador pode exigir um teste de **`Mobilidade`** nas mesmas condições de **Correr**. Em caso de falha, você percorre no máximo 15 m, e o narrador pode aplicar outra consequência apropriada, como ficar **`Caído`**.\n\nO skate não funciona adequadamente em escadas, entulho, lama, areia, terreno muito irregular ou superfícies com rachaduras e desníveis acentuados. Quando a trajetória exigir curvas fechadas, desvio de obstáculos ou outras manobras complexas, use as regras de **Manobrar**, mantendo o deslocamento do skate.\n\n**Perda de equilíbrio:** se você ficar **`Caído`** enquanto utiliza o skate, você cai e deixa de utilizá-lo. O skate permanece no espaço onde isso ocorreu ou no espaço válido mais próximo.\n\n**Espaços:** 3\n\n**Preço:** 120 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Locomoção\n- Raridade: Comum\n- Espaços: 3\n- Preço (Ⱥ): 120","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["EQUIPAMENTOS DE MOBILIDADE"],"tipo_tabela":"Item","campos":{"Item":"Skate","Tipo":"Locomoção","Raridade":"Comum","Espaços":"3","Preço (Ⱥ)":"120"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"ac505df34b8f4416afb71927ab4967c3","linhaBlocoId":"53039e271c9343d7a27b12fbf1a70a22","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"mobilidade","categoria_label":"Mobilidade","subtipo":null,"estatisticas":{"campos_tabela":{"Item":"Skate","Tipo":"Locomoção","Raridade":"Comum","Espaços":"3","Preço (Ⱥ)":"120"},"espacos_texto":"3"}},"id":"item:mobilidade_skate","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"14aa0534b964d269f46f7069b896dffe091872eab08eb55cdc5b3e39376dfe23"},{"content_type":"item","slug":"mobilidade_boran_t6","payload":{"id":"mobilidade_boran_t6","slug":"mobilidade_boran_t6","nome":"BORAN T6","raridade":"comum","raridade_label":"Comum","preco":18000,"preco_texto":"18.000","preco_qualificador":null,"descricao_curta":"*Picape híbrida · Comum*","descricao_longa":"*Picape híbrida · Comum*\n\nA T6 é uma picape de cabine dupla, com espaço para cinco ocupantes e uma caçamba traseira aberta. Sua carroceria combina uma cabine fechada de quatro portas com um chassi reforçado, projetado para transportar ferramentas, suprimentos e equipamentos volumosos. A tampa traseira pode ser rebatida para facilitar o carregamento, enquanto as laterais da caçamba possuem trilhos e pontos de ancoragem para prender objetos durante o transporte.\n\nA suspensão reforçada suporta cargas distribuídas de maneira desigual, e painéis removíveis facilitam o acesso aos componentes mecânicos e rúnicos. Menor e mais ágil que os caminhões Boran, a T6 consegue circular por ruas estreitas, estradas de serviço e áreas de trabalho sem exigir grandes espaços de manobra. É comum entre equipes de manutenção, pequenos comerciantes, trabalhadores rurais e profissionais que precisam transportar pessoas e materiais no mesmo veículo.\n\n**Velocidade:** 195 km/h\n\n**Capacidade:** 5 pessoas\n\n**Carga:** Média\n\n**PD:** 28\n\n**Preço:** 18.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Picape híbrida\n- Raridade: Comum\n- Preço (Ⱥ): 18.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"BORAN T6","Tipo":"Picape híbrida","Raridade":"Comum","Preço (Ⱥ)":"18.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"b3c2777f45444c22823946a3ed09f0ee","linhaBlocoId":"3f30a136355280bd9419c882e19a779d","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"BORAN T6","Tipo":"Picape híbrida","Raridade":"Comum","Preço (Ⱥ)":"18.000"},"espacos_texto":null}},"id":"item:mobilidade_boran_t6","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"0dd9744c2c51e75ae4fda68d8ebac6283d57a221ecb9173de148c54c09946822"},{"content_type":"item","slug":"mobilidade_karden_r5","payload":{"id":"mobilidade_karden_r5","slug":"mobilidade_karden_r5","nome":"KARDEN R5","raridade":"raro","raridade_label":"Raro","preco":45000,"preco_texto":"45.000","preco_qualificador":null,"descricao_curta":"*Esportivo híbrido · Raro*","descricao_longa":"*Esportivo híbrido · Raro*\n\nO R5 mal deixa espaço entre a máquina e quem a dirige. Dois assentos baixos ocupam o centro de uma carroceria larga, cercados pelos módulos de propulsão e por tomadas de ar que atravessam as laterais até a traseira. As rodas ficam afastadas do corpo principal, presas a conjuntos independentes que corrigem tração e inclinação enquanto o veículo se move.\n\nEm velocidade, partes da própria carroceria se levantam, recolhem ou mudam de ângulo para manter o carro plantado no chão. Não há banco traseiro, quase não há espaço para bagagem e pouco foi feito para tornar a viagem confortável. O R5 existe para quem prefere sentir cada correção da máquina a entregá-la a um sistema automático.\n\n**Velocidade:** 360 km/h\n\n**Capacidade:** 2 pessoas\n\n**Carga:** Mínima\n\n**PD:** 15\n\n**Preço:** 45.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Esportivo híbrido\n- Raridade: Raro\n- Preço (Ⱥ): 45.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"KARDEN R5","Tipo":"Esportivo híbrido","Raridade":"Raro","Preço (Ⱥ)":"45.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"b3c2777f45444c22823946a3ed09f0ee","linhaBlocoId":"19c3688b45ad416da69ec7446acdc23e","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"KARDEN R5","Tipo":"Esportivo híbrido","Raridade":"Raro","Preço (Ⱥ)":"45.000"},"espacos_texto":null}},"id":"item:mobilidade_karden_r5","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"741d133f5d02739dd606307520aabe88e1043c5e81e8aeb79d9b6a2633c98cc2"},{"content_type":"item","slug":"mobilidade_orison_via","payload":{"id":"mobilidade_orison_via","slug":"mobilidade_orison_via","nome":"ORISON VIA","raridade":"incomum","raridade_label":"Incomum","preco":24000,"preco_texto":"24.000","preco_qualificador":null,"descricao_curta":"*Sedã autônomo híbrido · Incomum*","descricao_longa":"*Sedã autônomo híbrido · Incomum*\n\nNo Via, o lugar do motorista só existe quando alguém precisa dele. Durante a condução autônoma, os assentos dianteiros giram para dentro e a cabine se fecha em torno dos ocupantes como um pequeno salão. Quando uma pessoa assume o controle, comandos físicos e informações de condução surgem diante do assento escolhido.\n\nQuase toda a superfície envidraçada funciona também como tela. Rotas, mensagens e informações da cidade aparecem junto à paisagem, enquanto climatização, iluminação e disposição interna acompanham os perfis dos passageiros. É um carro comum entre quem passa tanto tempo dentro dele quanto fora: profissionais, famílias abastadas e serviços particulares que atravessam Vosek de um compromisso ao outro.\n\n**Condução autônoma:** o veículo pode realizar deslocamentos urbanos rotineiros, seguir rotas, estacionar e buscar passageiros sem que uma criatura o conduza. Um usuário autorizado pode chamá-lo remotamente para um ponto acessível pela malha viária.\n\nA condução autônoma não resolve situações excepcionais por conta própria, como terreno inadequado, infraestrutura comprometida, perseguições ou manobras extremas. Nessas situações, um ocupante precisa assumir o controle.\n\n**Velocidade:** 225 km/h\n\n**Capacidade:** 5 pessoas\n\n**Carga:** Média\n\n**PD:** 22\n\n**Preço:** 24.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Sedã autônomo híbrido\n- Raridade: Incomum\n- Preço (Ⱥ): 24.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"ORISON VIA","Tipo":"Sedã autônomo híbrido","Raridade":"Incomum","Preço (Ⱥ)":"24.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"b3c2777f45444c22823946a3ed09f0ee","linhaBlocoId":"1b8fae7bff9344959d2a2a72c68f04c6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"ORISON VIA","Tipo":"Sedã autônomo híbrido","Raridade":"Incomum","Preço (Ⱥ)":"24.000"},"espacos_texto":null}},"id":"item:mobilidade_orison_via","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"150208697dd10b1e13816a0f1802c8180eda8061cc741a72674f356ed6f35a31"},{"content_type":"item","slug":"mobilidade_veyra_n4","payload":{"id":"mobilidade_veyra_n4","slug":"mobilidade_veyra_n4","nome":"VEYRA N4","raridade":"comum","raridade_label":"Comum","preco":10000,"preco_texto":"10.000","preco_qualificador":null,"descricao_curta":"*Compacto híbrido · Comum*","descricao_longa":"*Compacto híbrido · Comum*\n\nO N4 é pequeno sem parecer apertado. A cabine começa quase na dianteira do carro, onde um veículo antigo teria capô, e termina pouco antes dos módulos traseiros. As quatro rodas ocupam os cantos da carroceria e giram de forma independente; em baixa velocidade, o carro consegue sair de uma vaga quase de lado ou mudar de direção dentro de espaços onde outro veículo precisaria manobrar várias vezes.\n\nPainéis presos por travas dão acesso às células de energia, aos condutores e aos conjuntos de roda sem desmontar metade do veículo. Oficinas conhecem o N4 de ponta a ponta. Peças usadas circulam aos montes, e poucos carros em Vosek acumulam tantas adaptações improvisadas ao longo da vida.\n\n**Velocidade:** 190 km/h\n\n**Capacidade:** 4 pessoas\n\n**Carga:** Pequena\n\n**PD:** 20\n\n**Preço:** 10.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Compacto híbrido\n- Raridade: Comum\n- Preço (Ⱥ): 10.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"VEYRA N4","Tipo":"Compacto híbrido","Raridade":"Comum","Preço (Ⱥ)":"10.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"b3c2777f45444c22823946a3ed09f0ee","linhaBlocoId":"973ceb56afae4bfc98907471825590cf","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"VEYRA N4","Tipo":"Compacto híbrido","Raridade":"Comum","Preço (Ⱥ)":"10.000"},"espacos_texto":null}},"id":"item:mobilidade_veyra_n4","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"508cf32fb66dcca6e3e441cdf52355e05bf32ccd4fe5e129e1e3f401eb2f2642"},{"content_type":"item","slug":"mobilidade_veyra_n6","payload":{"id":"mobilidade_veyra_n6","slug":"mobilidade_veyra_n6","nome":"VEYRA N6","raridade":"comum","raridade_label":"Comum","preco":15000,"preco_texto":"15.000","preco_qualificador":null,"descricao_curta":"*Sedã híbrido · Comum*","descricao_longa":"*Sedã híbrido · Comum*\n\nO N6 é um sedã de porte médio, com carroceria alongada, quatro portas e cabine para cinco ocupantes. Seu porta-malas separado oferece espaço para bagagens, ferramentas e equipamentos, enquanto os bancos traseiros podem ser rebatidos para acomodar objetos mais compridos. A distância maior entre os eixos proporciona mais espaço para as pernas e uma condução estável, especialmente em viagens longas.\n\nConstruído sobre a mesma plataforma do Veyra N4, o N6 conserva os módulos de roda independentes, os componentes de fácil acesso e a ampla disponibilidade de peças de reposição. Sua mecânica simples e o espaço interno generoso fizeram dele uma escolha frequente entre famílias, motoristas profissionais e pequenas empresas. É um dos sedãs mais comuns nas ruas de Vosek, valorizado pela combinação de conforto, capacidade de carga e manutenção acessível.\n\n**Velocidade:** 220 km/h\n\n**Capacidade:** 5 pessoas\n\n**Carga:** Média\n\n**PD:** 24\n\n**Preço:** 15.000 Ⱥ\n\n**Preço:** 15.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Sedã híbrido\n- Raridade: Comum\n- Preço (Ⱥ): 15.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"VEYRA N6","Tipo":"Sedã híbrido","Raridade":"Comum","Preço (Ⱥ)":"15.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"b3c2777f45444c22823946a3ed09f0ee","linhaBlocoId":"9a8c8891dda44cb88aa16791694eb4bd","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"VEYRA N6","Tipo":"Sedã híbrido","Raridade":"Comum","Preço (Ⱥ)":"15.000"},"espacos_texto":null}},"id":"item:mobilidade_veyra_n6","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"22f5221b7a3d3b9eb09827bfcb165ed80cb647f0b66c905dc05b288568665abf"},{"content_type":"item","slug":"mobilidade_veyra_nx","payload":{"id":"mobilidade_veyra_nx","slug":"mobilidade_veyra_nx","nome":"VEYRA NX","raridade":"incomum","raridade_label":"Incomum","preco":21000,"preco_texto":"21.000","preco_qualificador":null,"descricao_curta":"*Esportivo híbrido · Incomum*","descricao_longa":"*Esportivo híbrido · Incomum*\n\nO NX leva a mecânica simples da Veyra até onde ela consegue ir sem virar uma máquina de competição. A cabine desce entre os quatro módulos de roda, parcialmente expostos nas laterais, e a carroceria estreita muda discretamente de forma conforme a velocidade aumenta. Sob carga, cada roda corrige sua própria tração enquanto pequenas superfícies móveis ajustam o fluxo de ar.\n\nAinda há quatro lugares e espaço suficiente para bagagem ou equipamento, e boa parte dos componentes continua acessível a uma oficina comum. Por isso o NX aparece tanto nas mãos de entusiastas quanto em rachas clandestinos: é rápido de fábrica, mas continua convidando o proprietário a abrir os painéis e mexer no que há por baixo.\n\n**Velocidade:** 270 km/h\n\n**Capacidade:** 4 pessoas\n\n**Carga:** Pequena\n\n**PD:** 20\n\n**Preço:** 21.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Esportivo híbrido\n- Raridade: Incomum\n- Preço (Ⱥ): 21.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"VEYRA NX","Tipo":"Esportivo híbrido","Raridade":"Incomum","Preço (Ⱥ)":"21.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"b3c2777f45444c22823946a3ed09f0ee","linhaBlocoId":"c7d42e2fc6b6483db691dff54dd34422","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"VEYRA NX","Tipo":"Esportivo híbrido","Raridade":"Incomum","Preço (Ⱥ)":"21.000"},"espacos_texto":null}},"id":"item:mobilidade_veyra_nx","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"750f8c03ff05e0d3356b4b349d13c2f61d18834cb05559b9fbe03ef9c1b4314b"},{"content_type":"item","slug":"mobilidade_veyra_t7","payload":{"id":"mobilidade_veyra_t7","slug":"mobilidade_veyra_t7","nome":"VEYRA T7","raridade":"incomum","raridade_label":"Incomum","preco":23000,"preco_texto":"23.000","preco_qualificador":null,"descricao_curta":"*SUV híbrido · Incomum*","descricao_longa":"*SUV híbrido · Incomum*\n\nO T7 é um SUV de porte médio, com carroceria alta, suspensão elevada e cabine fechada para cinco ocupantes. As rodas ficam posicionadas próximas às extremidades da carroceria, ampliando a estabilidade, enquanto os conjuntos de suspensão independentes absorvem as irregularidades do terreno. A dianteira curta, os painéis inferiores reforçados e a maior distância do solo permitem atravessar estradas danificadas e caminhos acidentados sem expor os componentes mecânicos mais sensíveis.\n\nO interior combina conforto com espaço para bagagens e equipamentos. Os bancos traseiros podem ser rebatidos para ampliar o compartimento de carga, e os painéis de manutenção permitem acessar os principais componentes sem desmontar a carroceria. O T7 é utilizado por equipes de campo, profissionais que circulam entre cidades e moradores de regiões onde as vias pavimentadas dão lugar a estradas de terra, terrenos irregulares e trajetos pouco conservados.\n\n**Velocidade:** 210 km/h\n\n**Capacidade:** 5 pessoas\n\n**Carga:** Média\n\n**PD:** 28\n\n**Preço:** 23.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: SUV híbrido\n- Raridade: Incomum\n- Preço (Ⱥ): 23.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"VEYRA T7","Tipo":"SUV híbrido","Raridade":"Incomum","Preço (Ⱥ)":"23.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"b3c2777f45444c22823946a3ed09f0ee","linhaBlocoId":"3f30a136355280d8a28af4d3b3f4d01d","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"VEYRA T7","Tipo":"SUV híbrido","Raridade":"Incomum","Preço (Ⱥ)":"23.000"},"espacos_texto":null}},"id":"item:mobilidade_veyra_t7","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"cd46d595c39647b02ac854fc524e1f138518d600d91f83815d9f7f242636f5a5"},{"content_type":"item","slug":"mobilidade_aera_c2","payload":{"id":"mobilidade_aera_c2","slug":"mobilidade_aera_c2","nome":"AERA C2","raridade":"incomum","raridade_label":"Incomum","preco":22000,"preco_texto":"22.000","preco_qualificador":null,"descricao_curta":"*Compacto planado · Incomum*","descricao_longa":"*Compacto planado · Incomum*\n\nO C2 é um planado curto, de cabine arredondada e laterais quase inteiramente envidraçadas. Quatro módulos cinéticos ocupam os cantos da parte inferior da carroceria, distribuindo sustentação e corrigindo a inclinação sem exigir grandes superfícies externas. Desligado, o veículo repousa sobre suportes retráteis e fica a poucos centímetros do piso.\n\nNo ar, a cabine permanece estável mesmo quando o C2 muda de altura ou entra numa curva. Essa previsibilidade ajudou a torná-lo uma visão habitual nas rotas aéreas de Vosek: pequeno o bastante para o tráfego urbano, simples o bastante para não exigir o tratamento reservado aos planados mais caros.\n\n**Velocidade:** 240 km/h\n\n**Capacidade:** 4 pessoas\n\n**Carga:** Pequena\n\n**PD:** 22\n\n**Preço:** 22.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Compacto planado\n- Raridade: Incomum\n- Preço (Ⱥ): 22.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"AERA C2","Tipo":"Compacto planado","Raridade":"Incomum","Preço (Ⱥ)":"22.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"bb6361584b9a4c32a2441c3007ef40f4","linhaBlocoId":"808d1f39f9e549da8a6bf6d686f448e6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"AERA C2","Tipo":"Compacto planado","Raridade":"Incomum","Preço (Ⱥ)":"22.000"},"espacos_texto":null}},"id":"item:mobilidade_aera_c2","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"d2b2e8e9ae022e2dc7a41afd06d9e28521e5970c5a156e0298f222ce3116f948"},{"content_type":"item","slug":"mobilidade_velys_atrium","payload":{"id":"mobilidade_velys_atrium","slug":"mobilidade_velys_atrium","nome":"VELYS ATRIUM","raridade":"raro","raridade_label":"Raro","preco":70000,"preco_texto":"70.000","preco_qualificador":null,"descricao_curta":"*Planado executivo autônomo · Raro*","descricao_longa":"*Planado executivo autônomo · Raro*\n\nO Atrium tem mais em comum com uma sala suspensa do que com uma cabine de pilotagem. O teto é alto, os assentos podem mudar de posição e as laterais se abrem em portas largas, pensadas para permitir entrada e saída sem atravessar um posto de condução. Não existe um assento permanentemente reservado ao piloto.\n\nPor fora, a carroceria forma uma superfície quase contínua. Os módulos cinéticos ficam escondidos sob o casco e só os acessos de manutenção denunciam sua posição. Dentro, vidro inteligente, iluminação e superfícies de comando aparecem apenas quando necessários. É um veículo feito para atravessar Vosek sem interromper uma reunião, uma conversa ou uma viagem confortável por causa do simples ato de pilotar.\n\n**Voo autônomo:** o Atrium pode realizar deslocamentos rotineiros pelas rotas aéreas, decolar, pousar, estacionar e buscar passageiros sem que uma criatura o conduza. Um usuário autorizado pode chamá-lo remotamente para um ponto acessível pelo tráfego aéreo. Situações excepcionais, como perseguições, rotas não mapeadas, infraestrutura comprometida ou manobras extremas, exigem controle manual.\n\n**Velocidade:** 250 km/h\n\n**Capacidade:** 6 pessoas\n\n**Carga:** Grande\n\n**PD:** 26\n\n**Preço:** 70.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Planado executivo autônomo\n- Raridade: Raro\n- Preço (Ⱥ): 70.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"VELYS ATRIUM","Tipo":"Planado executivo autônomo","Raridade":"Raro","Preço (Ⱥ)":"70.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"bb6361584b9a4c32a2441c3007ef40f4","linhaBlocoId":"9d7a418cd077448e97ad0d2dbc793143","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"VELYS ATRIUM","Tipo":"Planado executivo autônomo","Raridade":"Raro","Preço (Ⱥ)":"70.000"},"espacos_texto":null}},"id":"item:mobilidade_velys_atrium","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"e3936d46ad3a0974852f09c19f0b372a1cea83e774ba913d14303f4f9ed7192a"},{"content_type":"item","slug":"mobilidade_soryn_m2","payload":{"id":"mobilidade_soryn_m2","slug":"mobilidade_soryn_m2","nome":"SORYN M2","raridade":"comum","raridade_label":"Comum","preco":4000,"preco_texto":"4.000","preco_qualificador":null,"descricao_curta":"*Moto urbana híbrida · Comum*","descricao_longa":"*Moto urbana híbrida · Comum*\n\nA M2 tem chassi curto, rodas largas e quase nenhum acabamento que esconda suas peças de serviço. Os conjuntos de tração ocupam os cubos, a suspensão fica protegida apenas onde precisa ficar e uma faixa estreita de vidro junto ao guidão reúne navegação, velocidade e alertas do veículo.\n\nNa traseira, pontos de fixação recebem caixas, bolsas rígidas e pequenos suportes sem exigir adaptações no quadro. É uma moto feita para passar o dia circulando: entregadores, técnicos e trabalhadores que precisam cortar trânsito, parar em qualquer canto e voltar a rodar sem cerimônia usam a M2 até a carenagem acumular mais remendos do que pintura original.\n\n**Velocidade:** 210 km/h\n\n**Capacidade:** 2 pessoas\n\n**Carga:** Pequena\n\n**PD:** 15\n\n**Preço:** 4.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Moto urbana híbrida\n- Raridade: Comum\n- Preço (Ⱥ): 4.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"SORYN M2","Tipo":"Moto urbana híbrida","Raridade":"Comum","Preço (Ⱥ)":"4.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"1a9572ebde2048448e50a3ffd3faac03","linhaBlocoId":"2e2a789cac9a4efca730d5289c7d4e03","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"SORYN M2","Tipo":"Moto urbana híbrida","Raridade":"Comum","Preço (Ⱥ)":"4.000"},"espacos_texto":null}},"id":"item:mobilidade_soryn_m2","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"23b394ec874444757c8d8861efb6d8dd8792284484732ddd4197a77e3614ff81"},{"content_type":"item","slug":"mobilidade_soryn_vanta","payload":{"id":"mobilidade_soryn_vanta","slug":"mobilidade_soryn_vanta","nome":"SORYN VANTA","raridade":"raro","raridade_label":"Raro","preco":15000,"preco_texto":"15.000","preco_qualificador":null,"descricao_curta":"*Moto esportiva híbrida · Raro*","descricao_longa":"*Moto esportiva híbrida · Raro*\n\nA Vanta é comprida, baixa e desconfortavelmente próxima do chão. O piloto se inclina sobre uma dianteira estreita enquanto a traseira se prolonga para acomodar tração e resfriamento. Parte da suspensão permanece à mostra, assim como os condutores que alimentam os módulos das rodas.\n\nPequenas aletas surgem da carenagem quando a velocidade sobe e voltam a desaparecer nas retas mais lentas. No painel, quase tudo que não ajuda a conduzir foi eliminado: velocidade, tração, temperatura e avisos críticos. A Vanta não tenta ser versátil. É uma moto feita para quem considera o trajeto entre dois lugares uma oportunidade de chegar antes.\n\n**Velocidade:** 320 km/h\n\n**Capacidade:** 2 pessoas\n\n**Carga:** Mínima\n\n**PD:** 13\n\n**Preço:** 16.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Moto esportiva híbrida\n- Raridade: Raro\n- Preço (Ⱥ): 15.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"SORYN VANTA","Tipo":"Moto esportiva híbrida","Raridade":"Raro","Preço (Ⱥ)":"15.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"1a9572ebde2048448e50a3ffd3faac03","linhaBlocoId":"0e1e2d108bba4763862d9e52a3b755b6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"SORYN VANTA","Tipo":"Moto esportiva híbrida","Raridade":"Raro","Preço (Ⱥ)":"15.000"},"espacos_texto":null}},"id":"item:mobilidade_soryn_vanta","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9124cab1980a86e30b79d0bfacdf44dc9a03181958b50638d6f41c5586bdcc67"},{"content_type":"item","slug":"mobilidade_nyxen_lark","payload":{"id":"mobilidade_nyxen_lark","slug":"mobilidade_nyxen_lark","nome":"NYXEN LARK","raridade":"incomum","raridade_label":"Incomum","preco":15000,"preco_texto":"15.000","preco_qualificador":null,"descricao_curta":"*Moto planada urbana · Incomum*","descricao_longa":"*Moto planada urbana · Incomum*\n\nA Lark concentra quase tudo que precisa para voar num corpo curto e estreito. Os módulos cinéticos ficam alojados sob a carenagem, enquanto a traseira permanece livre para receber pequenas caixas ou bolsas rígidas. Desligada, apoia-se em dois suportes retráteis escondidos na parte inferior.\n\nNo ar, não tenta imitar a estabilidade de um carro planado. A moto inclina com o piloto, corrige a sustentação durante a curva e recupera o nível quando o movimento termina. É barata para a categoria, pequena para os corredores mais congestionados e muito usada por quem transforma minutos de deslocamento em parte do trabalho: mensageiros, entregadores e gente que não pode depender do trânsito no chão.\n\n**Velocidade:** 250 km/h\n\n**Capacidade:** 2 pessoas\n\n**Carga:** Mínima\n\n**PD:** 13\n\n**Preço:** 14.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Moto planada urbana\n- Raridade: Incomum\n- Preço (Ⱥ): 15.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"NYXEN LARK","Tipo":"Moto planada urbana","Raridade":"Incomum","Preço (Ⱥ)":"15.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"588ff6f7e9ca4f6a8702743e2e29f4ba","linhaBlocoId":"7a7dceef8095472ea864ccae5528c140","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"NYXEN LARK","Tipo":"Moto planada urbana","Raridade":"Incomum","Preço (Ⱥ)":"15.000"},"espacos_texto":null}},"id":"item:mobilidade_nyxen_lark","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"5a314d9ae6e5725f9f3899d831df3d2127ed5db86119cbe249c8f086886da4c6"},{"content_type":"item","slug":"mobilidade_nyxen_raze","payload":{"id":"mobilidade_nyxen_raze","slug":"mobilidade_nyxen_raze","nome":"NYXEN RAZE","raridade":"raro","raridade_label":"Raro","preco":35000,"preco_texto":"35.000","preco_qualificador":null,"descricao_curta":"*Moto planada esportiva · Raro*","descricao_longa":"*Moto planada esportiva · Raro*\n\nA Raze reduz a moto a uma carenagem estreita cercada por vetores cinéticos. O piloto viaja quase deitado, com braços e pernas encaixados junto ao corpo central, enquanto módulos parcialmente expostos corrigem sustentação, frenagem e direção de forma independente.\n\nA geometria favorece mudanças bruscas de altitude e curvas que fariam uma cabine convencional perder estabilidade. Em troca, há espaço para uma única pessoa e praticamente nada além dela. O painel acompanha essa lógica: velocidade, altitude, vetores e alertas críticos, sem informação sobrando. Entre os planados civis, poucas máquinas deixam tão evidente que conforto foi a primeira coisa sacrificada.\n\n**Velocidade:** 350 km/h\n\n**Capacidade:** 1 pessoa\n\n**Carga:** Mínima\n\n**PD:** 12\n\n**Preço:** 35.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Moto planada esportiva\n- Raridade: Raro\n- Preço (Ⱥ): 35.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"NYXEN RAZE","Tipo":"Moto planada esportiva","Raridade":"Raro","Preço (Ⱥ)":"35.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"588ff6f7e9ca4f6a8702743e2e29f4ba","linhaBlocoId":"038f77f54d9c4d8889486e767e2bc33a","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"NYXEN RAZE","Tipo":"Moto planada esportiva","Raridade":"Raro","Preço (Ⱥ)":"35.000"},"espacos_texto":null}},"id":"item:mobilidade_nyxen_raze","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"8070288d2610bb0c4060fbf53af39f6dd2b3b7fab2bba0e796a312305544df99"},{"content_type":"item","slug":"mobilidade_velys_iris","payload":{"id":"mobilidade_velys_iris","slug":"mobilidade_velys_iris","nome":"VELYS IRIS","raridade":"raro","raridade_label":"Raro","preco":28000,"preco_texto":"28.000","preco_qualificador":null,"descricao_curta":"*Moto planada autônoma · Raro*","descricao_longa":"*Moto planada autônoma · Raro*\n\nA Iris envolve piloto e passageiro com uma carenagem mais larga do que a de outras motos planadas. Em vez de deixar o corpo inteiro inclinar livremente nas curvas, seus módulos cinéticos compensam parte do movimento e mantêm o conjunto mais próximo do nível, sobretudo quando o sistema autônomo está conduzindo.\n\nOs controles manuais permanecem recolhidos até alguém assumir a direção. Fora disso, a frente é limpa, quase sem instrumentos visíveis, e a própria carenagem exibe apenas as informações necessárias aos ocupantes. A Iris troca parte da agressividade de uma Nyxen pela possibilidade de chamar a moto, embarcar e atravessar as rotas aéreas sem que ninguém precise pilotá-la.\n\n**Voo autônomo:** a Iris pode realizar deslocamentos rotineiros pelas rotas aéreas, decolar, pousar, estacionar e buscar passageiros sem que uma criatura a conduza. Um usuário autorizado pode chamá-la remotamente para um ponto acessível pelo tráfego aéreo. Situações excepcionais, como perseguições, rotas não mapeadas, infraestrutura comprometida ou manobras extremas, exigem controle manual.\n\n**Velocidade:** 270 km/h\n\n**Capacidade:** 2 pessoas\n\n**Carga:** Mínima\n\n**PD:** 14\n\n**Preço:** 28.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Moto planada autônoma\n- Raridade: Raro\n- Preço (Ⱥ): 28.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"VELYS IRIS","Tipo":"Moto planada autônoma","Raridade":"Raro","Preço (Ⱥ)":"28.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"588ff6f7e9ca4f6a8702743e2e29f4ba","linhaBlocoId":"90b5ee0cb054485e981534e3af49fda5","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"VELYS IRIS","Tipo":"Moto planada autônoma","Raridade":"Raro","Preço (Ⱥ)":"28.000"},"espacos_texto":null}},"id":"item:mobilidade_velys_iris","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"eccfb8d693f8742f1cca35090049e57e006c201771b9a34f1be4535f0eb5d5ad"},{"content_type":"item","slug":"mobilidade_aera_l8","payload":{"id":"mobilidade_aera_l8","slug":"mobilidade_aera_l8","nome":"AERA L8","raridade":"raro","raridade_label":"Raro","preco":42000,"preco_texto":"42.000","preco_qualificador":null,"descricao_curta":"*Furgão planado · Raro*","descricao_longa":"*Furgão planado · Raro*\n\nO L8 é um furgão de carga planado, com carroceria alta, linhas retas e um compartimento traseiro inteiramente fechado. A cabine para quatro ocupantes fica concentrada na dianteira, deixando a maior parte do veículo disponível para o transporte de mercadorias e equipamentos. Portas largas nas laterais e na traseira facilitam o carregamento, enquanto o piso reforçado possui pontos de fixação para manter cargas pesadas no lugar durante o voo.\n\nOs módulos cinéticos de sustentação ficam parcialmente expostos sob a carroceria e nas laterais, protegidos por painéis de manutenção. São maiores que os encontrados em planados compactos e ajustam continuamente a sustentação para compensar o peso e a distribuição da carga. Embora volumoso, o L8 consegue operar em espaços de pouso relativamente pequenos, sendo utilizado no abastecimento de instalações elevadas, transporte de maquinário e entregas comerciais que exigem acesso aéreo.\n\n**Velocidade:** 220 km/h\n\n**Capacidade:** 4 pessoas\n\n**Carga:** Grande\n\n**PD:** 30\n\n**Preço:** 42.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Furgão planado\n- Raridade: Raro\n- Preço (Ⱥ): 42.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"AERA L8","Tipo":"Furgão planado","Raridade":"Raro","Preço (Ⱥ)":"42.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"6536d3f499b943efb0e30e84cc66cc9b","linhaBlocoId":"3f30a136355280bd8e4ac3314b195a63","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"AERA L8","Tipo":"Furgão planado","Raridade":"Raro","Preço (Ⱥ)":"42.000"},"espacos_texto":null}},"id":"item:mobilidade_aera_l8","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"47046d3b4ffb1daf615764eaf0005e39460f9267f09870a1a8d640147c86c2c8"},{"content_type":"item","slug":"mobilidade_boran_m8","payload":{"id":"mobilidade_boran_m8","slug":"mobilidade_boran_m8","nome":"BORAN M8","raridade":"comum","raridade_label":"Comum","preco":22000,"preco_texto":"22.000","preco_qualificador":null,"descricao_curta":"*Furgão híbrido · Comum*","descricao_longa":"*Furgão híbrido · Comum*\n\nO M8 é um furgão de carga de carroceria retangular, com cabine curta para dois ocupantes e um compartimento traseiro fechado que ocupa a maior parte de seu comprimento. Portas largas dão acesso à baia de carga, cujo piso reforçado possui trilhos, pontos de fixação e conexões de energia e dados. O interior foi projetado para acomodar mercadorias volumosas ou receber módulos especializados sem exigir alterações permanentes na estrutura.\n\nSua construção privilegia resistência e facilidade de manutenção. Painéis removíveis permitem acessar os componentes mecânicos e rúnicos, enquanto a suspensão reforçada mantém o veículo estável mesmo com a baia carregada. Comum em serviços de entrega, manutenção urbana e transporte comercial, o M8 também é utilizado como base para oficinas móveis, clínicas e unidades de apoio que precisam circular pela cidade.\n\n**Encaixes modulares:** 1\n\n**Velocidade:** 185 km/h\n\n**Capacidade:** 2 pessoas\n\n**Carga:** Grande\n\n**PD:** 32\n\n**Preço:** 22.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Furgão híbrido\n- Raridade: Comum\n- Preço (Ⱥ): 22.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"BORAN M8","Tipo":"Furgão híbrido","Raridade":"Comum","Preço (Ⱥ)":"22.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"6536d3f499b943efb0e30e84cc66cc9b","linhaBlocoId":"bd7d82dc2b1c4e29adf65e37452a4e09","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"BORAN M8","Tipo":"Furgão híbrido","Raridade":"Comum","Preço (Ⱥ)":"22.000"},"espacos_texto":null}},"id":"item:mobilidade_boran_m8","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b513c8ee074fd589dee976992a67b9f635fa2c8f66e7096c19a3f97c92b22eb3"},{"content_type":"item","slug":"mobilidade_boran_m12","payload":{"id":"mobilidade_boran_m12","slug":"mobilidade_boran_m12","nome":"BORAN M12","raridade":"incomum","raridade_label":"Incomum","preco":30000,"preco_texto":"30.000","preco_qualificador":null,"descricao_curta":"*Caminhão híbrido · Incomum*","descricao_longa":"*Caminhão híbrido · Incomum*\n\nO M12 é um caminhão de carga pesada, com cabine dianteira para quatro ocupantes e uma extensa plataforma traseira aberta. O chassi largo e reforçado sustenta equipamentos industriais, contêineres e estruturas modulares, presos por trilhos e pontos de ancoragem distribuídos ao longo da plataforma. Conexões de energia e dados permitem instalar até dois módulos especializados, transformando o caminhão conforme as necessidades de transporte ou trabalho.\n\nApesar das dimensões, o M12 possui uma capacidade de manobra incomum para um veículo de seu porte. Seus conjuntos de rodas dianteiros e traseiros esterçam independentemente, permitindo deslocamentos laterais controlados e facilitando o posicionamento em docas, depósitos e espaços industriais apertados. A suspensão compensa diferenças na distribuição do peso, mantendo a plataforma estável durante o transporte de cargas volumosas. O modelo é amplamente utilizado em obras, operações logísticas, recuperação de equipamentos e transporte de maquinário pesado.\n\n**Encaixes modulares:** 2\n\n**Velocidade:** 175 km/h\n\n**Capacidade:** 4 pessoas\n\n**Carga:** Grande\n\n**PD:** 40\n\n**Preço:** 30.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Caminhão híbrido\n- Raridade: Incomum\n- Preço (Ⱥ): 30.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"BORAN M12","Tipo":"Caminhão híbrido","Raridade":"Incomum","Preço (Ⱥ)":"30.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"6536d3f499b943efb0e30e84cc66cc9b","linhaBlocoId":"90966c5a2b9342a6b1d9a98f62e93f34","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"BORAN M12","Tipo":"Caminhão híbrido","Raridade":"Incomum","Preço (Ⱥ)":"30.000"},"espacos_texto":null}},"id":"item:mobilidade_boran_m12","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"da76afbab6426e96688355bf513bf2993e6879aa3f0aea3c642a1a151f6f686d"},{"content_type":"item","slug":"mobilidade_orison_vecta","payload":{"id":"mobilidade_orison_vecta","slug":"mobilidade_orison_vecta","nome":"ORISON VECTA","raridade":"incomum","raridade_label":"Incomum","preco":26000,"preco_texto":"26.000","preco_qualificador":null,"descricao_curta":"*Van de passageiros híbrida · Incomum*","descricao_longa":"*Van de passageiros híbrida · Incomum*\n\nA Vecta é uma van de passageiros com carroceria alongada, teto elevado e cabine integrada, projetada para acomodar até oito ocupantes. As portas laterais deslizantes dão acesso às fileiras de bancos, enquanto o corredor central permite circular pelo interior sem precisar sair do veículo. Grandes superfícies envidraçadas oferecem visibilidade aos passageiros, e a abertura traseira dá acesso a um compartimento reservado para bagagens e equipamentos.\n\nO interior privilegia conforto e flexibilidade. Os bancos podem ser ajustados ou parcialmente recolhidos para ampliar o espaço disponível para carga, enquanto a climatização e a suspensão compensam as variações de peso durante viagens com lotação completa. A Vecta é utilizada por serviços de transporte privado, instituições, equipes de trabalho e famílias numerosas, sendo uma alternativa aos automóveis convencionais quando é necessário transportar várias pessoas em um único veículo.\n\n**Velocidade:** 190 km/h\n\n**Capacidade:** 8 pessoas\n\n**Carga:** Média\n\n**PD:** 26\n\n**Preço:** 26.000 Ⱥ\n\nDados da lista de mercadorias:\n- Tipo: Van híbrida\n- Raridade: Incomum\n- Preço (Ⱥ): 26.000","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS"],"tipo_tabela":"Modelo","campos":{"Modelo":"ORISON VECTA","Tipo":"Van híbrida","Raridade":"Incomum","Preço (Ⱥ)":"26.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":"6536d3f499b943efb0e30e84cc66cc9b","linhaBlocoId":"3f30a13635528085a794d6c66908cfb6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"veiculo","categoria_label":"Veículo","subtipo":null,"estatisticas":{"campos_tabela":{"Modelo":"ORISON VECTA","Tipo":"Van híbrida","Raridade":"Incomum","Preço (Ⱥ)":"26.000"},"espacos_texto":null}},"id":"item:mobilidade_orison_vecta","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"f5cfedb6065c3348c677824d2ee315d389bf233948c1533d83ddc15222584f2c"},{"content_type":"item","slug":"mobilidade_baia_de_unidades","payload":{"id":"mobilidade_baia_de_unidades","slug":"mobilidade_baia_de_unidades","nome":"BAIA DE UNIDADES","raridade":"incomum","raridade_label":"Incomum","preco":800,"preco_texto":"800 Ⱥ","preco_qualificador":null,"descricao_curta":"*Módulo veicular · Incomum*","descricao_longa":"*Módulo veicular · Incomum*\n\nSuportes articulados, travas de retenção, conexões de dados e pontos de energia permitem transportar drones e robôs em compartimentos próprios, mantendo as unidades presas e prontas para operação.\n\n**Armazenamento de Unidades:** a baia pode transportar **até 2 drones ou 1 robô** que caiba fisicamente em seu compartimento sem ocupar a Carga normal do veículo.\n\n**Lançar Unidade** **`1 PA`**: uma criatura dentro do veículo pode liberar uma Unidade armazenada na baia em um espaço adjacente ao veículo, desde que exista uma saída desobstruída.\n\nUma Unidade pode ser recolhida novamente quando estiver adjacente ao veículo e houver espaço para acomodá-la.\n\nA baia fornece conexões adequadas para diagnóstico, programação e manutenção, mas não recupera automaticamente PD, munições, cargas ou outros recursos da Unidade.\n\n**Preço:** 800 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Incomum\n- Preço: 800 Ⱥ","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS","MÓDULOS BORAN"],"tipo_tabela":"Verbete sem tabela","campos":{"Raridade":"Incomum","Preço":"800 Ⱥ"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":null,"linhaBlocoId":"eb5cabcd168d40c4880fd849c6349409","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"modulo_veicular","categoria_label":"Módulo Veicular","subtipo":null,"estatisticas":{"campos_tabela":{"Raridade":"Incomum","Preço":"800 Ⱥ"},"espacos_texto":null}},"id":"item:mobilidade_baia_de_unidades","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"c9bbb13fb94f78823dde30ee2e2ad10c557c72b067a136633a5598f78d11e92a"},{"content_type":"item","slug":"mobilidade_compartimento_oculto","payload":{"id":"mobilidade_compartimento_oculto","slug":"mobilidade_compartimento_oculto","nome":"COMPARTIMENTO OCULTO","raridade":"incomum","raridade_label":"Incomum","preco":500,"preco_texto":"500 Ⱥ","preco_qualificador":null,"descricao_curta":"*Módulo veicular · Incomum*","descricao_longa":"*Módulo veicular · Incomum*\n\nPainéis falsos, cavidades estruturais e acessos independentes escondem uma segunda área de armazenamento entre a baia e a carroceria.\n\n**Compartimento oculto:** permite armazenar uma quantidade de equipamento equivalente a uma **Carga Média** sem ocupar a Carga normal do veículo.\n\nSeu conteúdo não é revelado por uma inspeção superficial. Localizá-lo exige uma busca direcionada capaz de identificar modificações ou compartimentos clandestinos.\n\n**Preço:** 500 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Incomum\n- Preço: 500 Ⱥ","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS","MÓDULOS BORAN"],"tipo_tabela":"Verbete sem tabela","campos":{"Raridade":"Incomum","Preço":"500 Ⱥ"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":null,"linhaBlocoId":"fcc56b17a0d14f14a69e0373e9e32c05","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"modulo_veicular","categoria_label":"Módulo Veicular","subtipo":null,"estatisticas":{"campos_tabela":{"Raridade":"Incomum","Preço":"500 Ⱥ"},"espacos_texto":null}},"id":"item:mobilidade_compartimento_oculto","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"6f7077ba24af87765f34c35757b5c7cd25dad1bbe441ba0082a302721d0d91d7"},{"content_type":"item","slug":"mobilidade_modulo_de_transporte","payload":{"id":"mobilidade_modulo_de_transporte","slug":"mobilidade_modulo_de_transporte","nome":"MÓDULO DE TRANSPORTE","raridade":"comum","raridade_label":"Comum","preco":300,"preco_texto":"300 Ⱥ","preco_qualificador":null,"descricao_curta":"*Módulo veicular · Comum*","descricao_longa":"*Módulo veicular · Comum*\n\nFileiras de assentos retráteis, suportes individuais e sistemas de segurança transformam a baia utilitária em um compartimento para passageiros.\n\n**Transporte:** aumenta a Capacidade do veículo em **4 pessoas** e reduz sua Carga em **1 categoria**.\n\n**Preço:** 300 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Comum\n- Preço: 300 Ⱥ","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS","MÓDULOS BORAN"],"tipo_tabela":"Verbete sem tabela","campos":{"Raridade":"Comum","Preço":"300 Ⱥ"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":null,"linhaBlocoId":"2f029bdc2d684f9480bda94adfe79d6f","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"modulo_veicular","categoria_label":"Módulo Veicular","subtipo":null,"estatisticas":{"campos_tabela":{"Raridade":"Comum","Preço":"300 Ⱥ"},"espacos_texto":null}},"id":"item:mobilidade_modulo_de_transporte","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"6e60a92bf3199027fac200338402e993f4ad9feac66d700af89a30a16847adac"},{"content_type":"item","slug":"mobilidade_modulo_clinica","payload":{"id":"mobilidade_modulo_clinica","slug":"mobilidade_modulo_clinica","nome":"MÓDULO-CLÍNICA","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000 Ⱥ","preco_qualificador":null,"descricao_curta":"*Módulo veicular · Incomum*","descricao_longa":"*Módulo veicular · Incomum*\n\nO módulo transforma a baia em uma unidade médica compacta, equipada com maca estabilizada, armazenamento refrigerado, monitores, iluminação cirúrgica e instrumentos para diagnóstico e intervenção.\n\n**Clínica móvel:** enquanto o veículo estiver parado, o módulo conta como infraestrutura médica adequada para cuidados físicos, diagnóstico e tratamento de ferimentos, incluindo atendimento especializado de Membros Feridos.\n\nTestes de **`Medicina`** realizados no módulo para essas atividades recebem **+1 de vantagem**.\n\nAo utilizar um Medkit no módulo, o alvo recupera **+2 PV** além do valor normalmente restaurado.\n\n**Preço:** 1.000 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Incomum\n- Preço: 1.000 Ⱥ","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS","MÓDULOS BORAN"],"tipo_tabela":"Verbete sem tabela","campos":{"Raridade":"Incomum","Preço":"1.000 Ⱥ"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":null,"linhaBlocoId":"b8cbf705a97c4cfa9c10400762ac67a4","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"modulo_veicular","categoria_label":"Módulo Veicular","subtipo":null,"estatisticas":{"campos_tabela":{"Raridade":"Incomum","Preço":"1.000 Ⱥ"},"espacos_texto":null}},"id":"item:mobilidade_modulo_clinica","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b3c14fcc677e7ca5efced205ad83018d6824a948cc9e00c7223a75e87777f84e"},{"content_type":"item","slug":"mobilidade_modulo_gerador","payload":{"id":"mobilidade_modulo_gerador","slug":"mobilidade_modulo_gerador","nome":"MÓDULO-GERADOR","raridade":"incomum","raridade_label":"Incomum","preco":600,"preco_texto":"600 Ⱥ","preco_qualificador":null,"descricao_curta":"*Módulo veicular · Incomum*","descricao_longa":"*Módulo veicular · Incomum*\n\nUm gerador rúnico de alta saída distribui energia por conexões internas e externas, permitindo que o veículo funcione como fonte móvel para ferramentas, terminais, iluminação e outras instalações.\n\n**Fonte externa:** enquanto o veículo estiver parado e funcionando, equipamentos conectados diretamente ao módulo podem permanecer ativos sem consumir cargas utilizadas exclusivamente para determinar sua duração de funcionamento.\n\nO módulo não restaura cargas já gastas nem substitui munições, consumíveis ou recursos utilizados para produzir efeitos.\n\n**Preço:** 600 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Incomum\n- Preço: 600 Ⱥ","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS","MÓDULOS BORAN"],"tipo_tabela":"Verbete sem tabela","campos":{"Raridade":"Incomum","Preço":"600 Ⱥ"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":null,"linhaBlocoId":"30a22dcbd35044c7a4a7bcd0a37be905","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"modulo_veicular","categoria_label":"Módulo Veicular","subtipo":null,"estatisticas":{"campos_tabela":{"Raridade":"Incomum","Preço":"600 Ⱥ"},"espacos_texto":null}},"id":"item:mobilidade_modulo_gerador","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"e4772d119e512850c1ce309bae9d163a919fd8e93415692db351d1950fb4dd71"},{"content_type":"item","slug":"mobilidade_modulo_oficina","payload":{"id":"mobilidade_modulo_oficina","slug":"mobilidade_modulo_oficina","nome":"MÓDULO-OFICINA","raridade":"incomum","raridade_label":"Incomum","preco":700,"preco_texto":"700 Ⱥ","preco_qualificador":null,"descricao_curta":"*Módulo veicular · Incomum*","descricao_longa":"*Módulo veicular · Incomum*\n\nBancadas retráteis, ferramentas pesadas, sistemas de diagnóstico, braços de sustentação e compartimentos para peças transformam a baia em uma oficina móvel.\n\n**Oficina móvel:** enquanto o veículo estiver parado, o módulo conta como uma oficina equipada para reparar, desmontar e modificar equipamentos, objetos, drones, robôs e veículos.\n\nTestes de **`Engenharia`** realizados no módulo para essas atividades recebem **+1 de vantagem**.\n\nAo utilizar um Kit de Reparo no módulo, restaure **+2 PD ou MIT** além do valor normalmente restaurado.\n\n**Preço:** 700 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Incomum\n- Preço: 700 Ⱥ","tags":["loja"],"dados_notion":{"pagina":"MOBILIDADE","secao":["VEÍCULOS","MÓDULOS BORAN"],"tipo_tabela":"Verbete sem tabela","campos":{"Raridade":"Incomum","Preço":"700 Ⱥ"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"ac80a136355282d08fbd01cb30610de4","paginaEditadaEm":"2026-10-10T22:09:00.000Z","tabelaBlocoId":null,"linhaBlocoId":"30dce4a2fc44409391c28c09075bfac6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"modulo_veicular","categoria_label":"Módulo Veicular","subtipo":null,"estatisticas":{"campos_tabela":{"Raridade":"Incomum","Preço":"700 Ⱥ"},"espacos_texto":null}},"id":"item:mobilidade_modulo_oficina","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"5deb2cdcf6ae45ef29311fa97f9b03d61efbe527866ed5c1f38b5c1fd43af7b0"},{"content_type":"item","slug":"trajes_daemon_i","payload":{"id":"trajes_daemon_i","slug":"trajes_daemon_i","nome":"Daemon I","raridade":"incomum","raridade_label":"Incomum","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"O Daemon I é o modelo leve da linha Daemon. Fibras condutoras percorrem o traje entre processadores instalados na coluna, cintura e antebraços e a interface sináptica usada pelo operador para acessar a Trama. Uma camada isolante envolve a cabeça e a coluna para filtrar retornos antes que alcancem diretamente o sistema nervoso.","descricao_longa":"*Incomum*\n\nO Daemon I é o modelo leve da linha Daemon. Fibras condutoras percorrem o traje entre processadores instalados na coluna, cintura e antebraços e a interface sináptica usada pelo operador para acessar a Trama. Uma camada isolante envolve a cabeça e a coluna para filtrar retornos antes que alcancem diretamente o sistema nervoso.\n\nA concentração dos componentes nessas regiões mantém o restante do traje fino o bastante para ser usado sob armaduras leves.\n\n**Overclock:** uma vez por rodada, antes de realizar um teste de **Protocolo** ou **Comando** durante uma Sessão, você pode gastar 1 RAM para receber **+1 de vantagem** nesse teste.\n\n**Isolamento neural:** enquanto estiver em uma Sessão, reduza em 1 qualquer perda de RAM ou dano psíquico causado a você por uma ação, entidade ou defesa hostil dentro da Trama. Essa redução não se aplica ao dano causado por **Desplugar**.\n\n**PD:** 10\n\n**Cobertura:** corpo inteiro\n\n**Compatibilidade de Armadura:** armaduras leves\n\n**Espaços:** 2\n\n**Preço:** 1.500 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Incomum\n- PD: 10\n- Compatibilidade: Armaduras leves\n- Espaços: 2\n- Preço (Ⱥ): 1.500","tags":["loja"],"dados_notion":{"pagina":"TRAJES","secao":[],"tipo_tabela":"Traje","campos":{"Traje":"Daemon I","Raridade":"Incomum","PD":"10","Compatibilidade":"Armaduras leves","Espaços":"2","Preço (Ⱥ)":"1.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355281a7a6d8d9cc819c7e5e","paginaEditadaEm":"2026-10-08T22:18:00.000Z","tabelaBlocoId":"0c9edf443d9d4f249d3334283253d6bf","linhaBlocoId":"2deb88d389674695abcd6673ea9c5193","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"traje","categoria_label":"Traje","subtipo":null,"estatisticas":{"campos_tabela":{"Traje":"Daemon I","Raridade":"Incomum","PD":"10","Compatibilidade":"Armaduras leves","Espaços":"2","Preço (Ⱥ)":"1.500"},"espacos_texto":"2","compatibilidade_armadura":["leve"]}},"id":"item:trajes_daemon_i","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"95033801d6bdf7e58e93dea0ff2b36caa6d3335c543d4c390d4f418ae020954f"},{"content_type":"item","slug":"trajes_daemon_ii","payload":{"id":"trajes_daemon_ii","slug":"trajes_daemon_ii","nome":"Daemon II","raridade":"raro","raridade_label":"Raro","preco":4000,"preco_texto":"4.000","preco_qualificador":null,"descricao_curta":"O Daemon II é o modelo distribuído da linha Daemon. Processadores e dissipadores ocupam o tronco, os braços e as pernas, ligados à interface sináptica por fibras condutoras incorporadas ao tecido. A carga de processamento é dividida entre esses componentes para evitar que um único núcleo concentre calor e retorno durante uma Sessão.","descricao_longa":"*Raro*\n\nO Daemon II é o modelo distribuído da linha Daemon. Processadores e dissipadores ocupam o tronco, os braços e as pernas, ligados à interface sináptica por fibras condutoras incorporadas ao tecido. A carga de processamento é dividida entre esses componentes para evitar que um único núcleo concentre calor e retorno durante uma Sessão.\n\nAo redor da cabeça e da coluna, uma camada isolante mais espessa reforça a filtragem dos sinais hostis que retornam pela conexão.\n\n**Overclock:** antes de realizar um teste de **Protocolo** ou **Comando** durante uma Sessão, você pode gastar 1 RAM para receber **+1 de vantagem** nesse teste. Apenas 1 RAM pode ser gasta dessa forma por teste.\n\n**Isolamento neural:** enquanto estiver em uma Sessão, reduza em 2 qualquer perda de RAM ou dano psíquico causado a você por uma ação, entidade ou defesa hostil dentro da Trama. Essa redução não se aplica ao dano causado por **Desplugar**.\n\n**PD:** 15\n\n**Cobertura:** corpo inteiro\n\n**Compatibilidade de Armadura:** armaduras leves\n\n**Espaços:** 3\n\n**Preço:** 4.000 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Raro\n- PD: 15\n- Compatibilidade: Armaduras leves\n- Espaços: 3\n- Preço (Ⱥ): 4.000","tags":["loja"],"dados_notion":{"pagina":"TRAJES","secao":[],"tipo_tabela":"Traje","campos":{"Traje":"Daemon II","Raridade":"Raro","PD":"15","Compatibilidade":"Armaduras leves","Espaços":"3","Preço (Ⱥ)":"4.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355281a7a6d8d9cc819c7e5e","paginaEditadaEm":"2026-10-08T22:18:00.000Z","tabelaBlocoId":"0c9edf443d9d4f249d3334283253d6bf","linhaBlocoId":"e509d8ae4241480896280ff47e22ca00","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"traje","categoria_label":"Traje","subtipo":null,"estatisticas":{"campos_tabela":{"Traje":"Daemon II","Raridade":"Raro","PD":"15","Compatibilidade":"Armaduras leves","Espaços":"3","Preço (Ⱥ)":"4.000"},"espacos_texto":"3","compatibilidade_armadura":["leve"]}},"id":"item:trajes_daemon_ii","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"71f8a2abf84f1efe64be6fb4161fe41bf9f8874268321b578b5cfd7c35a022aa"},{"content_type":"item","slug":"trajes_daemon_iii","payload":{"id":"trajes_daemon_iii","slug":"trajes_daemon_iii","nome":"Daemon III","raridade":"muito_raro","raridade_label":"Muito Raro","preco":6000,"preco_texto":"6.000","preco_qualificador":null,"descricao_curta":"O Daemon III é o modelo integral da linha Daemon. Unidades de processamento, dissipadores e camadas de isolamento cobrem quase todo o corpo, ligadas à interface sináptica por uma malha condutora contínua. Os núcleos podem operar em paralelo e concentrar carga numa mesma operação, enquanto o revestimento ao redor da cabeça, coluna e nervos periféricos absorve parte do retorno hostil.","descricao_longa":"*Muito Raro*\n\nO Daemon III é o modelo integral da linha Daemon. Unidades de processamento, dissipadores e camadas de isolamento cobrem quase todo o corpo, ligadas à interface sináptica por uma malha condutora contínua. Os núcleos podem operar em paralelo e concentrar carga numa mesma operação, enquanto o revestimento ao redor da cabeça, coluna e nervos periféricos absorve parte do retorno hostil.\n\nO volume desses componentes ocupa o espaço que normalmente seria usado por uma armadura externa.\n\n**Overclock:** antes de realizar um teste de **Protocolo** ou **Comando** durante uma Sessão, você pode gastar até 2 RAM. Para cada 1 RAM gasta dessa forma, receba **+1 de vantagem** nesse teste, até **+2 de vantagem**.\n\n**Isolamento neural:** enquanto estiver em uma Sessão, reduza em 3 qualquer perda de RAM ou dano psíquico causado a você por uma ação, entidade ou defesa hostil dentro da Trama. Essa redução não se aplica ao dano causado por **Desplugar**.\n\n**PD:** 20\n\n**Cobertura:** corpo inteiro\n\n**Compatibilidade de Armadura:** nenhuma\n\n**Espaços:** 3\n\n**Preço:** 6.000 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Muito Raro\n- PD: 20\n- Compatibilidade: Nenhuma\n- Espaços: 3\n- Preço (Ⱥ): 6.000","tags":["loja"],"dados_notion":{"pagina":"TRAJES","secao":[],"tipo_tabela":"Traje","campos":{"Traje":"Daemon III","Raridade":"Muito Raro","PD":"20","Compatibilidade":"Nenhuma","Espaços":"3","Preço (Ⱥ)":"6.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355281a7a6d8d9cc819c7e5e","paginaEditadaEm":"2026-10-08T22:18:00.000Z","tabelaBlocoId":"0c9edf443d9d4f249d3334283253d6bf","linhaBlocoId":"376d1990a24f43fc9e46a639b7ad6e5b","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"traje","categoria_label":"Traje","subtipo":null,"estatisticas":{"campos_tabela":{"Traje":"Daemon III","Raridade":"Muito Raro","PD":"20","Compatibilidade":"Nenhuma","Espaços":"3","Preço (Ⱥ)":"6.000"},"espacos_texto":"3","compatibilidade_armadura":[]}},"id":"item:trajes_daemon_iii","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"bf9596e0ca5f0c4ba14085669d7de2c625b8e4643b66bf942c5bfc2aac06b7ac"},{"content_type":"item","slug":"trajes_eclipse","payload":{"id":"trajes_eclipse","slug":"trajes_eclipse","nome":"Eclipse","raridade":"muito_raro","raridade_label":"Muito Raro","preco":3000,"preco_texto":"3.000","preco_qualificador":null,"descricao_curta":"O Eclipse é um traje integral construído em camadas termorreguladoras, materiais de baixa emissão, filtros químicos e uma malha de isolamento eletromagnético. Juntas desacopladas e superfícies absorventes revestem os pontos de maior atrito para reduzir o ruído produzido pelo próprio equipamento durante o movimento.","descricao_longa":"*Muito Raro*\n\nO Eclipse é um traje integral construído em camadas termorreguladoras, materiais de baixa emissão, filtros químicos e uma malha de isolamento eletromagnético. Juntas desacopladas e superfícies absorventes revestem os pontos de maior atrito para reduzir o ruído produzido pelo próprio equipamento durante o movimento.\n\nEm conjunto, essas camadas abafam calor, odor, emissões eletromagnéticas e pequenos sons mecânicos sem alterar a aparência visual do usuário.\n\n**Supressão de assinatura:** quando uma criatura ou sistema tentar localizar ou rastrear você principalmente por calor, odor ou emissões eletromagnéticas, sofre **–2 de desvantagem** no teste.\n\nSe uma capacidade normalmente determinar sua posição automaticamente exclusivamente por uma dessas assinaturas, ela não o localiza automaticamente enquanto o Eclipse estiver funcionando. Em vez disso, o observador realiza um teste de **`Percepção`** contra sua **`Furtividade`**.\n\n**Amortecimento acústico:** criaturas sofrem **–1 de desvantagem** em testes de **`Percepção`** para localizar ou acompanhar você principalmente por sons discretos produzidos pelo movimento do Traje ou pelos equipamentos que estiver carregando.\n\nEsse efeito não reduz sons deliberados ou intensos, como fala, disparos, impactos, objetos quebrando ou interações ruidosas com o ambiente.\n\nQuando um mesmo teste utilizar diferentes formas de percepção afetadas pelo Eclipse, aplique apenas a maior desvantagem fornecida pelo Traje. O Eclipse não interfere com aparência visual, vibrações transmitidas por superfícies, pegadas, objetos deslocados ou outras alterações físicas produzidas pela passagem do usuário.\n\n**PD:** 15\n\n**Cobertura:** corpo inteiro\n\n**Compatibilidade de Armadura:** nenhuma\n\n**Espaços:** 2\n\n**Preço:** 3.000 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Muito Raro\n- PD: 15\n- Compatibilidade: Nenhuma\n- Espaços: 2\n- Preço (Ⱥ): 3.000","tags":["loja"],"dados_notion":{"pagina":"TRAJES","secao":[],"tipo_tabela":"Traje","campos":{"Traje":"Eclipse","Raridade":"Muito Raro","PD":"15","Compatibilidade":"Nenhuma","Espaços":"2","Preço (Ⱥ)":"3.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355281a7a6d8d9cc819c7e5e","paginaEditadaEm":"2026-10-08T22:18:00.000Z","tabelaBlocoId":"0c9edf443d9d4f249d3334283253d6bf","linhaBlocoId":"ca7df2d4dabb4ae3a4e5f02479a72fd9","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"traje","categoria_label":"Traje","subtipo":null,"estatisticas":{"campos_tabela":{"Traje":"Eclipse","Raridade":"Muito Raro","PD":"15","Compatibilidade":"Nenhuma","Espaços":"2","Preço (Ⱥ)":"3.000"},"espacos_texto":"2","compatibilidade_armadura":[]}},"id":"item:trajes_eclipse","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"861e860af49be6b301a2a42f5d2d64a5b0efcd45ca0677b773bce7804b91c347"},{"content_type":"item","slug":"trajes_parallax","payload":{"id":"trajes_parallax","slug":"trajes_parallax","nome":"Parallax","raridade":"muito_raro","raridade_label":"Muito Raro","preco":3000,"preco_texto":"3.000","preco_qualificador":null,"descricao_curta":"O Parallax é um traje integral coberto por matrizes ópticas e microprojetores distribuídos pela superfície. Durante o movimento, essas unidades projetam cópias sincronizadas do usuário em posições ligeiramente deslocadas, reproduzindo sua silhueta, postura e trajetória.","descricao_longa":"*Muito Raro*\n\nO Parallax é um traje integral coberto por matrizes ópticas e microprojetores distribuídos pela superfície. Durante o movimento, essas unidades projetam cópias sincronizadas do usuário em posições ligeiramente deslocadas, reproduzindo sua silhueta, postura e trajetória.\n\nAs projeções são formadas por luz e sinal externos ao corpo e aparecem para câmeras e outros sensores ópticos junto da imagem real do usuário.\n\n**Matriz de Ecos:** no início de cada cena, o Traje projeta 2 Ecos Holográficos. Enquanto possuir Ecos, ataques direcionados a você que dependam de visão ou sensores ópticos sofrem desvantagem conforme a quantidade de Ecos ativos:\n\n| **Ecos** | **Efeito** |\n| --- | --- |\n| 2 | **–2 de desvantagem** |\n| 1 | **–1 de desvantagem** |\n| 0 | Nenhum |\n\nQuando a desvantagem imposta pelos Ecos fizer um ataque que acertaria você falhar, remova 1 Eco.\n\nEfeitos em área e ataques capazes de determinar sua posição por um meio não reproduzido pelas projeções ignoram essa desvantagem.\n\nOs Ecos não ocupam espaço, não bloqueiam movimento, não podem realizar ações, não podem ser escolhidos como alvos independentes e não tornam você **`Oculto`**.\n\n**Recomposição:** duas vezes por cena, uma vez por rodada, depois de utilizar **Deslocar-se** e percorrer pelo menos 3 m, recupere 1 Eco, até o máximo de 2.\n\n**PD:** 15\n\n**Cobertura:** corpo inteiro\n\n**Compatibilidade de Armadura:** nenhuma\n\n**Espaços:** 3\n\n**Preço:** 3.000 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Muito Raro\n- PD: 15\n- Compatibilidade: Nenhuma\n- Espaços: 3\n- Preço (Ⱥ): 3.000","tags":["loja"],"dados_notion":{"pagina":"TRAJES","secao":[],"tipo_tabela":"Traje","campos":{"Traje":"Parallax","Raridade":"Muito Raro","PD":"15","Compatibilidade":"Nenhuma","Espaços":"3","Preço (Ⱥ)":"3.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355281a7a6d8d9cc819c7e5e","paginaEditadaEm":"2026-10-08T22:18:00.000Z","tabelaBlocoId":"0c9edf443d9d4f249d3334283253d6bf","linhaBlocoId":"d8e538c92fc84c199ee062ae3e078c71","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"traje","categoria_label":"Traje","subtipo":null,"estatisticas":{"campos_tabela":{"Traje":"Parallax","Raridade":"Muito Raro","PD":"15","Compatibilidade":"Nenhuma","Espaços":"3","Preço (Ⱥ)":"3.000"},"espacos_texto":"3","compatibilidade_armadura":[]}},"id":"item:trajes_parallax","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"95fac0aaa1ab46992bcebdd6c9c17a9fa59aa52b759464d7a3c02a2eeeec3aa7"},{"content_type":"item","slug":"trajes_trauma_suit","payload":{"id":"trajes_trauma_suit","slug":"trajes_trauma_suit","nome":"Trauma Suit","raridade":"raro","raridade_label":"Raro","preco":2000,"preco_texto":"2.000","preco_qualificador":null,"descricao_curta":"O Trauma Suit é um traje integral de intervenção clínica equipado com sensores biométricos, iluminação direcionada, manipuladores retráteis e compartimentos esterilizados distribuídos pelo tronco, cintura e membros. Durante um procedimento, os sensores acompanham o paciente enquanto os manipuladores mantêm luz, instrumentos e superfícies de apoio posicionados ao redor da área de trabalho.","descricao_longa":"*Raro*\n\nO Trauma Suit é um traje integral de intervenção clínica equipado com sensores biométricos, iluminação direcionada, manipuladores retráteis e compartimentos esterilizados distribuídos pelo tronco, cintura e membros. Durante um procedimento, os sensores acompanham o paciente enquanto os manipuladores mantêm luz, instrumentos e superfícies de apoio posicionados ao redor da área de trabalho.\n\nCompartimentos vedados mantêm suprimentos de Farmácia separados do restante do equipamento carregado pelo usuário e acessíveis durante a intervenção.\n\n**Suporte clínico:** ao realizar um teste de **`Medicina`**, se as condições do ambiente não estiverem impondo desvantagem ao procedimento, você recebe **+1 de vantagem**.\n\nSe o ambiente estiver impondo desvantagem ao teste, você não recebe essa vantagem, mas ignora até **–2 de desvantagem** causada especificamente pelas condições ambientais. Essa característica não reduz a Complexidade ou CD própria do procedimento.\n\n**Compartimentos clínicos:** o Trauma Suit possui 2 espaços exclusivos para itens de Farmácia. Itens armazenados nesses espaços são considerados **Equipados** em compartimentos próprios do Traje e não ocupam espaços da Mochila nem posições normais de Acesso Rápido.\n\nEsses itens continuam seguindo normalmente seus custos de PA, testes, usos e demais requisitos.\n\n**PD:** 10\n\n**Cobertura:** corpo inteiro\n\n**Compatibilidade de Armadura:** armaduras leves\n\n**Espaços:** 3\n\n**Preço:** 2.000 Ⱥ\n\nDados da lista de mercadorias:\n- Raridade: Raro\n- PD: 10\n- Compatibilidade: Armaduras leves\n- Espaços: 3\n- Preço (Ⱥ): 2.000","tags":["loja"],"dados_notion":{"pagina":"TRAJES","secao":[],"tipo_tabela":"Traje","campos":{"Traje":"Trauma Suit","Raridade":"Raro","PD":"10","Compatibilidade":"Armaduras leves","Espaços":"3","Preço (Ⱥ)":"2.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3f00a136355281a7a6d8d9cc819c7e5e","paginaEditadaEm":"2026-10-08T22:18:00.000Z","tabelaBlocoId":"0c9edf443d9d4f249d3334283253d6bf","linhaBlocoId":"1036de7b55984fe6ac2059e7ab9e87f4","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"traje","categoria_label":"Traje","subtipo":null,"estatisticas":{"campos_tabela":{"Traje":"Trauma Suit","Raridade":"Raro","PD":"10","Compatibilidade":"Armaduras leves","Espaços":"3","Preço (Ⱥ)":"2.000"},"espacos_texto":"3","compatibilidade_armadura":["leve"]}},"id":"item:trajes_trauma_suit","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9e726fc6475e3b72a50ac196ae37bb73a95d34faf8e92ac455fee03c53918f8e"},{"content_type":"item","slug":"vertinas_manta","payload":{"id":"vertinas_manta","slug":"vertinas_manta","nome":"Manta","raridade":"incomum","raridade_label":"Incomum","preco":50,"preco_texto":"50","preco_qualificador":null,"descricao_curta":"Substitui a emoção atual por uma artificial específica.","descricao_longa":"*Incomum*\n\nManta é uma vertina cognitiva altamente viciante, distribuída em diferentes variantes. Cada metal corresponde a uma emoção artificial, que substitui por completo a emoção real do usuário enquanto o efeito durar. Muito utilizada em redes clandestinas e ambientes de manipulação psíquica, altera reações sociais, bloqueia empatia genuína e pode tornar o usuário indiferente a estímulos externos.\n\nO consumo frequente de Manta leva à dependência severa, dessensibilização emocional e alterações permanentes na cognição do usuário.\n\n| **Metal** | **Emoção** |\n| --- | --- |\n| Cobre | Alegria |\n| Chumbo | Tristeza |\n| Mercúrio | Desejo |\n| Ferro | Raiva |\n| Ouro | Euforia |\n\n- **Efeito: **ao consumir uma dose, o usuário passa a sentir apenas a emoção artificial. O efeito permanece por 30 minutos. Enquanto sob efeito, sofre penalidade em testes sociais ligados à emoção real (–2) e bônus em ações motivadas pela emoção artificial (+2), a critério do narrador.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 50\n\nDados da lista de mercadorias:\n- Efeito: Substitui a emoção atual por uma artificial específica.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 50","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Manta","Efeito":"Substitui a emoção atual por uma artificial específica.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"50"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"238831ccf25840dba18539922c93d377","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Manta","Efeito":"Substitui a emoção atual por uma artificial específica.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"50"},"espacos_texto":"1"}},"id":"item:vertinas_manta","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"f45c95292c818cbc472aa9f623ea35f12764f62fde08e745eaf6bbdae2ae8beb"},{"content_type":"item","slug":"vertinas_beijo_de_bruxa","payload":{"id":"vertinas_beijo_de_bruxa","slug":"vertinas_beijo_de_bruxa","nome":"Beijo de bruxa","raridade":"incomum","raridade_label":"Incomum","preco":100,"preco_texto":"100","preco_qualificador":null,"descricao_curta":"Por 1 hora, todos os testes de conjuração recebem +1 de vantagem.","descricao_longa":"*Incomum*\n\nBastante procurada por magistas refratários, essa mistura provoca uma onda quente que percorre o corpo logo nos primeiros segundos. O foco se estreita, a mente fica aguda, e o fluxo de mana responde com facilidade. Por alguns minutos, conjurar parece simples e irresistível, como se toda resistência interna sumisse. Porém, quando o efeito passa, bate uma fadiga pesada e a sensação de estar no limite, com alto risco de desmaio se o uso virar rotina.\n\n- **Efeito:** por 1 hora, concede +1 em todos os testes de conjuração.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 100\n\nDados da lista de mercadorias:\n- Efeito: Por 1 hora, todos os testes de conjuração recebem +1 de vantagem.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 100","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Beijo de bruxa","Efeito":"Por 1 hora, todos os testes de conjuração recebem +1 de vantagem.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"100"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"fd793f7491c1497498d022972b51b332","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Beijo de bruxa","Efeito":"Por 1 hora, todos os testes de conjuração recebem +1 de vantagem.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"100"},"espacos_texto":"1"}},"id":"item:vertinas_beijo_de_bruxa","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"38872f4850633a6336588b715e77a3190dcee1cfd1139c3709c7bb4700502304"},{"content_type":"item","slug":"vertinas_lotus","payload":{"id":"vertinas_lotus","slug":"vertinas_lotus","nome":"Lótus","raridade":"incomum","raridade_label":"Incomum","preco":250,"preco_texto":"250","preco_qualificador":null,"descricao_curta":"Por 1 hora, magias de Ataque causam +1d6 de dano.","descricao_longa":"*Incomum*\n\nEssência extraída de flores arcanossaturadas de Zonas Anômalas, a Lótus acelera os impulsos arcanos ligados ao ataque. O magista sente um calor inexplicável nas mãos e a energia das magias se projeta com força multiplicada.\n\n- **Efeito:** por 1 hora, magias de **`Ataque`** causam +1d6 de dano.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 250\n\nDados da lista de mercadorias:\n- Efeito: Por 1 hora, magias de Ataque causam +1d6 de dano.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 250","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Lótus","Efeito":"Por 1 hora, magias de Ataque causam +1d6 de dano.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"97496f6f1fcd461491a88b614cac095e","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Lótus","Efeito":"Por 1 hora, magias de Ataque causam +1d6 de dano.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"espacos_texto":"1"}},"id":"item:vertinas_lotus","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"79896321dff460ac16d8767f34dd165de5117f8db37719d67933b970d3da512b"},{"content_type":"item","slug":"vertinas_zenite","payload":{"id":"vertinas_zenite","slug":"vertinas_zenite","nome":"Zênite","raridade":"incomum","raridade_label":"Incomum","preco":250,"preco_texto":"250","preco_qualificador":null,"descricao_curta":"Por 1 hora, magias de Controle têm alcance e áreas ampliados em 50%.","descricao_longa":"*Incomum*\n\nUm pó translúcido de origem sintética, dissolvido ou inalado pouco antes de manipulações mais elaboradas. Ao ingerir, o usuário sente a percepção se expandir e as fronteiras do próprio alcance ficarem mais fluidas.\n\n- **Efeito:** por 1 hora, magias de **`Controle`** têm alcance e áreas ampliados em 50%.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 250\n\nDados da lista de mercadorias:\n- Efeito: Por 1 hora, magias de Controle têm alcance e áreas ampliados em 50%.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 250","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Zênite","Efeito":"Por 1 hora, magias de Controle têm alcance e áreas ampliados em 50%.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"3ff57098489d4082b39895ce4aa030ea","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Zênite","Efeito":"Por 1 hora, magias de Controle têm alcance e áreas ampliados em 50%.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"espacos_texto":"1"}},"id":"item:vertinas_zenite","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b03f6ac1c059fb2d51cec0a1bace592133da01e4891c92f274cabcd51e2113b5"},{"content_type":"item","slug":"vertinas_relicario","payload":{"id":"vertinas_relicario","slug":"vertinas_relicario","nome":"Relicário","raridade":"incomum","raridade_label":"Incomum","preco":250,"preco_texto":"250","preco_qualificador":null,"descricao_curta":"Por 1 hora, magias de Suporte beneficiam um alvo adicional.","descricao_longa":"*Incomum*\n\nUm líquido levemente dourado, com sabor amargo e notas de raiz. O usuário sente uma estabilidade estranha ao canalizar energia de suporte, permitindo que cada feitiço beneficie um aliado a mais do que o normal.\n\n- **Efeito:** por 1 hora, magias de **`Suporte`** beneficiam um alvo adicional dentro do alcance.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 250\n\nDados da lista de mercadorias:\n- Efeito: Por 1 hora, magias de Suporte beneficiam um alvo adicional.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 250","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Relicário","Efeito":"Por 1 hora, magias de Suporte beneficiam um alvo adicional.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"95bc435a71034401968c3d87b7d83574","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Relicário","Efeito":"Por 1 hora, magias de Suporte beneficiam um alvo adicional.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"espacos_texto":"1"}},"id":"item:vertinas_relicario","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"1095b88f560946be4825b4f51354851d2da94cd7b9677edda1a13c8fa90cd900"},{"content_type":"item","slug":"vertinas_raio_negro","payload":{"id":"vertinas_raio_negro","slug":"vertinas_raio_negro","nome":"Raio negro","raridade":"incomum","raridade_label":"Incomum","preco":250,"preco_texto":"250","preco_qualificador":null,"descricao_curta":"Por 1 hora, magias de Mobilidade permitem percorrer 50% mais distância.","descricao_longa":"*Incomum*\n\nAmpola de vidro escurecido, guardando uma solução pulsante. Raio negro faz o corpo pulsar com energia inquieta, tornando o movimento ágil e instintivo. O usuário sente-se mais leve, capaz de atravessar distâncias maiores com facilidade.\n\n- **Efeito:** por 1 hora, magias de **`Mobilidade`** permitem percorrer 50% mais distância.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 250\n\nDados da lista de mercadorias:\n- Efeito: Por 1 hora, magias de Mobilidade permitem percorrer 50% mais distância.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 250","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Raio negro","Efeito":"Por 1 hora, magias de Mobilidade permitem percorrer 50% mais distância.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"e53020f613cd4da6bddb9a6d7e21b9a8","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Raio negro","Efeito":"Por 1 hora, magias de Mobilidade permitem percorrer 50% mais distância.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"250"},"espacos_texto":"1"}},"id":"item:vertinas_raio_negro","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"8a18d10ae50edd464a598f923c626b7ef15cb2aa407b535e1a4bce08d1ef3482"},{"content_type":"item","slug":"vertinas_marola","payload":{"id":"vertinas_marola","slug":"vertinas_marola","nome":"Marola","raridade":"incomum","raridade_label":"Incomum","preco":300,"preco_texto":"300","preco_qualificador":null,"descricao_curta":"Ganha 5 de mana temporária ao final de um descanso curto. 3 Usos.","descricao_longa":"*Incomum*\n\nPó cristalino de tom azulado. Pode ser inalado puro ou queimado em cachimbos improvisados, soltando fumaça espessa e azul que gruda nas roupas e arranha os pulmões. É comum ver refratários encostados em becos ou bares subterrâneos tragando a névoa azul, que deixa o ar turvo e os olhos vidrados.\n\n- **Efeito:** ao final de um descanso curto, o usuário ganha 5 de mana temporária. O valor é sempre 5 por personagem, mesmo que vários usos tenham sido gastos em um mesmo descanso. Possui 3 Usos.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 300\n\nDados da lista de mercadorias:\n- Efeito: Ganha 5 de mana temporária ao final de um descanso curto. 3 Usos.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 300","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Marola","Efeito":"Ganha 5 de mana temporária ao final de um descanso curto. 3 Usos.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"d2d54aeefcd0477fa37e8e83d3ec0020","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Marola","Efeito":"Ganha 5 de mana temporária ao final de um descanso curto. 3 Usos.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"300"},"espacos_texto":"1"}},"id":"item:vertinas_marola","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"a6aa29fd22a606deaf1956683e297fb5a253f310eac2d8123aea085db7edd83b"},{"content_type":"item","slug":"vertinas_azulzinha","payload":{"id":"vertinas_azulzinha","slug":"vertinas_azulzinha","nome":"Azulzinha","raridade":"incomum","raridade_label":"Incomum","preco":400,"preco_texto":"400","preco_qualificador":null,"descricao_curta":"Recupera imediatamente 2d6 pontos de mana.","descricao_longa":"Incomum\n\nAmpola de mana sintética, relativamente popular nos mercados noturnos. Ao injetar, o corpo é tomado por uma onda de energia crua, intensa e elétrica, como se cada célula acordasse ao mesmo tempo. O usuário sente o fluxo arcano atravessar músculos e veias, clareando os sentidos e acelerando o pensamento, mas junto vem uma pressão incômoda na cabeça e nas juntas. Pouco depois, o efeito desaparece de repente, deixando um cansaço pesado e uma sensação de vazio interno.\n\n- **Efeito:** recupera instantaneamente 2d6 pontos de mana.\n\n- **Espaços:** 1\n\n- **Preço:** Ⱥ 400\n\n[Imagem no Notion]\n\nDados da lista de mercadorias:\n- Efeito: Recupera imediatamente 2d6 pontos de mana.\n- Raridade: Incomum\n- Espaços: 1\n- Preço (Ⱥ): 400","tags":["loja"],"dados_notion":{"pagina":"VERTINAS","secao":[],"tipo_tabela":"Vertina","campos":{"Vertina":"Azulzinha","Efeito":"Recupera imediatamente 2d6 pontos de mana.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"400"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"2200a136355282d5b49901ab965a0da0","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"0533697da8974ebd8d7b5a1276b806fe","linhaBlocoId":"c2f2eb73427447219ceb9547ebdf0b45","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"vertina","categoria_label":"Vertina","subtipo":null,"estatisticas":{"campos_tabela":{"Vertina":"Azulzinha","Efeito":"Recupera imediatamente 2d6 pontos de mana.","Raridade":"Incomum","Espaços":"1","Preço (Ⱥ)":"400"},"espacos_texto":"1"}},"id":"item:vertinas_azulzinha","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"27a74e652195e38f027ef2f9ea360f779c144e19f5438c2ffc675cbcafb743bd"},{"content_type":"rune","slug":"armas_retratil","payload":{"id":"armas_retratil","slug":"armas_retratil","nome":"Retrátil","raridade":"comum","raridade_label":"Comum","preco":500,"preco_texto":"500","preco_qualificador":null,"descricao_curta":"A arma pode ser retraída e ocultada.","descricao_longa":"*Comum*\n\nSímbolos de Material comprimem a estrutura do item em placas móveis, permitindo recolher a lâmina ou concentrar o bastão em um formato compacto. Uma vez retraída, a arma pode ser ocultada com facilidade.\n\n- **Efeito:** a arma pode ser retraída em formato compacto, tornando-se **ocultável**. É possível expandir ou retrair a arma com a ação **Interagir ****`1 PA`**.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 500\n\nDados da lista de mercadorias:\n- Efeito: A arma pode ser retraída e ocultada.\n- Raridade: Comum\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 500\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Retrátil","Efeito":"A arma pode ser retraída e ocultada.","Raridade":"Comum","Espaços":"1 (avulsa)","Preço (Ⱥ)":"500","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"47eb39937e8d43b78dec2628d1fb82f6","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_retratil","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"93d906c13529e71f89b6c247d1d9844b2f51c109afb8fcac87358e57f112c444"},{"content_type":"rune","slug":"armas_impeto","payload":{"id":"armas_impeto","slug":"armas_impeto","nome":"Ímpeto","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"Se mover 6 m antes de atacar, causa +1d4 de dano.","descricao_longa":"*Incomum*\n\nCanaliza energia cinética pelas inscrições, acumulando força em cada passo. Quando liberada, a runa transfere esse ímpeto diretamente para o golpe final, transformando deslocamento em impacto.\n\n- **Efeito:** se o usuário se mover ao menos 6 metros antes de atacar, a arma causa **+1d4 de dano** nesse golpe.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.000\n\nDados da lista de mercadorias:\n- Efeito: Se mover 6 m antes de atacar, causa +1d4 de dano.\n- Raridade: Incomum\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.000\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Ímpeto","Efeito":"Se mover 6 m antes de atacar, causa +1d4 de dano.","Raridade":"Incomum","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.000","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"baed96cb4db14eb4bb3ffeec49805263","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_impeto","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"a87d532ae20588aa2a1c18fef73a1d65b59721c880f1166d4e347a77442b9aa4"},{"content_type":"rune","slug":"armas_armas_corpo_a_corpo_silenciadora","payload":{"id":"armas_armas_corpo_a_corpo_silenciadora","slug":"armas_armas_corpo_a_corpo_silenciadora","nome":"Silenciadora","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"Ataques com a arma não emitem som algum.","descricao_longa":"*Incomum*\n\nAs linhas arcanas abafam vibrações e reverberações, como se o espaço ao redor da arma se fechasse em silêncio absoluto. O som do corte, do impacto ou até do ar sendo rasgado desaparece por completo.\n\n- **Efeito:** ataques com essa arma não produzem ruído audível.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.000\n\nDados da lista de mercadorias:\n- Efeito: Ataques com a arma não emitem som algum.\n- Raridade: Incomum\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.000\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Silenciadora","Efeito":"Ataques com a arma não emitem som algum.","Raridade":"Incomum","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.000","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"4a742116c46e40dc973425a33063afc5","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_armas_corpo_a_corpo_silenciadora","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"818556064799bc4941104cd7915a4a8f0254d1e980b8a7fa35fc3795fad09391"},{"content_type":"rune","slug":"armas_finta","payload":{"id":"armas_finta","slug":"armas_finta","nome":"Finta","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"Permite Fintar como parte da ação Atacar.","descricao_longa":"*Incomum*\n\nO traçado rúnico altera o peso da arma de forma sutil, facilitando mudanças bruscas de direção. Essa oscilação quase imperceptível engana o olhar do inimigo e dá vantagem em manobras enganosas.\n\n- **Efeito: **o usuário pode realizar **Finta** como parte da própria ação **Atacar**, sem custo extra.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.000\n\nDados da lista de mercadorias:\n- Efeito: Permite Fintar como parte da ação Atacar.\n- Raridade: Incomum\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.000\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Finta","Efeito":"Permite Fintar como parte da ação Atacar.","Raridade":"Incomum","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.000","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"398cb0e380214cf49955d2976c848f08","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_finta","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"e72b497f2e97a6b95e6c24ef6638152f3de51b2ecd32f88b36006bd772e10e46"},{"content_type":"rune","slug":"armas_clarao","payload":{"id":"armas_clarao","slug":"armas_clarao","nome":"Clarão","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"ao acertar, emite luz que ofusca inimigos em 2 m.","descricao_longa":"*Incomum*\n\nSímbolos luminosos gravados no metal armazenam radiação latente, liberada em um único estalo quando acionada. O clarão rompe a escuridão e desorienta qualquer um ao redor, confundindo a visão no calor da luta.\n\n- **Efeito:** por 1 PA, após acertar, a arma emite luz intensa; inimigos em até 2 metros devem fazer teste de **Desviar**, CD 7 ou ficam **`Ofuscados`** até o fim do próximo turno deles.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.000\n\nDados da lista de mercadorias:\n- Efeito: ao acertar, emite luz que ofusca inimigos em 2 m.\n- Raridade: Incomum\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.000\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Clarão","Efeito":"ao acertar, emite luz que ofusca inimigos em 2 m.","Raridade":"Incomum","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.000","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"fdd73a88f0d645cbaebba70f08bae770","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_clarao","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b38fea483fab2f5be00c20c27b6037e13593c9a19c9019078c4a016befbcf7d2"},{"content_type":"rune","slug":"armas_armas_corpo_a_corpo_flamejante","payload":{"id":"armas_armas_corpo_a_corpo_flamejante","slug":"armas_armas_corpo_a_corpo_flamejante","nome":"Flamejante","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"+1d4 ígneo, aplica Queimando em crítico.","descricao_longa":"*Raro*\n\nGravuras ígneas despertam labaredas que percorrem toda a arma quando ativadas. O calor transforma cada ataque em um arco incandescente, capaz de atear fogo e queimar mesmo através de armaduras.\n\n- **Efeito:** a arma causa **+1d4 de dano ígneo** e aplica **`Queimando`** em sucesso crítico. A runa possui 2 usos diários e recupera todos os usos em um descanso longo. É possível ativá-la ou desativá-la com a ação **Interagir ****`1 PA`**.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.500\n\nDados da lista de mercadorias:\n- Efeito: +1d4 ígneo, aplica Queimando em crítico.\n- Raridade: Raro\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.500\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Flamejante","Efeito":"+1d4 ígneo, aplica Queimando em crítico.","Raridade":"Raro","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.500","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"d9d4234e578242ce9cccccd3f0e8da40","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_armas_corpo_a_corpo_flamejante","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"2a97c61c4ebd800dc376b7074efad759f8f414072bfaa73c9c2d47f495acafa0"},{"content_type":"rune","slug":"armas_eletrizante","payload":{"id":"armas_eletrizante","slug":"armas_eletrizante","nome":"Eletrizante","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"+1d4 elétrico, aplica Atordoado em crítico.","descricao_longa":"*Raro*\n\nTraços energéticos correm como veios de relâmpago sobre o metal. Uma vez despertados, envolvem o usuário em faíscas que percorrem cada golpe, sobrecarregando nervos e circuitos.\n\n- **Efeito:** a arma causa **+1d4 de dano elétrico** e aplica **`Atordoado`** em sucesso crítico. A runa possui 2 usos diários e recupera todos os usos em um descanso longo. É possível ativá-la ou desativá-la com a ação **Interagir ****`1 PA`**.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.500\n\nDados da lista de mercadorias:\n- Efeito: +1d4 elétrico, aplica Atordoado em crítico.\n- Raridade: Raro\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.500\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Eletrizante","Efeito":"+1d4 elétrico, aplica Atordoado em crítico.","Raridade":"Raro","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.500","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"dedaf4e5c7aa4b8ea034fd41a89f75b3","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_eletrizante","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"c66480727d2ba748d60d166839aad4534ba2393974f44f1bc8fac3eaff068be0"},{"content_type":"rune","slug":"armas_armas_corpo_a_corpo_toxica_137c82","payload":{"id":"armas_armas_corpo_a_corpo_toxica_137c82","slug":"armas_armas_corpo_a_corpo_toxica_137c82","nome":"Tóxica","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"Atingidos podem ficar Envenenados.","descricao_longa":"*Raro*\n\nLinhas esverdeadas percorrem a lâmina, liberando toxinas sutis sempre que a arma corta carne. O veneno não mata de imediato, mas enfraquece músculos e atrapalha reflexos, corroendo lentamente a resistência do alvo.\n\n- **Efeito:** a cada acerto, o alvo deve fazer um teste de **`Vigor`**, CD 7. Em falha, fica **`Envenenado`**.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.500\n\nDados da lista de mercadorias:\n- Efeito: Atingidos podem ficar Envenenados.\n- Raridade: Raro\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.500\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Tóxica","Efeito":"Atingidos podem ficar Envenenados.","Raridade":"Raro","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.500","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"5cbc2815911c41668e23fb6fa4cd59ea","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_armas_corpo_a_corpo_toxica_137c82","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"c13e064cdb0700ba825f2d4fb536a26b6a9198fe67b9b0b159ffaac22585de5e"},{"content_type":"rune","slug":"armas_ruina","payload":{"id":"armas_ruina","slug":"armas_ruina","nome":"Ruína","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"Alvos atingidos não podem recuperar PV por 1 rodada.","descricao_longa":"*Raro*\n\nRunas corrosivas se acendem no momento do golpe, impregnando o alvo com energia entrópica. O corpo se fecha à cura, rejeitando tanto magia quanto tratamento comum até a marca rúnica se dissipar.\n\n- **Efeito:** inimigos atingidos não podem recuperar PV por 1 rodada.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.600\n\nDados da lista de mercadorias:\n- Efeito: Alvos atingidos não podem recuperar PV por 1 rodada.\n- Raridade: Raro\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.500\n- Aplicação: Armas brancas","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS BRANCAS"],"tipo_tabela":"Runa","campos":{"Runa":"Ruína","Efeito":"Alvos atingidos não podem recuperar PV por 1 rodada.","Raridade":"Raro","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.500","Aplicação":"Armas brancas"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"a943c9afde68420d969102f4af946d23","linhaBlocoId":"e9cafa4ce9224a86a5dbb7a8eb4bea23","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"corpo_a_corpo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_ruina","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"1bef794efe5a5db39ceeaf45e791854f7b9de950f16fc1c19d4c7e5fe4fede30"},{"content_type":"rune","slu