.2.0","payload_hash":"da24e131844cc4ce3488385ab30edc7346b59e27a0c5290efd34b9626f56b7ed"},{"content_type":"rune","slug":"armas_rastreadora","payload":{"id":"armas_rastreadora","slug":"armas_rastreadora","nome":"Rastreadora","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"Permite seguir o alvo atingido até o fim da cena.","descricao_longa":"*Incomum*\n\nSímbolos sensoriais marcam o alvo atingido com energia rúnica rastreável, visível apenas para usuários equipados com *Óptica Rúnica e *sintonizados com a runa. Mesmo em fuga, multidão ou cobertura, a posição do alvo fica destacada no campo de visão do atirador.\n\n- **Efeito:** o usuário consegue seguir e identificar o alvo atingido, mesmo que ele tente se ocultar ou se misture ao ambiente. Dura 1 hora.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.000\n\nDados da lista de mercadorias:\n- Efeito: Permite seguir o alvo atingido até o fim da cena.\n- Raridade: Incomum\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.000\n- Aplicação: Armas de fogo","tags":["loja"],"dados_notion":{"pagina":"ARMAS","secao":["RUNAS","RUNAS PARA ARMAS DE FOGO"],"tipo_tabela":"Runa","campos":{"Runa":"Rastreadora","Efeito":"Permite seguir o alvo atingido até o fim da cena.","Raridade":"Incomum","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.000","Aplicação":"Armas de fogo"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"9690a136355283c59bd8813acc4e4935","paginaEditadaEm":"2026-10-11T01:57:00.000Z","tabelaBlocoId":"076b28dfd8894a1c8137f278b0e4e761","linhaBlocoId":"aa704edb61194114996a59f8fcf44039","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["arma"],"restricao_subtipo":"fogo","custo_integridade":0,"estatisticas":{}},"id":"rune:armas_rastreadora","source_pack_id"