7ac438f76174c055cd46e54cbe339076fab77c9677fe3c26503448604b2"},{"content_type":"rune","slug":"drones_e_robos_interferencia","payload":{"id":"drones_e_robos_interferencia","slug":"drones_e_robos_interferencia","nome":"Interferência","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"1.000","preco_qualificador":null,"descricao_curta":"Bloqueia sinais em 10 m por 1 minuto.","descricao_longa":"*Incomum*\n\nPulsos tecnomágicos bloqueiam sinais e dificultam rastreamento.\n\n- **Efeito:** pode, por  **`1 PA`**** **(do operador, no caso de drones, ou do próprio robô), bloquear todos os rastreadores e transmissões em um raio de 10 m por 1 minuto.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.000\n\nDados da lista de mercadorias:\n- Efeito: Bloqueia sinais em 10 m por 1 minuto.\n- Raridade: Incomum\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.000","tags":["loja"],"dados_notion":{"pagina":"DRONES E ROBÔS","secao":["RUNAS"],"tipo_tabela":"Runa","campos":{"Runa":"Interferência","Efeito":"Bloqueia sinais em 10 m por 1 minuto.","Raridade":"Incomum","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"7a00a13635528396b33501c34c719d2a","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"792f53090323408c946846339f5edbf0","linhaBlocoId":"0e46a07f55fe42a6b55d8d25d85d2aa9","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["drone","robo"],"restricao_subtipo":null,"custo_integridade":0,"estatisticas":{}},"id":"rune:drones_e_robos_interferencia","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"368de9ac500262bc892186ce9b40bb0f9e0c807b210f260f2c659b87c3f4083f"},{"content_type":"rune","slug":"drones_e_robos_energia","payload":{"id":"drones_e_robos_energia","slug":"drones_e_robos_energia","nome":"Energia","raridade":"raro","raridade_label":"Raro","preco":1500,"preco_texto":"1.500","preco_qualificador":null,"descricao_curta":"1 vez por cena, pode gastar 1 PA extra.","descricao_longa":"*Raro*\n\nInscrições energéticas otimizam os circuitos, liberando energia extra em momentos críticos.\n\n- **Efeito:** 1 vez por cena, pode gastar **`1 PA`** adicional, mesmo que já tenha atingido o limite no turno.\n\n- **Espaços:** 1 (avulsa)\n\n- **Preço:** Ⱥ 1.500\n\nDados da lista de mercadorias:\n- Efeito: 1 vez por cena, pode gastar 1 PA extra.\n- Raridade: Raro\n- Espaços: 1 (avulsa)\n- Preço (Ⱥ): 1.500","tags":["loja"],"dados_notion":{"pagina":"DRONES E ROBÔS","secao":["RUNAS"],"tipo_tabela":"Runa","campos":{"Runa":"Energia","Efeito":"1 vez por cena, pode gastar 1 PA extra.","Raridade":"Raro","Espaços":"1 (avulsa)","Preço (Ⱥ)":"1.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"7a00a13635528396b33501c34c719d2a","paginaEditadaEm":"2026-10-08T22:19:00.000Z","tabelaBlocoId":"792f53090323408c946846339f5edbf0","linhaBlocoId":"255f1530e9fb4935a9e42e4258425075","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"runa","categoria_label":"Runa","slots_possiveis":["drone","robo"],"restricao_subtipo":null,"custo_integridade":0,"estatisticas":{}},"id":"rune:drones_e_robos_energia","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"dd52a27af3afa26e3c5c2746006c104beec11aef166e932215025be6dc23a105"},{"content_type":"escalpo","slug":"escalpos_ouvidos_de_cacador","payload":{"id":"escalpos_ouvidos_de_cacador","slug":"escalpos_ouvidos_de_cacador","nome":"Ouvidos de Caçador","raridade":"incomum","raridade_label":"Incomum","preco":1200,"preco_texto":"Ⱥ 1.200","preco_qualificador":null,"descricao_curta":"Isolam fontes sonoras e facilitam distinguir ou acompanhar sons específicos.","descricao_longa":"---\n\n*Incomum*\n\nO usuário pode isolar uma fonte sonora que consiga ouvir, reduzindo ruídos concorrentes a um murmúrio. Recebe +1 de vantagem em testes de **`Percepção`** para distinguir ou acompanhar sons específicos.\n\nPossuem 2 espaços para módulos de Ouvidos de Caçador.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 1.200\n\n**Integridade:** –1\n\n### MÓDULOS DE OUVIDOS DE CAÇADOR\n\n---\n\n#### CARTOGRAFIA ACÚSTICA\n\n#### ESCUTA AMPLIADA\n\n#### RASTREADOR SONORO\n\nDados da lista de mercadorias:\n- Resumo: Isolam fontes sonoras e facilitam distinguir ou acompanhar sons específicos.\n- Raridade: Incomum\n- Espaços: 1\n- Preço: Ⱥ 1.200","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS AUDITIVOS"],"tipo_tabela":"Nome","campos":{"Nome":"Ouvidos de Caçador","Resumo":"Isolam fontes sonoras e facilitam distinguir ou acompanhar sons específicos.","Raridade":"Incomum","Espaços":"1","Preço":"Ⱥ 1.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"8c9e2de85ac3414cb6369fc6dc96d2b2","linhaBlocoId":"6464711d41fe4b309aaefa1e2d2bd99e","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"auditivos","categoria_label":"auditivos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_ouvidos_de_cacador","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"5461d562426d79e1cef5313f2be1223e29e8fa4944077ddb9448078754a21fe6"},{"content_type":"escalpo","slug":"escalpos_transceptor_coclear","payload":{"id":"escalpos_transceptor_coclear","slug":"escalpos_transceptor_coclear","nome":"Transceptor Coclear","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"Ⱥ 1.000","preco_qualificador":null,"descricao_curta":"Recebe áudio digital e transmite a voz por comandos neurais a até 20 m.","descricao_longa":"---\n\n*Incomum*\n\nO implante recebe sons digitais diretamente pelo sistema auditivo e transmite a voz do usuário por comandos neurais, sem fala audível. Ele se comunica com dispositivos conectados ao ID sináptico a até 20 m.\n\nPossui 2 espaços para módulos de Transceptor Coclear.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 1.000\n\n**Integridade:** –1\n\n### MÓDULOS DO TRANSCEPTOR COCLEAR\n\n---\n\n#### CANAL CRIPTOGRAFADO\n\n#### GRAVADOR DE ÁUDIO\n\n#### VARREDURA DE FREQUÊNCIA\n\nDados da lista de mercadorias:\n- Resumo: Recebe áudio digital e transmite a voz por comandos neurais a até 20 m.\n- Raridade: Incomum\n- Espaços: 1\n- Preço: Ⱥ 1.000","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS AUDITIVOS"],"tipo_tabela":"Nome","campos":{"Nome":"Transceptor Coclear","Resumo":"Recebe áudio digital e transmite a voz por comandos neurais a até 20 m.","Raridade":"Incomum","Espaços":"1","Preço":"Ⱥ 1.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"8c9e2de85ac3414cb6369fc6dc96d2b2","linhaBlocoId":"0ce4fb2c883f4b2aa80c331a83280866","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"auditivos","categoria_label":"auditivos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_transceptor_coclear","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"dec497691b0a1a62f36118a0fa49883018494fd36e8daaa7df779e6392e1a4b2"},{"content_type":"escalpo","slug":"escalpos_bracos_egide","payload":{"id":"escalpos_bracos_egide","slug":"escalpos_bracos_egide","nome":"Braços Égide","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"Ⱥ 2.500","preco_qualificador":null,"descricao_curta":"Funcionam como um escudo médio integrado com 8 PD e cobertura parcial enquanto abertos.","descricao_longa":"---\n\n*Raro*\n\nUm par de braços reforçados abriga placas de metal kravita que podem se expandir sobre os antebraços. As placas possuem **8 PD**, resistência física e podem ser abertas ou recolhidas sem gastar PA durante seu turno.\n\nVocê também pode abrir as placas como parte da declaração de **Bloquear**, antes de realizar o teste.\n\nEnquanto as placas estiverem abertas e possuírem ao menos 1 PD:\n\n- Funcionam como um **escudo médio integrado**, concedendo **cobertura parcial (–1 de desvantagem)**.\n\n- Podem ser utilizadas para **Bloquear** mesmo com as mãos ocupadas.\n\n- Seguem normalmente as regras de PD, Resistência e impactos de escudos.\n\nAs placas permanecem abertas até serem recolhidas. Ao chegar a 0 PD, deixam de conceder cobertura e não podem ser usadas para **Bloquear** até recuperarem PD.\n\nOs Braços Égide recuperam todos os PD perdidos durante um descanso longo.\n\nPossuem 2 espaços para módulos de Braços Égide.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.500\n\n**Integridade:** –2\n\n### MÓDULOS DE BRAÇOS ÉGIDE\n\n---\n\n#### PLACAS REFORÇADAS\n\n#### TRAVAS INERCIAIS\n\nDados da lista de mercadorias:\n- Resumo: Funcionam como um escudo médio integrado com 8 PD e cobertura parcial enquanto abertos.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE BRAÇO"],"tipo_tabela":"Nome","campos":{"Nome":"Braços Égide","Resumo":"Funcionam como um escudo médio integrado com 8 PD e cobertura parcial enquanto abertos.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"1ca2b06bafdb46dfbcdebe3978c4a72b","linhaBlocoId":"b71d499894ff4ef28da73e71c6b2e496","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_braco","categoria_label":"de braco","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_bracos_egide","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"7c720540f24d5d9da654588f33da66cb55dd993bb66b7090dea54d0e6e5c9e49"},{"content_type":"escalpo","slug":"escalpos_bracos_gorila","payload":{"id":"escalpos_bracos_gorila","slug":"escalpos_bracos_gorila","nome":"Braços Gorila","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"Ⱥ 2.500","preco_qualificador":null,"descricao_curta":"Ampliam a força física e causam 1d10 de dano em ataques desarmados.","descricao_longa":"---\n\n*Raro*\n\nUm par de braços largos e pesados, movidos por musculatura sintética e pistões rúnicos. Seus ataques desarmados com os braços causam 1d10 de dano contundente. Você recebe +1 de vantagem em testes para erguer, arrastar, sustentar ou quebrar algo usando os braços.\n\nPossuem 2 espaços para módulos de Braços Gorila.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.500\n\n**Integridade:** –2\n\n### MÓDULOS DE BRAÇOS GORILA\n\n---\n\n#### ATUADORES INDUSTRIAIS\n\n#### JUNTAS DE IMPACTO\n\n#### PISTÕES DE SOBRECARGA\n\nDados da lista de mercadorias:\n- Resumo: Ampliam a força física e causam 1d10 de dano em ataques desarmados.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE BRAÇO"],"tipo_tabela":"Nome","campos":{"Nome":"Braços Gorila","Resumo":"Ampliam a força física e causam 1d10 de dano em ataques desarmados.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"1ca2b06bafdb46dfbcdebe3978c4a72b","linhaBlocoId":"d9cb67ea2b2d4deea31b04d2f8b3e9b1","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_braco","categoria_label":"de braco","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_bracos_gorila","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9e9d76935b0450c76c6cf9f7fb9748c1df9cba54af1676e8157d2a01e0a47eb3"},{"content_type":"escalpo","slug":"escalpos_bracos_lamina","payload":{"id":"escalpos_bracos_lamina","slug":"escalpos_bracos_lamina","nome":"Braços-Lâmina","raridade":"raro","raridade_label":"Raro","preco":2000,"preco_texto":"Ⱥ 2.000","preco_qualificador":null,"descricao_curta":"Possuem lâminas retráteis que causam 1d8 + 1 de dano e podem provocar Sangramento.","descricao_longa":"---\n\n*Raro*\n\nLâminas de metal kravita permanecem recolhidas nos antebraços e podem ser projetadas ou retraídas sem gastar PA. Funcionam como armas corpo a corpo leves que causam 1d8 + 1 de dano cortante ou perfurante, definido durante a instalação. Em um sucesso crítico, o alvo fica Sangrando.\n\nPossuem 2 espaços para módulos de Braços-Lâmina.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.000\n\n**Integridade:** –2\n\n### MÓDULOS DE BRAÇOS-LÂMINA\n\n---\n\n#### FIO MONOMOLECULAR\n\n#### LÂMINA SEGMENTADA\n\nDados da lista de mercadorias:\n- Resumo: Possuem lâminas retráteis que causam 1d8 + 1 de dano e podem provocar Sangramento.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.000","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE BRAÇO"],"tipo_tabela":"Nome","campos":{"Nome":"Braços-Lâmina","Resumo":"Possuem lâminas retráteis que causam 1d8 + 1 de dano e podem provocar Sangramento.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"1ca2b06bafdb46dfbcdebe3978c4a72b","linhaBlocoId":"eadfa45184e847c89a6a90acac651b71","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_braco","categoria_label":"de braco","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_bracos_lamina","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"b7eda1fd78077b957161a09d717ab9732dfe9477652d6fca2a3c8f0c28fe0548"},{"content_type":"escalpo","slug":"escalpos_bracos_polimorficos","payload":{"id":"escalpos_bracos_polimorficos","slug":"escalpos_bracos_polimorficos","nome":"Braços Polimórficos","raridade":"raro","raridade_label":"Raro","preco":2000,"preco_texto":"Ⱥ 2.000","preco_qualificador":null,"descricao_curta":"Reorganizam mãos e antebraços para formar ferramentas manuais simples.","descricao_longa":"---\n\n*Raro*\n\nAs mãos e os antebraços podem reorganizar sua estrutura para formar ferramentas manuais simples, como chaves, alicates, sondas, lâminas de corte e conectores. Isso não cria armas, munições, componentes consumíveis ou ferramentas especializadas completas.\n\nPossuem 2 espaços para módulos de Braços Polimórficos.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.000\n\n**Integridade:** –2\n\n### MÓDULOS DE BRAÇOS POLIMÓRFICOS\n\n---\n\n#### COMPARTIMENTO INTERNO\n\n#### ESTABILIZADOR DE PRECISÃO\n\n#### INTERFACE PALMAR\n\nDados da lista de mercadorias:\n- Resumo: Reorganizam mãos e antebraços para formar ferramentas manuais simples.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.000","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE BRAÇO"],"tipo_tabela":"Nome","campos":{"Nome":"Braços Polimórficos","Resumo":"Reorganizam mãos e antebraços para formar ferramentas manuais simples.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"1ca2b06bafdb46dfbcdebe3978c4a72b","linhaBlocoId":"56ec157301cf4411afc0d82a2394b112","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_braco","categoria_label":"de braco","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_bracos_polimorficos","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"f5043fec6135ae88515c88a5492d72e6fdb11ec22c2d802a8298ebf0f6132094"},{"content_type":"escalpo","slug":"escalpos_bracos_vetoriais","payload":{"id":"escalpos_bracos_vetoriais","slug":"escalpos_bracos_vetoriais","nome":"Braços Vetoriais","raridade":"raro","raridade_label":"Raro","preco":2200,"preco_texto":"Ⱥ 2.200","preco_qualificador":null,"descricao_curta":"Disparam cabos que permitem alcançar superfícies e se deslocar até elas.","descricao_longa":"---\n\n*Raro*\n\nCada antebraço abriga um cabo de metal flexível capaz de se fixar a uma superfície a até 10 m. Por 1 PA, você pode se deslocar em linha reta até um espaço adjacente ao ponto fixado. Os cabos também podem sustentar seu peso.\n\nPossuem 2 espaços para módulos de Braços Vetoriais.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.200\n\n**Integridade:** –2\n\n### MÓDULOS DE BRAÇOS VETORIAIS\n\n---\n\n#### CABO DUPLO\n\n#### GANCHO DE CAPTURA\n\n#### GUINCHO AMPLIADO\n\nDados da lista de mercadorias:\n- Resumo: Disparam cabos que permitem alcançar superfícies e se deslocar até elas.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.200","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE BRAÇO"],"tipo_tabela":"Nome","campos":{"Nome":"Braços Vetoriais","Resumo":"Disparam cabos que permitem alcançar superfícies e se deslocar até elas.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"1ca2b06bafdb46dfbcdebe3978c4a72b","linhaBlocoId":"2296909d8680474da810289c1eff92ed","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_braco","categoria_label":"de braco","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_bracos_vetoriais","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"520e27f42014ad9d923874c3169d2a7377e26d8aacd787ce85acf480bf1a4a08"},{"content_type":"escalpo","slug":"escalpos_pernas_de_aranha","payload":{"id":"escalpos_pernas_de_aranha","slug":"escalpos_pernas_de_aranha","nome":"Pernas de Aranha","raridade":"raro","raridade_label":"Raro","preco":2200,"preco_texto":"Ⱥ 2.200","preco_qualificador":null,"descricao_curta":"Permitem caminhar por paredes sem apoios ou testes em superfícies comuns.","descricao_longa":"---\n\n*Raro*\n\nMembros segmentados e pés aderentes permitem mover-se por paredes usando o deslocamento de Andar, sem necessidade de apoios ou testes em superfícies comuns. Você precisa manter ao menos três pontos de contato com a superfície.\n\nPossuem 2 espaços para módulos de Pernas de Aranha.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.200\n\n**Integridade:** –2\n\n### MÓDULOS DE PERNAS DE ARANHA\n\n---\n\n#### ADERÊNCIA INVERTIDA\n\n#### ÂNCORAS PLANTARES\n\n#### PASSOS DE SEDA\n\nDados da lista de mercadorias:\n- Resumo: Permitem caminhar por paredes sem apoios ou testes em superfícies comuns.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.200","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE PERNA"],"tipo_tabela":"Nome","campos":{"Nome":"Pernas de Aranha","Resumo":"Permitem caminhar por paredes sem apoios ou testes em superfícies comuns.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"4c58bf4d2e4f4a869279c9376b10dfbb","linhaBlocoId":"b4b589a67fc048aeb2b6b29d3edb3848","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_perna","categoria_label":"de perna","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_pernas_de_aranha","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"8d7d1952f1a85c9a46bf44b4bf62106d95da19bbea7ecedc96771e9064d62538"},{"content_type":"escalpo","slug":"escalpos_pernas_sismicas","payload":{"id":"escalpos_pernas_sismicas","slug":"escalpos_pernas_sismicas","nome":"Pernas Sísmicas","raridade":"raro","raridade_label":"Raro","preco":2300,"preco_texto":"Ⱥ 2.300","preco_qualificador":null,"descricao_curta":"Transformam o impacto de aterrissagens em descargas capazes de derrubar criaturas.","descricao_longa":"---\n\n*Raro*\n\nPernas pesadas acumulam o impacto de saltos e quedas. Por 2 PA, ao aterrissar de uma altura de pelo menos 2 m, você descarrega essa força contra o solo. Criaturas adjacentes devem Resistir, CD 7; em uma falha, ficam Caídas.\n\nPossuem 2 espaços para módulos de Pernas Sísmicas.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.300\n\n**Integridade:** –2\n\n### MÓDULOS DE PERNAS SÍSMICAS\n\n---\n\n#### AMORTECEDORES DE QUEDA\n\n#### ONDA DE CHOQUE\n\n#### PLACAS DE PROPAGAÇÃO\n\nDados da lista de mercadorias:\n- Resumo: Transformam o impacto de aterrissagens em descargas capazes de derrubar criaturas.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.300","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE PERNA"],"tipo_tabela":"Nome","campos":{"Nome":"Pernas Sísmicas","Resumo":"Transformam o impacto de aterrissagens em descargas capazes de derrubar criaturas.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.300"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"4c58bf4d2e4f4a869279c9376b10dfbb","linhaBlocoId":"d58aa8019c9b4d33ac7d8fbaac657c1b","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_perna","categoria_label":"de perna","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_pernas_sismicas","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"6700eee84459d4106f5c221ef1979801238072f7aed0ec99fc9d043b3b678797"},{"content_type":"escalpo","slug":"escalpos_pernas_vetoriais","payload":{"id":"escalpos_pernas_vetoriais","slug":"escalpos_pernas_vetoriais","nome":"Pernas Vetoriais","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"Ⱥ 2.500","preco_qualificador":null,"descricao_curta":"Aumentam o deslocamento e permitem atravessar vãos ou mudar de direção no ar.","descricao_longa":"---\n\n*Raro*\n\nTendões sintéticos armazenam a energia de cada passada e a redistribuem através de impulsores rúnicos nas articulações. Seu deslocamento de Andar aumenta em 2 m. Além disso, durante um deslocamento, você pode atravessar vãos e mudar de direção no ar, desde que termine o movimento sobre uma superfície capaz de sustentá-lo.\n\nPossuem 2 espaços para módulos de Pernas Vetoriais.\n\n**Espaços:** 3\n\n**Preço:** Ⱥ 2.500\n\n**Integridade:** –2\n\n### MÓDULOS DE PERNAS VETORIAIS\n\n---\n\n#### QUEDA CONTROLADA\n\n#### SOBRECARGA DE IMPULSO\n\n#### TENDÕES DE SALTO\n\nDados da lista de mercadorias:\n- Resumo: Aumentam o deslocamento e permitem atravessar vãos ou mudar de direção no ar.\n- Raridade: Raro\n- Espaços: 3\n- Preço: Ⱥ 2.500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS DE PERNA"],"tipo_tabela":"Nome","campos":{"Nome":"Pernas Vetoriais","Resumo":"Aumentam o deslocamento e permitem atravessar vãos ou mudar de direção no ar.","Raridade":"Raro","Espaços":"3","Preço":"Ⱥ 2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"4c58bf4d2e4f4a869279c9376b10dfbb","linhaBlocoId":"c180c79dd21640e5904bacf0b0bb8817","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"de_perna","categoria_label":"de perna","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_pernas_vetoriais","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"a89181470b3a81bcce0e7a0da6fd7d5975e24f7488ae304c0d7f617d25619c4c"},{"content_type":"escalpo","slug":"escalpos_armadura_reativa_subdermica_ars","payload":{"id":"escalpos_armadura_reativa_subdermica_ars","slug":"escalpos_armadura_reativa_subdermica_ars","nome":"Armadura Reativa Subdérmica (ARS)","raridade":"incomum","raridade_label":"Incomum","preco":1500,"preco_texto":"Ⱥ 1.500 por região","preco_qualificador":"por região","descricao_curta":"Projeta placas protetoras que concedem MIT à região instalada.","descricao_longa":"---\n\n*Incomum*\n\nUma malha tecnomágica implantada sob a pele se projeta em placas visíveis quando ativada. Cada instalação protege uma região. Ativar todas as regiões instaladas custa 1 PA, e a MIT perdida é restaurada durante um descanso longo.\n\n> ***Mitigação (MIT):** valor de redução aplicado contra o dano de ataques. Cada vez que um dano é absorvido, a MIT perde 1 ponto.*\n\n| Região | MIT | Preço | **Espaços** | Integridade |\n| --- | --- | --- | --- | --- |\n| Braços | 3 | Ⱥ 1.500 | 1 | –1 |\n| Cabeça | 2 | Ⱥ 1.500 | 1 | –1 |\n| Pernas | 3 | Ⱥ 1.500 | 1 | –1 |\n| Tronco | 4 | Ⱥ 1.500 | 1 | –1 |\n\nDados da lista de mercadorias:\n- Resumo: Projeta placas protetoras que concedem MIT à região instalada.\n- Raridade: Incomum\n- Espaços: 1\n- Preço: Ⱥ 1.500 por região","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS INTERNOS"],"tipo_tabela":"Nome","campos":{"Nome":"Armadura Reativa Subdérmica (ARS)","Resumo":"Projeta placas protetoras que concedem MIT à região instalada.","Raridade":"Incomum","Espaços":"1","Preço":"Ⱥ 1.500 por região"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"f2bd2c5e15fd4ec9abdc892281058bdb","linhaBlocoId":"78a313af94b94a779c7da2b283e9c3a2","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"internos","categoria_label":"internos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_armadura_reativa_subdermica_ars","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"3106fcaac5813e783fc0f58d8325de6e0bd900891f3cc2c1e6f289b2271366c5"},{"content_type":"escalpo","slug":"escalpos_beijo_da_morte","payload":{"id":"escalpos_beijo_da_morte","slug":"escalpos_beijo_da_morte","nome":"Beijo da Morte","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"Ⱥ 2.500","preco_qualificador":null,"descricao_curta":"Armazena uma dose de veneno que pode ser aplicada por contato com a boca.","descricao_longa":"---\n\n*Raro*\n\nUm reservatório ligado à boca pode recobrir os lábios, dentes ou língua com uma dose de veneno armazenada. O escalpo comporta uma dose por vez e pode aplicá-la ao beijar, morder ou manter contato direto com uma criatura.\n\nAo beijar ou morder um alvo, ele deve realizar um teste de **`Vigor`**,** **CD 7. Em falha, sofre o efeito do veneno aplicado.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 2.500\n\n**Integridade:** –2\n\n| **Veneno** | **Efeito** | **Raridade** | **Espaços** | **Preço (Ⱥ)** |\n| --- | --- | --- | --- | --- |\n| Tóxico | Causa 2d8 de dano tóxico. O alvo fica **`Envenenado`**. | Incomum | 1 (dose) | 100 |\n| Paralisante | O alvo fica **`Atordoado`** por 1d4 + 1 rodadas em falha de teste. Metade em sucesso (arredondado para baixo). | Incomum | 1 (dose) | 100 |\n| Sonífero | Adormece alvo por 1d4 +1 rodadas em falha. Metade em sucesso (arredondado para baixo). | Incomum | 1 (dose) | 100 |\n| Letal | 3d10 de dano físico imediato em falha, metade em sucesso (arredondado para baixo). | Incomum | 1 (dose) | 200 |\n\nDados da lista de mercadorias:\n- Resumo: Armazena uma dose de veneno que pode ser aplicada por contato com a boca.\n- Raridade: Raro\n- Espaços: 1\n- Preço: Ⱥ 2.500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS INTERNOS"],"tipo_tabela":"Nome","campos":{"Nome":"Beijo da Morte","Resumo":"Armazena uma dose de veneno que pode ser aplicada por contato com a boca.","Raridade":"Raro","Espaços":"1","Preço":"Ⱥ 2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"f2bd2c5e15fd4ec9abdc892281058bdb","linhaBlocoId":"28ce283760d7452da17b40c33e0da25e","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"internos","categoria_label":"internos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_beijo_da_morte","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"f3cdcae8cb7f6d03c917655f6cdeadfef3be36078124f3f2200d6f2d3fdc0887"},{"content_type":"escalpo","slug":"escalpos_biomonitor","payload":{"id":"escalpos_biomonitor","slug":"escalpos_biomonitor","nome":"Biomonitor","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"Ⱥ 2.500","preco_qualificador":null,"descricao_curta":"Recupera automaticamente 2d6 PV quando o usuário fica com metade ou menos dos PV máximos.","descricao_longa":"---\n\n*Raro*\n\nO escalpo monitora continuamente os sinais vitais e mantém uma carga de compostos regenerativos pronta para circulação.\n\nNa primeira vez no dia que sofrer dano e ficar com metade ou menos dos seus PV máximos, você recupera imediatamente 2d6 PV. O Biomonitor não pode ser ativado voluntariamente e volta a funcionar no início do dia seguinte.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 2.500\n\n**Integridade:** –2\n\nDados da lista de mercadorias:\n- Resumo: Recupera automaticamente 2d6 PV quando o usuário fica com metade ou menos dos PV máximos.\n- Raridade: Raro\n- Espaços: 1\n- Preço: Ⱥ 2.500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS INTERNOS"],"tipo_tabela":"Nome","campos":{"Nome":"Biomonitor","Resumo":"Recupera automaticamente 2d6 PV quando o usuário fica com metade ou menos dos PV máximos.","Raridade":"Raro","Espaços":"1","Preço":"Ⱥ 2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"f2bd2c5e15fd4ec9abdc892281058bdb","linhaBlocoId":"775d8990a8ba45a3b53663aae9382dc5","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"internos","categoria_label":"internos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_biomonitor","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"31a9d908f4e853d4863d775f9b67b0ac97c004af14550704a22ea113c6982057"},{"content_type":"escalpo","slug":"escalpos_catalisador_imunologico","payload":{"id":"escalpos_catalisador_imunologico","slug":"escalpos_catalisador_imunologico","nome":"Catalisador Imunológico","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"Ⱥ 2.500","preco_qualificador":null,"descricao_curta":"Concede 3d6 PV adicionais durante um descanso longo.","descricao_longa":"---\n\n*Raro*\n\nRunas implantadas junto à medula aceleram a reposição celular enquanto o corpo permanece em repouso. A recuperação deixa febre baixa, fome intensa e marcas luminosas temporárias sob a pele.\n\nDurante um descanso longo, você recupera 3d6 PV adicionais.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 2.500\n\n**Integridade:** –1\n\nDados da lista de mercadorias:\n- Resumo: Concede 3d6 PV adicionais durante um descanso longo.\n- Raridade: Raro\n- Espaços: 1\n- Preço: Ⱥ 2.500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS INTERNOS"],"tipo_tabela":"Nome","campos":{"Nome":"Catalisador Imunológico","Resumo":"Concede 3d6 PV adicionais durante um descanso longo.","Raridade":"Raro","Espaços":"1","Preço":"Ⱥ 2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"f2bd2c5e15fd4ec9abdc892281058bdb","linhaBlocoId":"3cb9dba3045d4fff99b77f2a652e04d9","tabelaTecnicaFonte":null},"vinculo