acao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"internos","categoria_label":"internos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_filtro_hematologico","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"39238cd96c3b0a122dadd9c40f7f24d6896e2c01ac99b804569de2a37da507bb"},{"content_type":"escalpo","slug":"escalpos_reserva_de_mana","payload":{"id":"escalpos_reserva_de_mana","slug":"escalpos_reserva_de_mana","nome":"Reserva de Mana","raridade":"raro","raridade_label":"Raro","preco":2500,"preco_texto":"Ⱥ 2.500","preco_qualificador":null,"descricao_curta":"Armazena 5 pontos adicionais de Mana após um descanso longo.","descricao_longa":"---\n\n*Raro*\n\nUm receptáculo rúnico alojado próximo ao centro do corpo acumula o excedente produzido durante o repouso e o mantém separado do fluxo natural do usuário.\n\nDepois de um descanso longo, o reservatório armazena 5 pontos de Mana. Essa Mana é gasta antes da sua reserva normal e desaparece no próximo descanso longo se não for utilizada.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 2.500\n\n**Integridade:** –2\n\nDados da lista de mercadorias:\n- Resumo: Armazena 5 pontos adicionais de Mana após um descanso longo.\n- Raridade: Raro\n- Espaços: 1\n- Preço: Ⱥ 2.500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS INTERNOS"],"tipo_tabela":"Nome","campos":{"Nome":"Reserva de Mana","Resumo":"Armazena 5 pontos adicionais de Mana após um descanso longo.","Raridade":"Raro","Espaços":"1","Preço":"Ⱥ 2.500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"f2bd2c5e15fd4ec9abdc892281058bdb","linhaBlocoId":"2e30627395d0425fb96a87473339beeb","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"ef