.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"internos","categoria_label":"internos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_reserva_pulmonar","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"a382376840614be347579b7289fa11d2dfbdc2691f21bb854f4f8678448cf0e1"},{"content_type":"escalpo","slug":"escalpos_olhos_de_cacador","payload":{"id":"escalpos_olhos_de_cacador","slug":"escalpos_olhos_de_cacador","nome":"Olhos de Caçador","raridade":"raro","raridade_label":"Raro","preco":2000,"preco_texto":"Ⱥ 2.000","preco_qualificador":null,"descricao_curta":"Ampliam o alcance da visão e facilitam perceber detalhes visuais.","descricao_longa":"---\n\n*Raro*\n\nOculares de foco variável ampliam detalhes e acompanham movimentos mínimos. Você identifica detalhes faciais a até 200 m e indivíduos a até 1 km, além de receber +1 em testes de **`Percepção`** ligados à visão.\n\nPossuem 2 espaços para módulos de Olhos de Caçador.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 2.000\n\n**Integridade:** –1\n\n### MÓDULOS DE OLHOS DE CAÇADOR\n\n---\n\n#### MATRIZ DE CONTRAFLUXO\n\n#### RASTREADOR OCULAR\n\n#### RÉPLICA RETINAL\n\nDados da lista de mercadorias:\n- Resumo: Ampliam o alcance da visão e facilitam perceber detalhes visuais.\n- Raridade: Raro\n- Espaços: 1\n- Preço: Ⱥ 2.000","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS ÓPTICOS"],"tipo_tabela":"Nome","campos":{"Nome":"Olhos de Caçador","Resumo":"Ampliam o alcance da visão e facilitam perceber detalhes visuais.","Raridade":"Raro","Espaços":"1","Preço":"Ⱥ 2.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"b88795ba8cdf48648a418438a9094e8b","linhaBlocoId":"8eb523d1375049f4ab59436932875214","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_a