goria":"opticos","categoria_label":"opticos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_olhos_de_vigilia","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"aa85329b99741942f5938498aa37c6ffa2023965ec51b987268d6383852f018a"},{"content_type":"escalpo","slug":"escalpos_olhos_projetores","payload":{"id":"escalpos_olhos_projetores","slug":"escalpos_olhos_projetores","nome":"Olhos Projetores","raridade":"incomum","raridade_label":"Incomum","preco":1200,"preco_texto":"Ⱥ 1.200","preco_qualificador":null,"descricao_curta":"Exibem interfaces na visão e projetam imagens visíveis no ambiente.","descricao_longa":"---\n\n*Incomum*\n\nOs olhos exibem interfaces digitais diretamente sobre a visão e projetam imagens armazenadas em um dispositivo conectado sobre uma superfície ou no ar a até 1 m. As projeções são visíveis para todos e não reproduzem áudio.\n\nPossuem 2 espaços para módulos de Olhos Projetores.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 1.200\n\n**Integridade:** –1\n\n### MÓDULOS DE OLHOS PROJETORES\n\n---\n\n#### EMISSÃO FOTÔNICA\n\n#### PROJEÇÃO AMPLIADA\n\n#### SOBREPOSIÇÃO ENGANOSA\n\nDados da lista de mercadorias:\n- Resumo: Exibem interfaces na visão e projetam imagens visíveis no ambiente.\n- Raridade: Incomum\n- Espaços: 1\n- Preço: Ⱥ 1.200","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS ÓPTICOS"],"tipo_tabela":"Nome","campos":{"Nome":"Olhos Projetores","Resumo":"Exibem interfaces na visão e projetam imagens visíveis no ambiente.","Raridade":"Incomum","Espaços":"1","Preço":"Ⱥ 1.200"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"b88795ba8cdf48648a418438a9094e8b","linhaBlocoId":"33d1da8550a74d77a6430981d1564921","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"opticos","categoria_label":"opticos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_olhos_projetores","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"4373616f1561c40112605e682b569603280daa1ce81eea88f4eac24d45294ef6"},{"content_type":"escalpo","slug":"escalpos_optica_runica","payload":{"id":"escalpos_optica_runica","slug":"escalpos_optica_runica","nome":"Óptica Rúnica","raridade":"muito_comum","raridade_label":"Muito Comum","preco":500,"preco_texto":"Ⱥ 500","preco_qualificador":null,"descricao_curta":"Projeta informações digitais diretamente sobre a visão do usuário.","descricao_longa":"---\n\n*Muito Comum*\n\nA Óptica Rúnica é um par de implantes oculares que substitui ou sobrepõe os olhos naturais. Cada globo é recoberto por uma fina malha de inscrições, invisível a olho nu, que permite a fusão entre visão biológica e informação digital.\n\nQualquer dado processado pelo *Processador Sináptico* ou por dispositivos externos conectados ao ID sináptico do usuário pode ser projetado diretamente em sua visão. Mensagens, mapas, interfaces, transmissões e hubs digitais surgem como parte natural da realidade observada.\n\nPossui 1 espaço para módulo de Óptica Rúnica.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 500\n\n**Integridade:** –1\n\n### MÓDULOS DE ÓPTICA RÚNICA\n\n---\n\n#### LEITOR CLANDESTINO DE RPI\n\nDados da lista de mercadorias:\n- Resumo: Projeta informações digitais diretamente sobre a visão do usuário.\n- Raridade: Muito Comum\n- Espaços: 1\n- Preço: Ⱥ 500","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS ÓPTICOS"],"tipo_tabela":"Nome","campos":{"Nome":"Óptica Rúnica","Resumo":"Projeta informações digitais diretamente sobre a visão do usuário.","Raridade":"Muito Comum","Espaços":"1","Preço":"Ⱥ 500"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"b88795ba8cdf48648a418438a9094e8b","linhaBlocoId":"ad70f795449a4a9f99ca84d1fbf44b6d","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"opticos","categoria_label":"opticos","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_optica_runica","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"9f45fb3e021f00ba1ff5fc02f364bb0219e537b4cd8abc407c169fcea05dd473"},{"content_type":"escalpo","slug":"escalpos_antecipador","payload":{"id":"escalpos_antecipador","slug":"escalpos_antecipador","nome":"Antecipador","raridade":"raro","raridade_label":"Raro","preco":2000,"preco_texto":"Ⱥ 2.000","preco_qualificador":null,"descricao_curta":"Permite gastar antecipadamente até 2 PA, descontados na próxima restauração.","descricao_longa":"---\n\n*Raro*\n\nRunas aceleram a transmissão dos impulsos nervosos até que o usuário experimente alguns segundos antes do restante do corpo conseguir acompanhá-lo.\n\nQuando quiser agir, desde que nenhuma outra ação ou efeito esteja sendo resolvido naquele momento, você pode ativar o *Antecipador* e gastar imediatamente até 2 PA. Isso pode ser feito dentro ou fora do seu turno. Os PA utilizados são descontados na próxima vez que seus PA forem restaurados.\n\nVocê não pode ativar o *Antecipador* enquanto ainda possuir PA a serem descontados. Ele não concede PA adicionais, apenas permite utilizá-los antecipadamente.\n\nPossui 1 espaço para módulo de Acelerador Sináptico.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 2.000\n\n**Integridade:** –2\n\n### MÓDULOS DO ACELERADOR SINÁPTICO\n\n---\n\n#### DILATAÇÃO TEMPORAL\n\n#### PAGAMENTO ESCALONADO\n\nDados da lista de mercadorias:\n- Resumo: Permite gastar antecipadamente até 2 PA, descontados na próxima restauração.\n- Raridade: Raro\n- Espaços: 1\n- Preço: Ⱥ 2.000","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["LISTA DE ESCALPOS","ESCALPOS NEURAIS"],"tipo_tabela":"Nome","campos":{"Nome":"Antecipador","Resumo":"Permite gastar antecipadamente até 2 PA, descontados na próxima restauração.","Raridade":"Raro","Espaços":"1","Preço":"Ⱥ 2.000"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"79dbcbd99c6a4de3b31d4730f837cf87","linhaBlocoId":"d1047fb7305a4a24bd93117dc3423d46","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"neurais","categoria_label":"neurais","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_antecipador","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"85997a5766be58758e1aa2137273465d28178af18ba2d8f5697556e14e882b8b"},{"content_type":"escalpo","slug":"escalpos_buffer_de_dor","payload":{"id":"escalpos_buffer_de_dor","slug":"escalpos_buffer_de_dor","nome":"Buffer de Dor","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"Ⱥ 1.000","preco_qualificador":null,"descricao_curta":"Permite ignorar temporariamente os efeitos de determinadas condições.","descricao_longa":"---\n\n*Incomum*\n\nUma vez por cena, ao receber Atordoado, Contundido, Queimando ou Sangrando, você pode ignorar os efeitos da condição até o final da cena. A condição não é removida e volta a afetá-lo quando a cena termina, caso ainda esteja presente.\n\n**Espaços:** 1\n\n**Preço:** Ⱥ 1.000\n\n**Integridade:** –2\n\nDados da lista de mercadorias:\n- Resumo: Permite ignorar temporariamente os efeitos de determinadas condições.\n- Raridade: Incomum\n- Es