ll,"descricao_curta":"Identidade superficial para verificações básicas.","descricao_longa":"*Comum*\n\nUma identidade superficial montada com dados reaproveitados, registros básicos e pouca atividade anterior. Permite realizar compras comuns, utilizar transporte público, acessar hospedagens simples e circular por sistemas que empreguem verificações básicas.\n\nProtocolos de Nível 2 ou superior encontram lacunas no histórico, registros incompatíveis ou dados insuficientes.\n\n**Espaços:** Não aplicável\n\n**Preço:** Ⱥ 300\n\nDados da lista de mercadorias:\n- Resumo: Identidade superficial para verificações básicas.\n- Raridade: Comum\n- Espaços: Não aplicável\n- Preço: Ⱥ 300","tags":["loja"],"dados_notion":{"pagina":"ESCALPOS","secao":["REGISTRO PESSOAL IMPERIAL (RPI)"],"tipo_tabela":"Nome","campos":{"Nome":"RPI Forjado (Nível 1)","Resumo":"Identidade superficial para verificações básicas.","Raridade":"Comum","Espaços":"Não aplicável","Preço":"Ⱥ 300"},"tabela_tecnica":null},"fonte_notion":{"paginaNotionId":"3d50a13635528061bda3c10fbb32cf04","paginaEditadaEm":"2026-10-08T22:20:00.000Z","tabelaBlocoId":"2966d645c4144ba3a28a4c054bae42cf","linhaBlocoId":"4ee1fe28c3e942a494ba670ce4d0175e","tabelaTecnicaFonte":null},"vinculos_sugeridos":null,"uso_manual":true,"payload_automacao":{"efeitos":[]},"status":"published","versao":"1.2.0","created_at":"2026-10-09","updated_at":"2026-10-11","categoria":"identidade","categoria_label":"identidade","custo_integridade":null,"slot":null,"requisitos":[],"estatisticas":{}},"id":"escalpo:escalpos_rpi_forjado_nivel_1","source_pack_id":"ruptura-notion-v12","source_pack_version":"1.2.0","version":"1.2.0","payload_hash":"4dfda34531b21fdc05c3ce40eb548d70d9042180e43a8ec8973ff8c1c9ed8abc"},{"content_type":"escalpo","slug":"escalpos_rpi_forjado_nivel_2","payload":{"id":"escalpos_rpi_forjado_nivel_2","slug":"escalpos_rpi_forjado_nivel_2","nome":"RPI Forjado (Nível 2)","raridade":"incomum","raridade_label":"Incomum","preco":1000,"preco_texto":"Ⱥ 1.0